  30 /// Reason carried by [`GraphError::ReleaseIntentStale`] (E124); real reasons are constructible only from this module.
  31 #[derive(Clone, Debug, PartialEq, Eq)]
  32 pub struct StaleReason {
  33     kind: StaleKind,
  34 }
  35 
  36 #[derive(Clone, Debug, PartialEq, Eq, thiserror::Error)]
  37 enum StaleKind {
  38     #[error("the re-observed Git commit trust evidence no longer matches what the intent was validated against")]
  39     TrustEvidenceChanged,
  40     #[error("the re-observed source identity no longer matches what the intent was validated against")]
  41     SourceIdentityChanged,
  42     #[error("the re-observed Git push remote no longer matches what the intent was validated against")]
  43     GitRemoteChanged,
  44     #[error("a fresh derivation from the current workspace no longer matches the intent that was validated")]
  45     IntentDiffersFromFreshDerivation,
  46 }
  47 
  48 impl std::fmt::Display for StaleReason {
  49     fn fmt(&self, formatter: &mut std::fmt::Formatter<'_>) -> std::fmt::Result {
  50         std::fmt::Display::fmt(&self.kind, formatter)
  51     }
  52 }
  53 
  54 impl StaleReason {
  55     fn trust_evidence_changed() -> Self {
  56         StaleReason {
  57             kind: StaleKind::TrustEvidenceChanged,
  58         }
  59     }
  60 
  61     fn source_identity_changed() -> Self {
  62         StaleReason {
  63             kind: StaleKind::SourceIdentityChanged,
  64         }
  65     }
  66 
  67     fn git_remote_changed() -> Self {
  68         StaleReason {
  69             kind: StaleKind::GitRemoteChanged,
  70         }
  71     }
  72 
  73     fn intent_differs_from_fresh_derivation() -> Self {
  74         StaleReason {
  75             kind: StaleKind::IntentDiffersFromFreshDerivation,
  76         }
  77     }
  78 }
