  80 /// The invocation data for one effect. This is deliberately graph-private:
  81 /// callers can inspect the serializable intent, but cannot substitute a new
  82 /// endpoint, tag target, or package directory at execution time.
  83 #[allow(dead_code)] // consumed by the durable executor batch
  84 #[derive(Debug)]
  85 enum PreparedOperation {
  86     RegistryPublish {
  87         package_dir: std::path::PathBuf,
  88         package_name: String,
  89         version: Version,
  90         registry: PreparedRegistryBinding,
  91         npm_access: Option<NpmAccess>,
  92         npm_tag: Option<String>,
  93     },
  94     Tag {
  95         name: TagName,
  96         target: CommitSha,
  97         annotation: String,
  98     },
  99     ForgeRelease {
 100         tag: TagName,
 101     },
 102 }
