 104 /// Credential-free, canonical registry routing. `endpoint` is populated only
 105 /// after parsing rejects userinfo, query, and fragments, so a later executor
 106 /// cannot recover credentials from this capability.
 107 #[allow(dead_code)] // consumed by the durable executor batch
 108 #[derive(Debug)]
 109 struct PreparedRegistryBinding {
 110     key: RegistryKey,
 111     endpoint: Option<String>,
 112     identity: RegistryBindingDigest,
 113 }
 114 
 115 /// Immutable, credential-free destination for Git effects. Its canonical
 116 /// digest is included in each tag-producing package fingerprint; the URL is
 117 /// retained only in the validated, non-serializable capability.
 118 #[derive(Clone, Debug, PartialEq, Eq)]
 119 struct PreparedGitRemote {
 120     endpoint: String,
 121     identity: SemanticInputDigest,
 122     github_repository: Option<GitHubRepository>,
 123 }
