 131     root: std::path::PathBuf,
 132     source: SourceIdentity,
 133     trust: GitCommitTrustEvidence,
 134     git_remote: Option<PreparedGitRemote>,
 135     _lock: ReleaseWorkspaceLock,
 136     operations: BTreeMap<ReleaseOperationId, PreparedOperation>,
 137 }
