 164 /// In-memory, non-transferable proof that an intent was rebuilt from a fresh
 165 /// workspace observation. It is intentionally neither cloneable nor serializable.
 166 pub struct ValidatedReleaseIntent<'a> {
 167     intent: ReleaseIntentV1,
 168     prepared: PreparedReleaseInputs,
 169     #[allow(dead_code)] // consumed by the durable execution coordinator
 170     runner: &'a dyn CommandRunner,
 171 }
 172 
 173 impl std::fmt::Debug for ValidatedReleaseIntent<'_> {
 174     fn fmt(&self, formatter: &mut std::fmt::Formatter<'_>) -> std::fmt::Result {
 175         formatter
 176             .debug_struct("ValidatedReleaseIntent")
 177             .field("intent", &self.intent)
 178             .finish_non_exhaustive()
 179     }
 180 }
