 182 impl ValidatedReleaseIntent<'_> {
 183     pub fn intent(&self) -> &ReleaseIntentV1 {
 184         &self.intent
 185     }
 186 
 187     #[allow(dead_code)] // consumed by the durable executor batch
 188     fn prepared(&self) -> &PreparedReleaseInputs {
 189         &self.prepared
 190     }
 191 
 192     /// Re-observes the held workspace immediately before an effect.
 193     #[allow(dead_code)] // consumed by the durable execution coordinator
 194     pub(crate) fn recheck_trust(&self) -> Result<(), GraphError> {
 195         let evidence =
 196             callisto_vcs::GitAccess::discover(&self.prepared.root, self.runner).observe_git_commit_trust()?;
 197         if evidence != self.prepared.trust || source_from_trust(&evidence) != self.prepared.source {
 198             return Err(GraphError::ReleaseIntentStale {
 199                 reason: StaleReason::trust_evidence_changed(),
 200             });
 201         }
 202         if self
 203             .prepared
 204             .git_remote
 205             .as_ref()
 206             .is_some_and(|expected| prepared_git_remote(&self.prepared.root, self.runner).as_ref() != Ok(expected))
 207         {
 208             return Err(GraphError::ReleaseIntentStale {
 209                 reason: StaleReason::git_remote_changed(),
 210             });
 211         }
 212         Ok(())
 213     }
 214 }
