 216 /// Builds a release intent from a fresh root-bound observation.
 217 pub fn build_release_intent<L: ProjectLocator, R: CommandRunner>(
 218     root: &Path,
 219     locator: &L,
 220     runner: &R,
 221     decision: &ReleaseDecisionV1,
 222     trust_profile: ExecutionTrustProfileV1,
 223 ) -> Result<ReleaseIntentV1, GraphError> {
 224     let root = canonical_root(root)?;
 225     let workspace = Workspace::load(root.clone(), locator, runner)?;
 226     let source = observe_source(&workspace, trust_profile)?;
 227     let intent = derive_release_intent(&workspace, decision, source.clone(), trust_profile)?;
 228 
 229     // Recheck after all input reads. A concurrent edit or checkout cannot be
 230     // authorized merely because it happened after the first check.
 231     if observe_source(&workspace, trust_profile)? != source {
 232         return Err(GraphError::ReleaseIntentStale {
 233             reason: StaleReason::source_identity_changed(),
 234         });
 235     }
 236     Ok(intent)
 237 }
