 297 fn canonical_root(root: &Path) -> Result<std::path::PathBuf, GraphError> {
 298     dunce::canonicalize(root).map_err(|error| GraphError::ReleaseInputRead {
 299         path: root.to_path_buf(),
 300         message: error.to_string(),
 301     })
 302 }
 303 
 304 fn observe_source<R: CommandRunner, D: DependencyResolver>(
 305     workspace: &Workspace<'_, R, D>,
 306     trust_profile: ExecutionTrustProfileV1,
 307 ) -> Result<SourceIdentity, GraphError> {
 308     Ok(source_from_trust(&observe_git_trust(workspace, trust_profile)?))
 309 }
 310 
 311 fn observe_git_trust<R: CommandRunner, D: DependencyResolver>(
 312     workspace: &Workspace<'_, R, D>,
 313     trust_profile: ExecutionTrustProfileV1,
 314 ) -> Result<GitCommitTrustEvidence, GraphError> {
 315     if !matches!(trust_profile, ExecutionTrustProfileV1::GitCommit) {
 316         return Err(ReleaseIntentError::UnsupportedTrustProfile.into());
 317     }
 318     let evidence = workspace.git_access().observe_git_commit_trust()?;
 319     if evidence.canonical_root() != workspace.root {
 320         return Err(GraphError::ReleasePreconditionUnmet {
 321             requirement: ReleasePreconditionRequirement::CanonicalRootMatchesWorkspace,
 322         });
 323     }
 324     if evidence.head_disposition() != GitHeadDisposition::Detached {
 325         return Err(GraphError::ReleasePreconditionUnmet {
 326             requirement: ReleasePreconditionRequirement::DetachedHead,
 327         });
 328     }
 329     Ok(evidence)
 330 }
 331 
 332 fn source_from_trust(evidence: &GitCommitTrustEvidence) -> SourceIdentity {
 333     SourceIdentity::GitCommit {
 334         sha: evidence.head().clone(),
 335     }
 336 }
