 873 fn derive_release_intent<R: CommandRunner, D: DependencyResolver>(
 874     workspace: &Workspace<'_, R, D>,
 875     decision: &ReleaseDecisionV1,
 876     source: SourceIdentity,
 877     trust_profile: ExecutionTrustProfileV1,
 878 ) -> Result<ReleaseIntentV1, GraphError> {
 879     let (snapshot, operations, _, _) = derive_release_inputs(workspace, decision, source)?;
 880     Ok(ReleaseIntentV1::new(
 881         decision.clone(),
 882         snapshot,
 883         trust_profile,
 884         operations,
 885         vec![],
 886     )?)
 887 }
