 889 fn derive_release_intent_with_prepared<R: CommandRunner, D: DependencyResolver>(
 890     workspace: &Workspace<'_, R, D>,
 891     decision: &ReleaseDecisionV1,
 892     source: SourceIdentity,
 893     trust_profile: ExecutionTrustProfileV1,
 894 ) -> Result<(ReleaseIntentV1, PreparedDerivation), GraphError> {
 895     let (snapshot, operations, prepared, git_remote) = derive_release_inputs(workspace, decision, source)?;
 896     let intent = ReleaseIntentV1::new(decision.clone(), snapshot, trust_profile, operations, vec![])?;
 897     Ok((
 898         intent,
 899         PreparedDerivation {
 900             operations: prepared,
 901             git_remote,
 902         },
 903     ))
 904 }
