1119 fn package_fingerprint<R: CommandRunner, D: DependencyResolver>(
1120     workspace: &Workspace<'_, R, D>,
1121     id: &ReleasePackageId,
1122     package: &callisto_model::Package,
1123     version: &Version,
1124     git_remote: Option<&PreparedGitRemote>,
1125 ) -> Result<SemanticInputDigest, GraphError> {
1126     let mut transcript = CanonicalTranscript::semantic_input_v1();
1127     transcript.push_str("package.id", &id.to_string());
1128     transcript.push_str("package.version", version.render());
1129     transcript.push_str(
1130         "package.releaseUnit",
1131         if crate::config::is_release_unit(&workspace.config, &package.id)? {
1132             "releasable"
1133         } else {
1134             "dev-only"
1135         },
1136     );
1137     for manifest in &package.manifests {
1138         let path = workspace.root.join(&manifest.path);
1139         let bytes = std::fs::read(&path).map_err(|error| GraphError::ReleaseInputRead {
1140             path: manifest.path.clone(),
1141             message: error.to_string(),
1142         })?;
1143         transcript.push_str("manifest.path", &manifest.path.display().to_string());
1144         transcript.push_str("manifest.bytes", digest_bytes("manifest", &bytes).as_str());
1145         transcript.push_str("manifest.role", &manifest_role_text(&manifest.role));
1146         transcript.push_str("manifest.format", manifest.format.ecosystem().prefix());
1147     }
1148     transcript.push_str("package.trigger", release_trigger_text(package.release_trigger));
1149     transcript.push_str(
1150         "package.tag",
1151         &package
1152             .tag_template
1153             .as_ref()
1154             .map_or_else(|| "default".to_string(), |tag| tag.as_str()),
1155     );
1156     for target in &package.publish_to {
1157         transcript.push_str("package.target", target_fingerprint(workspace, target)?.as_str());
1158     }
1159     if let Some(remote) = git_remote {
1160         transcript.push_str("package.gitRemote", remote.identity.as_str());
1161     }
1162     Ok(SemanticInputDigest::from_transcript(&transcript))
1163 }
