 239 /// Re-observes root, config, package discovery, manifests, Git evidence, and
 240 /// the exact operation DAG before creating an opaque authorization capability.
 241 pub fn validate_release_intent<'a, L: ProjectLocator, R: CommandRunner>(
 242     root: &Path,
 243     locator: &L,
 244     runner: &'a R,
 245     received: ReleaseIntentV1,
 246 ) -> Result<ValidatedReleaseIntent<'a>, GraphError> {
 247     validate_release_intent_with_state_directory(root, locator, runner, None, received)
 248 }
 249 
 250 /// Validates an intent while placing its workspace lock under an explicit
 251 /// caller-owned state directory.
 252 ///
 253 /// CI callers that supply an explicit durable state file must use its parent
 254 /// here as well.  Otherwise validation would still depend on the runner's
 255 /// implicit platform state location, defeating hermetic job handoff.
 256 pub fn validate_release_intent_with_state_directory<'a, L: ProjectLocator, R: CommandRunner>(
 257     root: &Path,
 258     locator: &L,
 259     runner: &'a R,
 260     state_directory: Option<&Path>,
 261     received: ReleaseIntentV1,
 262 ) -> Result<ValidatedReleaseIntent<'a>, GraphError> {
 263     let root = canonical_root(root)?;
 264     let workspace = Workspace::load(root.clone(), locator, runner)?;
 265     let initial_trust = observe_git_trust(&workspace, received.trust_profile)?;
 266     let lock = ReleaseWorkspaceLock::acquire(&root, state_directory)?;
 267     let trust = observe_git_trust(&workspace, received.trust_profile)?;
 268     if trust != initial_trust {
 269         return Err(GraphError::ReleaseIntentStale {
 270             reason: StaleReason::trust_evidence_changed(),
 271         });
 272     }
 273     let source = source_from_trust(&trust);
 274     let (expected, prepared) =
 275         derive_release_intent_with_prepared(&workspace, &received.decision, source.clone(), received.trust_profile)?;
 276     let final_trust = observe_git_trust(&workspace, received.trust_profile)?;
 277     if expected != received || final_trust != trust {
 278         return Err(GraphError::ReleaseIntentStale {
 279             reason: StaleReason::intent_differs_from_fresh_derivation(),
 280         });
 281     }
 282 
 283     Ok(ValidatedReleaseIntent {
 284         prepared: PreparedReleaseInputs {
 285             root,
 286             source,
 287             trust: final_trust,
 288             git_remote: prepared.git_remote,
 289             _lock: lock,
 290             operations: prepared.operations,
 291         },
 292         intent: received,
 293         runner,
 294     })
 295 }
