 338 impl ValidatedReleaseIntent<'_> {
 339     /// Dispatches exactly one graph-private operation prepared during fresh
 340     /// validation. This is intentionally the only production effect path: it
 341     /// never accepts a path, endpoint, tag, package name, or version from a
 342     /// caller.
 343     pub(crate) fn dispatch_prepared(
 344         &self,
 345         permit: &ApplyPermit,
 346         id: &ReleaseOperationId,
 347     ) -> Result<OperationOutcome, GraphError> {
 348         let operation = self
 349             .prepared
 350             .operations
 351             .get(id)
 352             .ok_or_else(|| GraphError::ReleaseInvariant {
 353                 detail: format!("dispatch_prepared: no prepared operation for `{id:?}`"),
 354             })?;
 355         match operation {
 356             PreparedOperation::RegistryPublish { .. } => self.dispatch_registry(permit, id, operation),
 357             PreparedOperation::Tag {
 358                 name,
 359                 target,
 360                 annotation,
 361             } => self.dispatch_tag(permit, name, target, annotation),
 362             PreparedOperation::ForgeRelease { tag } => self.dispatch_forge_release(tag),
 363         }
 364     }
 365 
 366     fn dispatch_registry(
 367         &self,
 368         _permit: &ApplyPermit,
 369         id: &ReleaseOperationId,
 370         prepared: &PreparedOperation,
 371     ) -> Result<OperationOutcome, GraphError> {
 372         let PreparedOperation::RegistryPublish {
 373             package_dir,
 374             package_name,
 375             version,
 376             registry,
 377             npm_access,
 378             npm_tag,
 379         } = prepared
 380         else {
 850     let malformed = |detail: String| GraphError::ReleaseCommand {
 851         program: program.to_string(),
 852         args: args.iter().map(ToString::to_string).collect(),
 853         failure: CommandFailure::MalformedOutput { detail },
 854     };
 855     let (headers, body) = stdout
 856         .rsplit_once("\r\n\r\n")
 857         .or_else(|| stdout.rsplit_once("\n\n"))
 858         .ok_or_else(|| malformed("response has no blank line separating headers from body".to_string()))?;
 859     let status_line = headers
 860         .lines()
 861         .rev()
 862         .find(|line| line.trim_end_matches('\r').starts_with("HTTP/"))
 863         .ok_or_else(|| malformed("response headers contain no HTTP status line".to_string()))?;
 864     let status = status_line
 865         .split_whitespace()
 866         .nth(1)
 867         .ok_or_else(|| malformed(format!("HTTP status line has no status code: {status_line:?}")))?
 868         .parse::<u16>()
 869         .map_err(|error| malformed(format!("HTTP status code is not a valid number: {error}")))?;
 870     Ok((status, body))
 871 }
