 906 fn derive_release_inputs<R: CommandRunner, D: DependencyResolver>(
 907     workspace: &Workspace<'_, R, D>,
 908     decision: &ReleaseDecisionV1,
 909     source: SourceIdentity,
 910 ) -> Result<DerivedReleaseInputs, GraphError> {
 911     super::release_decision::validate_release_units(workspace, decision)?;
 912     let mut package_inputs = Vec::new();
 913 
 914     let mut selected = BTreeMap::new();
 915     let mut package_ids = BTreeMap::<callisto_model::PackageId, Vec<ReleasePackageId>>::new();
 916     for package in workspace.graph.packages() {
 917         if !crate::config::is_release_unit(&workspace.config, &package.id)? {
 918             continue;
 919         }
 920         // One canonical manifest per ecosystem is the expected shape, but
 921         // dedup defensively -- `release_package_ids` maps every canonical
 922         // manifest, and two manifests sharing an ecosystem would otherwise
 923         // select/push the same identity twice.
 924         for id in super::release_decision::release_package_ids(package)?
 925             .into_iter()
 926             .collect::<BTreeSet<_>>()
 927         {
 928             if let Some(entry) = decision.entries.iter().find(|entry| entry.package == id) {
 929                 selected.insert(id.clone(), (package, entry.target_version.clone()));
 930                 package_ids.entry(package.id.clone()).or_default().push(id);
 931             }
 932         }
 933     }
 934     for entry in &decision.entries {
 935         let id = &entry.package;
 936         if !selected.contains_key(id) {
 937             return Err(GraphError::ReleasePackageNotSelected { package: id.clone() });
 938         }
 939     }
 940 
 941     let requires_git_remote = selected.values().any(|(package, _)| {
 942         package
 943             .publish_to
 944             .iter()
 945             .any(|target| !matches!(target, PublishTarget::None))
 946     });
 947     let git_remote = requires_git_remote
 948         .then(|| prepared_git_remote(&workspace.root, workspace.runner))
 949         .transpose()?;
 950 
 951     let mut operations = BTreeMap::<ReleaseOperationId, ReleaseOperation>::new();
 952     let mut prepared = BTreeMap::<ReleaseOperationId, PreparedOperation>::new();
 953     let mut publishes_by_package = BTreeMap::<ReleasePackageId, Vec<ReleaseOperationId>>::new();
 954     let mut tag_by_package = BTreeMap::<ReleasePackageId, ReleaseOperationId>::new();
 955 
 956     // First construct leaves so dependency prerequisites can refer only to
 957     // exact selected release identities, never PackageId's wildcard matcher.
 958     for (id, (package, version)) in &selected {
 959         let produces_tag = package
 960             .publish_to
 961             .iter()
 962             .any(|target| !matches!(target, PublishTarget::None));
 963         let fingerprint = package_fingerprint(
 964             workspace,
 965             id,
 966             package,
 967             version,
 968             produces_tag.then_some(git_remote.as_ref()).flatten(),
 969         )?;
 970         package_inputs.push(ReleasePackageInputV1 {
 971             package: id.clone(),
 972             fingerprint,
 973         });
 974 
 975         let mut publishes = Vec::new();
 976         for target in &package.publish_to {
 977             if target.ecosystem() == Some(id.ecosystem()) {
 978                 let registry_key = target.registry_key().expect("registry target has registry key");
 979                 let binding = prepared_registry_binding(workspace, target)?;
 980                 let operation = ReleaseOperation::registry_publish(
 981                     id.clone(),
 982                     version.clone(),
 983                     RegistryBindingId::new(registry_key.as_str(), binding.identity.clone())?,
 984                     Vec::new(),
 985                 )?;
 986                 // A durable registry operation must have one exact endpoint
 987                 // binding. The model-level operation identity currently has
 988                 // only a registry key, so reject a second target that would
 989                 // collapse to the same operation until the typed binding
 990                 // identity is added there.
 991                 if prepared.contains_key(operation.id()) {
 992                     return Err(GraphError::ReleaseSelectionInvalid {
 993                         package: id.clone(),
 994                         reason: ReleaseSelectionInvalidReason::DuplicateRegistryTarget,
 995                     });
 996                 }
 997                 prepared.insert(
 998                     operation.id().clone(),
 999                     PreparedOperation::RegistryPublish {
1000                         package_dir: package_dir(package)?,
1001                         package_name: id.name().to_string(),
1002                         version: version.clone(),
1003                         registry: binding,
1004                         npm_access: match target {
1005                             PublishTarget::Npm { access, .. } => *access,
1006                             _ => None,
1007                         },
1008                         npm_tag: matches!(target, PublishTarget::Npm { .. })
1009                             .then(|| version.is_prerelease().then_some("next".to_string()))
1010                             .flatten(),
1011                     },
1012                 );
1013                 publishes.push(operation.id().clone());
1014                 operations.insert(operation.id().clone(), operation);
1015             }
1016         }
1017         publishes.sort();
1018         publishes_by_package.insert(id.clone(), publishes);
1019     }
1020 
1021     // Replace each publish leaf with prerequisites from selected dependency
1022     // packages. This preserves the existing publish semantics: runtime,
1023     // build, optional, and dev dependencies must exist before publish.
1024     for (id, (package, _)) in &selected {
1025         let mut prerequisites = BTreeSet::new();
1026         for edge in workspace.graph.dependencies_of(&package.id) {
1027             if !matches!(
1028                 edge.kind,
1029                 DepKind::Runtime | DepKind::Build | DepKind::Optional | DepKind::Dev
1030             ) {
1031                 continue;
1032             }
1033             for dependency_release_id in package_ids.get(&edge.to).into_iter().flatten() {
1034                 prerequisites.extend(
1035                     publishes_by_package
1036                         .get(dependency_release_id)
1037                         .into_iter()
1038                         .flatten()
1039                         .cloned(),
1040                 );
1041             }
1042         }
1043         for publish_id in publishes_by_package.get(id).into_iter().flatten() {
1044             let operation = operations.get(publish_id).expect("publish operation was constructed");
1045             let replacement = ReleaseOperation::new(operation.id().clone(), prerequisites.iter().cloned().collect())?;
1046             operations.insert(publish_id.clone(), replacement);
1047         }
1048     }
1049 
1050     for (id, (package, version)) in &selected {
1051         if !package
1052             .publish_to
1053             .iter()
1054             .any(|target| !matches!(target, PublishTarget::None))
1055         {
1056             continue;
1057         }
1058         let tag = ReleaseOperation::tag(
1059             id.clone(),
1060             version.clone(),
1061             publishes_by_package.get(id).cloned().unwrap_or_default(),
1062         )?;
1063         let tag_name = package
1064             .tag_template
1065             .clone()
1066             .unwrap_or_else(|| callisto_model::TagTemplate::default_for(&package.id))
1067             .render(version);
1068         let target = match &source {
1069             SourceIdentity::GitCommit { sha } => sha.clone(),
1070             SourceIdentity::HermeticContent { .. } => {
1071                 return Err(GraphError::UnsupportedRelease {
1072                     feature: UnsupportedReleaseFeature::SourceIdentity,
1073                 })
1074             }
1075         };
1076         prepared.insert(
1077             tag.id().clone(),
1078             PreparedOperation::Tag {
1079                 annotation: format!("Release {tag_name}"),
1080                 name: tag_name,
1081                 target,
1082             },
1083         );
1084         tag_by_package.insert(id.clone(), tag.id().clone());
1085         operations.insert(tag.id().clone(), tag);
1086     }
1087     for (id, (package, version)) in &selected {
1088         if package
1089             .publish_to
1090             .iter()
1091             .any(|target| matches!(target, PublishTarget::GitHubRelease))
1092         {
1093             let tag = tag_by_package.get(id).expect("release point has tag").clone();
1094             let operation = ReleaseOperation::forge_release(id.clone(), version.clone(), vec![tag])?;
1095             let tag = match prepared.get(operation.prerequisites().first().expect("forge release has tag")) {
1096                 Some(PreparedOperation::Tag { name, .. }) => name.clone(),
1097                 _ => {
1098                     return Err(GraphError::ReleaseInvariant {
1099                         detail: format!(
1100                             "forge release `{:?}` prerequisite is not a prepared Tag operation",
1100                             "forge release `{:?}` prerequisite is not a prepared Tag operation",
1101                             operation.id()
1102                         ),
1103                     })
1104                 }
1105             };
1106             prepared.insert(operation.id().clone(), PreparedOperation::ForgeRelease { tag });
1107             operations.insert(operation.id().clone(), operation);
1108         }
1109     }
1110 
1111     Ok((
1112         ReleaseInputSnapshotV1::new(source, package_inputs)?,
1113         canonical_operation_order(operations)?,
1114         prepared,
1115         git_remote,
1116     ))
1117 }
