1193 fn canonical_operation_order(
1194     operations: BTreeMap<ReleaseOperationId, ReleaseOperation>,
1195 ) -> Result<Vec<ReleaseOperation>, GraphError> {
1196     let mut remaining: BTreeMap<_, usize> = operations
1197         .iter()
1198         .map(|(id, operation)| (id.clone(), operation.prerequisites().len()))
1199         .collect();
1200     let mut dependents = BTreeMap::<ReleaseOperationId, Vec<ReleaseOperationId>>::new();
1201     for (id, operation) in &operations {
1202         for prerequisite in operation.prerequisites() {
1203             dependents.entry(prerequisite.clone()).or_default().push(id.clone());
1204         }
1205     }
1206     let mut ready: BTreeSet<_> = remaining
1207         .iter()
1208         .filter_map(|(id, count)| (*count == 0).then_some(id.clone()))
1209         .collect();
1210     let mut ordered = Vec::with_capacity(operations.len());
1211     while let Some(id) = ready.pop_first() {
1212         ordered.push(operations.get(&id).expect("known operation").clone());
1213         for dependent in dependents.get(&id).into_iter().flatten() {
1214             let count = remaining.get_mut(dependent).expect("known operation");
1215             *count -= 1;
1216             if *count == 0 {
1217                 ready.insert(dependent.clone());
1218             }
1219         }
1220     }
1221     if ordered.len() != operations.len() {
1222         return Err(GraphError::ReleaseInvariant {
1223             detail: "release operation DAG contains a cycle: topological sort could not order every operation"
1224                 .to_string(),
1225         });
1226     }
1227     Ok(ordered)
1228 }
