3004     fn digest_intent(
3005         release: &ProductReleaseId,
3006         source: &CommitSha,
3007         destination: &ReleaseDestinationBinding,
3008         approved: &[ApprovedRegistryPackage],
3009         operations: &[ReleaseOperation],
3010         slots: &[ReleaseArtifactSlot],
3011     ) -> IntentDigest {
3012         let mut transcript = CanonicalTranscript::intent_v1();
3013         transcript.push_str("successor.schema", "1");
3014         transcript.push_str("product", release.product.as_str());
3015         transcript.push_str("product.version", release.version.render());
3016         transcript.push_str("source", source.as_str());
3017         transcript.push_bytes(
3018             "destination",
3019             serde_json::to_vec(destination).expect("closed destination binding serializes"),
3020         );
3021         for registry in approved {
3022             transcript.push_bytes(
3023                 "approved-registry",
3024                 serde_json::to_vec(registry).expect("closed roster serializes"),
3025             );
3026         }
3027         for operation in operations {
3028             transcript.push_bytes(
3029                 "operation",
3030                 serde_json::to_vec(&operation.id).expect("closed operation serializes"),
3031             );
3032             for prerequisite in &operation.prerequisites {
3033                 transcript.push_bytes(
3034                     "prerequisite",
3035                     serde_json::to_vec(prerequisite).expect("closed operation serializes"),
3036                 );
3037             }
3038         }
3039         for slot in slots {
3040             transcript.push_bytes("slot", serde_json::to_vec(slot).expect("closed slot serializes"));
3041         }
3042         IntentDigest::from_transcript(&transcript)
3043     }
