3066     impl ValidatedPayloadEntries {
3067         fn new(intent: &ReleaseIntent, mut entries: Vec<ReleaseArtifactEntry>) -> Result<Self, SuccessorError> {
3068             entries.sort_by(|left, right| left.slot.cmp(&right.slot));
3069             let expected = intent.slots.iter().filter(|slot| {
3070                 matches!(
3071                     slot,
3072                     ReleaseArtifactSlot::RegistryPackage { .. } | ReleaseArtifactSlot::ProductAsset { .. }
3073                 )
3074             });
3075             if entries.windows(2).any(|pair| pair[0].slot == pair[1].slot)
3076                 || entries.iter().map(|entry| &entry.slot).ne(expected)
3077                 || entries.iter().any(|entry| {
3078                     entry.source_commit != intent.source_commit || entry.provenance != *entry.slot.policy()
3079                 })
3080             {
3081                 return Err(SuccessorError::MismatchedManifest);
3082             }
3083             Ok(Self {
3084                 intent_digest: intent.digest.clone(),
3085                 source_commit: intent.source_commit.clone(),
3086                 slots: entries.iter().map(|entry| entry.slot.clone()).collect(),
3087                 entries,
3088             })
3089         }
