3091         fn validate_for(&self, intent: &ReleaseIntent) -> Result<(), SuccessorError> {
3092             let expected = intent.slots.iter().filter(|slot| {
3093                 matches!(
3094                     slot,
3095                     ReleaseArtifactSlot::RegistryPackage { .. } | ReleaseArtifactSlot::ProductAsset { .. }
3096                 )
3097             });
3098             if self.intent_digest != intent.digest
3099                 || self.source_commit != intent.source_commit
3100                 || self.slots.iter().ne(expected)
3101             {
3102                 return Err(SuccessorError::MismatchedPayloadIntent);
3103             }
3104             Ok(())
3105         }
3106     }
