3126     impl ReleaseArtifactManifest {
3127         const SCHEMA_VERSION: u8 = 1;
3128 
3129         fn complete(intent: &ReleaseIntent, payloads: &ValidatedPayloadEntries) -> Result<Self, SuccessorError> {
3130             payloads.validate_for(intent)?;
3131             let metadata = ReleaseDistributionMetadataV1::from_payloads(intent, payloads)?;
3132             let metadata_bytes = metadata.canonical_json();
3133             let metadata_slot = intent
3134                 .slots
3135                 .iter()
3136                 .find(|slot| matches!(slot, ReleaseArtifactSlot::ReleaseMetadata { .. }))
3137                 .expect("closed intent has metadata slot")
3138                 .clone();
3139             let metadata_entry = generated_entry(intent, metadata_slot, metadata_bytes);
3140             let checksum_bytes = canonical_checksum_bytes(&payloads.entries, &metadata_entry)?;
3141             let checksum_slot = intent
3142                 .slots
3143                 .iter()
3144                 .find(|slot| matches!(slot, ReleaseArtifactSlot::ChecksumManifest { .. }))
3145                 .expect("closed intent has checksum slot")
3146                 .clone();
3147             let checksum_entry = generated_entry(intent, checksum_slot, checksum_bytes);
3148             let mut entries = payloads.entries.clone();
3149             entries.extend([metadata_entry, checksum_entry]);
3150             entries.sort_by(|left, right| left.slot.cmp(&right.slot));
3151             validate_complete_entries(intent, &entries)?;
3152             Ok(Self {
3153                 schema_version: Self::SCHEMA_VERSION,
3154                 intent_digest: intent.digest.clone(),
3155                 source_commit: intent.source_commit.clone(),
3156                 entries,
3157             })
3158         }
3159 
3160         fn validate_for_intent(&self, intent: &ReleaseIntent) -> Result<(), SuccessorError> {
3161             if self.schema_version != Self::SCHEMA_VERSION
3162                 || self.intent_digest != intent.digest
3163                 || self.source_commit != intent.source_commit
3164             {
3165                 return Err(SuccessorError::MismatchedManifest);
3166             }
3167             let payloads = ValidatedPayloadEntries::new(
3168                 intent,
3169                 self.entries
3170                     .iter()
3171                     .filter(|entry| {
3172                         matches!(
3173                             entry.slot,
3174                             ReleaseArtifactSlot::RegistryPackage { .. } | ReleaseArtifactSlot::ProductAsset { .. }
3175                         )
3176                     })
3177                     .cloned()
3178                     .collect(),
3179             )?;
3180             (*self == Self::complete(intent, &payloads)?)
3181                 .then_some(())
3182                 .ok_or(SuccessorError::MismatchedManifest)
3183         }
3184     }
