3186     fn generated_entry(intent: &ReleaseIntent, slot: ReleaseArtifactSlot, bytes: Vec<u8>) -> ReleaseArtifactEntry {
3187         ReleaseArtifactEntry {
3188             digest: ArtifactDigest::from_bytes(&bytes),
3189             byte_length: bytes.len() as u64,
3190             source_commit: intent.source_commit.clone(),
3191             provenance: slot.policy().clone(),
3192             slot,
3193         }
3194     }
