3196     fn validate_complete_entries(
3197         intent: &ReleaseIntent,
3198         entries: &[ReleaseArtifactEntry],
3199     ) -> Result<(), SuccessorError> {
3200         if entries.windows(2).any(|pair| pair[0].slot == pair[1].slot)
3201             || entries.iter().map(|entry| &entry.slot).ne(intent.slots.iter())
3202             || entries
3203                 .iter()
3204                 .any(|entry| entry.source_commit != intent.source_commit || entry.provenance != *entry.slot.policy())
3205         {
3206             return Err(SuccessorError::MismatchedManifest);
3207         }
3208         Ok(())
3209     }
