 128     /// Extracts every `code(E<digits>)` occurrence from `text`, in order of appearance. Deliberately
 129     /// a hand-rolled scan rather than a `regex` dependency — the pattern is fixed-shape and simple
 130     /// enough that adding a whole crate dependency for it isn't warranted.
 131     fn extract_diagnostic_codes(text: &str) -> Vec<String> {
 132         let mut codes = Vec::new();
 133         let mut rest = text;
 134         while let Some(start) = rest.find("code(E") {
 135             let after_marker = &rest[start + "code(".len()..];
 136             let digit_end = after_marker
 137                 .find(|c: char| !c.is_ascii_digit() && c != 'E')
 138                 .unwrap_or(after_marker.len());
 139             let candidate = &after_marker[..digit_end];
 140             // `code(` is also used for things like `code(callisto::foo)` in test-double
 141             // diagnostics elsewhere in the workspace (out of scope for this scan, since those
 142             // files aren't in `DIAGNOSTIC_CODE_SOURCE_FILES`) -- guard here anyway so a stray
 143             // non-numeric match can't silently produce a bogus "code".
 144             if candidate.len() > 1 && candidate[1..].chars().all(|c| c.is_ascii_digit()) {
 145                 codes.push(candidate.to_string());
 146             }
 147             rest = &after_marker[digit_end..];
 148         }
 149         codes
 150     }
