3263     impl ReleaseDistributionMetadataV1 {
3264         const SCHEMA_VERSION: u8 = 1;
3265 
3266         fn from_payloads(intent: &ReleaseIntent, validated: &ValidatedPayloadEntries) -> Result<Self, SuccessorError> {
3267             validated.validate_for(intent)?;
3268             let mut payloads = validated
3269                 .entries
3270                 .iter()
3271                 .filter_map(|entry| match &entry.slot {
3272                     ReleaseArtifactSlot::ProductAsset {
3273                         target,
3274                         file_name,
3275                         provenance_policy,
3276                         ..
3277                     } => Some(MetadataPayload {
3278                         target: *target,
3279                         file_name: file_name.clone(),
3280                         digest: entry.digest.clone(),
3281                         byte_length: entry.byte_length,
3282                         provenance_policy: provenance_policy.clone(),
3283                     }),
3284                     _ => None,
3285                 })
3286                 .collect::<Vec<_>>();
3287             payloads.sort_by_key(|payload| payload.target);
3288             let verification_policy = payloads
3289                 .first()
3290                 .expect("closed product roster contains product payloads")
3291                 .provenance_policy
3292                 .clone();
3293             let metadata = Self {
3294                 schema_version: Self::SCHEMA_VERSION,
3295                 product_release: intent.product_release.clone(),
3296                 intent_digest: intent.digest.clone(),
3297                 source_commit: intent.source_commit.clone(),
3298                 payloads,
3299                 verification_policy,
3300             };
3301             metadata.validate()?;
3302             Ok(metadata)
3303         }
3304 
3305         fn canonical_json(&self) -> Vec<u8> {
3306             serde_json::to_vec(self).expect("closed metadata serializes")
3307         }
3308 
3309         fn validate(&self) -> Result<(), SuccessorError> {
3310             if self.schema_version != Self::SCHEMA_VERSION
3311                 || self.payloads.len() != ProductTarget::ALL.len()
3312                 || self.payloads.windows(2).any(|pair| pair[0].target >= pair[1].target)
3313                 || !ProductTarget::ALL.iter().zip(&self.payloads).all(|(target, payload)| {
3314                     target == &payload.target && is_safe_artifact_component(&payload.file_name)
3315                 })
3316                 || self
3317                     .payloads
3318                     .iter()
3319                     .any(|payload| payload.provenance_policy.validate().is_err())
3320                 || self.verification_policy.validate().is_err()
3321                 || self
3322                     .payloads
3323                     .iter()
3324                     .any(|payload| payload.provenance_policy != self.verification_policy)
3325             {
3326                 return Err(SuccessorError::InvalidMetadata);
3327             }
3328             Ok(())
3329         }
3330     }
