2787         destination: &ReleaseDestinationBinding,
2788         approved: &[ApprovedRegistryPackage],
2789         slots: &[ReleaseArtifactSlot],
2790     ) -> Result<(), SuccessorError> {
2791         if slots.windows(2).any(|pair| pair[0] == pair[1]) {
2792             return Err(SuccessorError::DuplicateSlot);
2793         }
2794         for slot in slots {
2795             slot.validate(release)?;
2796         }
2797         if approved.iter().any(|entry| {
2798             destination.registry_for(entry.package.ecosystem()).ok() != Some(&entry.registry)
2799         }) {
2800             return Err(SuccessorError::RegistryDestinationMismatch);
2801         }
2802         let registry_slots = slots
2803             .iter()
2804             .filter_map(|slot| match slot {
2805                 ReleaseArtifactSlot::RegistryPackage {
2806                     package,
2807                     version,
2808                     registry,
2809                     format,
2810                     ..
2811                 } if version == &release.version => Some(ApprovedRegistryPackage {
2812                     package: package.clone(),
2813                     registry: registry.clone(),
2814                     format: format.clone(),
2815                 }),
2816                 _ => None,
2817             })
2818             .collect::<BTreeSet<_>>();
2819         if registry_slots.len()
2820             != slots
2821                 .iter()
2822                 .filter(|slot| matches!(slot, ReleaseArtifactSlot::RegistryPackage { .. }))
2823                 .count()
2824             || registry_slots.iter().ne(approved.iter())
2825         {
2826             return Err(SuccessorError::RegistrySlotOutsideApprovedRoster);
2827         }
2828         let targets: BTreeSet<_> = slots
2829             .iter()
2830             .filter_map(|slot| match slot {
2831                 ReleaseArtifactSlot::ProductAsset { target, .. } => Some(*target),
2832                 _ => None,
2833             })
2834             .collect();
2835         if slots
2836             .iter()
2837             .filter(|slot| matches!(slot, ReleaseArtifactSlot::ProductAsset { .. }))
2838             .count()
2839             != ProductTarget::ALL.len()
2840             || targets.len() != ProductTarget::ALL.len()
2841             || !ProductTarget::ALL.iter().all(|target| targets.contains(target))
2842             || slots
2843                 .iter()
2844                 .filter(|slot| matches!(slot, ReleaseArtifactSlot::ChecksumManifest { .. }))
2845                 .count()
2846                 != 1
2847             || slots
2848                 .iter()
2849                 .filter(|slot| matches!(slot, ReleaseArtifactSlot::ReleaseMetadata { .. }))
2850                 .count()
2851                 != 1
2852         {
2853             return Err(SuccessorError::InvalidProductRoster);
2854         }
2855         let mut names = BTreeSet::new();
2856         if slots.iter().any(|slot| !names.insert(slot.file_name())) {
2857             return Err(SuccessorError::DuplicateFileName);
2858         }
2859         Ok(())
2860     }
