2862     fn validate_operations(
2863         release: &ProductReleaseId,
2864         destination: &ReleaseDestinationBinding,
2865         approved: &[ApprovedRegistryPackage],
2866         operations: &[ReleaseOperation],
2867         slots: &[ReleaseArtifactSlot],
2868     ) -> Result<(), SuccessorError> {
2869         let ids: BTreeSet<_> = operations.iter().map(|operation| operation.id.clone()).collect();
2870         if ids.len() != operations.len() {
2871             return Err(SuccessorError::DuplicateOperation);
2872         }
2873         for operation in operations {
2874             operation.id.validate(release)?;
2875             if operation.prerequisites.windows(2).any(|pair| pair[0] >= pair[1])
2876                 || operation.prerequisites.iter().any(|id| !ids.contains(id))
2877             {
2878                 return Err(SuccessorError::InvalidPrerequisite);
2879             }
2880         }
2881         let expected_uploads: BTreeSet<_> = slots.iter().filter(|slot| slot.release().is_some()).cloned().collect();
2882         let uploads: BTreeSet<_> = operations
2883             .iter()
2884             .filter_map(|operation| match &operation.id {
2885                 ReleaseOperationId::ArtifactUpload { slot, .. } => Some(slot.clone()),
2886                 _ => None,
2887             })
2888             .collect();
2889         if uploads != expected_uploads {
2890             return Err(SuccessorError::InvalidProductRoster);
2891         }
2892         let registry_operations: BTreeSet<_> = operations
2893             .iter()
2894             .filter_map(|operation| match &operation.id {
2895                 ReleaseOperationId::RegistryArtifactPublish { slot, .. } => Some(slot.clone()),
2896                 _ => None,
2897             })
2898             .collect();
2899         let registry_slots: BTreeSet<_> = slots
2900             .iter()
2901             .filter(|slot| matches!(slot, ReleaseArtifactSlot::RegistryPackage { .. }))
2902             .cloned()
2903             .collect();
2904         if registry_operations != registry_slots || registry_slots.len() != approved.len() {
2905             return Err(SuccessorError::InvalidPackageOperation);
2906         }
2907         let tags = operations
2908             .iter()
2909             .filter(|operation| matches!(operation.id, ReleaseOperationId::ProductTag { .. }))
2910             .collect::<Vec<_>>();
2911         let prepares = operations
2912             .iter()
2913             .filter(|operation| matches!(operation.id, ReleaseOperationId::ForgePrepare { .. }))
2914             .collect::<Vec<_>>();
2915         let publishes = operations
2916             .iter()
2917             .filter(|operation| matches!(operation.id, ReleaseOperationId::ForgePublish { .. }))
2918             .collect::<Vec<_>>();
2919         if tags.len() != 1 || prepares.len() != 1 || publishes.len() != 1 {
2920             return Err(SuccessorError::InvalidProductOperation);
2921         }
2922         let mut registry_ids = operations
2923             .iter()
2924             .filter_map(|operation| {
2925                 matches!(operation.id, ReleaseOperationId::RegistryArtifactPublish { .. })
2926                     .then_some(operation.id.clone())
2927             })
2928             .collect::<Vec<_>>();
2929         registry_ids.sort();
2930         if tags[0].prerequisites != registry_ids
2931             || prepares[0].prerequisites != [tags[0].id.clone()]
2932             || operations.iter().any(|operation| {
2933                 matches!(operation.id, ReleaseOperationId::ArtifactUpload { .. })
2934                     && operation.prerequisites != [prepares[0].id.clone()]
2935             })
2936         {
2937             return Err(SuccessorError::InvalidPrerequisite);
2938         }
2939         let prepare_repository = match &prepares[0].id {
2940             ReleaseOperationId::ForgePrepare { repository, .. } => repository,
2941             _ => unreachable!("filtered ForgePrepare"),
2942         };
2943         let publish_repository = match &publishes[0].id {
2944             ReleaseOperationId::ForgePublish { repository, .. } => repository,
2945             _ => unreachable!("filtered ForgePublish"),
2946         };
2947         if prepare_repository != publish_repository || prepare_repository != destination.forge_repository() {
2948             return Err(SuccessorError::MismatchedForgeRepository);
2949         }
2950         let mut upload_ids = operations
2951             .iter()
2952             .filter_map(|operation| {
2953                 matches!(operation.id, ReleaseOperationId::ArtifactUpload { .. }).then_some(operation.id.clone())
2954             })
2955             .collect::<Vec<_>>();
2956         upload_ids.sort();
2957         if publishes[0].prerequisites != upload_ids {
2958             return Err(SuccessorError::InvalidPrerequisite);
2959         }
2960         let edges: BTreeMap<_, _> = operations
2961             .iter()
2962             .map(|operation| (operation.id.clone(), operation.prerequisites.clone()))
2963             .collect();
2964         let canonical = stable_order(&edges)?;
2965         if operations.iter().map(|operation| &operation.id).ne(canonical.iter()) {
2966             return Err(SuccessorError::NonCanonicalOperationOrder);
2967         }
2968         Ok(())
2969     }
2970 
2971     fn stable_order(
2972         prerequisites: &BTreeMap<ReleaseOperationId, Vec<ReleaseOperationId>>,
2973     ) -> Result<Vec<ReleaseOperationId>, SuccessorError> {
2974         let mut remaining: BTreeMap<_, _> = prerequisites
2975             .iter()
2976             .map(|(id, prerequisites)| (id.clone(), prerequisites.len()))
2977             .collect();
2978         let mut dependents = BTreeMap::<ReleaseOperationId, Vec<ReleaseOperationId>>::new();
2979         for (id, prerequisites) in prerequisites {
2980             for prerequisite in prerequisites {
2981                 dependents.entry(prerequisite.clone()).or_default().push(id.clone());
2982             }
2983         }
2984         let mut ready: BTreeSet<_> = remaining
2985             .iter()
2986             .filter_map(|(id, count)| (*count == 0).then_some(id.clone()))
2987             .collect();
2988         let mut ordered = Vec::with_capacity(prerequisites.len());
2989         while let Some(id) = ready.pop_first() {
2990             ordered.push(id.clone());
2991             for dependent in dependents.get(&id).into_iter().flatten() {
2992                 let count = remaining.get_mut(dependent).expect("known successor node");
2993                 *count -= 1;
2994                 if *count == 0 {
2995                     ready.insert(dependent.clone());
2996                 }
2997             }
2998         }
2999         (ordered.len() == prerequisites.len())
3000             .then_some(ordered)
3001             .ok_or(SuccessorError::CyclicPrerequisites)
3002     }
