 348 pub fn load(root: &Path) -> Result<ResolvedConfig, ConfigError> {
 349     let callisto_toml = root.join("callisto.toml");
 350     let raw = if callisto_toml.exists() {
 351         let content = fs::read_to_string(&callisto_toml).map_err(|e| ConfigError::Read {
 352             path: callisto_toml.clone(),
 353             message: e.to_string(),
 354         })?;
 355         toml::from_str::<RawConfig>(&content).map_err(|e| ConfigError::ParseToml {
 356             path: callisto_toml.clone(),
 357             message: e.to_string(),
 358         })?
 359     } else {
 360         RawConfig::default()
 361     };
 362 
 363     let mut provenance = BTreeMap::new();
 364 
 365     let changesets_dir_str = raw
 366         .changesets
 367         .as_ref()
 368         .and_then(|c| c.dir.as_deref())
 369         .unwrap_or(".changeset");
 370 
 371     // Reject any changesets.dir value that is absolute or contains '..'
 372     // components — either would allow load_changesets / atomic_write to
 373     // escape the workspace root. We check components() rather than
 374     // canonicalizing because the directory may not exist yet (e.g. a fresh
 375     // workspace).
 376     let changesets_dir =
 377         callisto_model::workspace_relative(changesets_dir_str).map_err(|_err| ConfigError::InvalidChangesetsDir {
 378             dir: changesets_dir_str.to_string(),
 379         })?;
 380 
 381     let cascade_raw = raw.cascade.unwrap_or_default();
 382     let mode = match cascade_raw.mode.as_deref() {
 383         Some("always") => {
 384             provenance.insert(ConfigKey::CASCADE_MODE, ConfigProvenance::Explicit);
 385             CascadeMode::Always
 386         }
 387         Some("out-of-range") | None => CascadeMode::OutOfRange,
 388         Some(other) => {
 389             return Err(ConfigError::UnknownKey {
 390                 path: callisto_toml,
 391                 key: format!("cascade.mode = {other}"),
 392             })
 393         }
 394     };
 395 
 396     let bump_severity = match cascade_raw.bump_severity.as_deref() {
 397         Some("minor") => {
 398             provenance.insert(ConfigKey::CASCADE_BUMP_SEVERITY, ConfigProvenance::Explicit);
 399             CascadeBumpSeverity::Minor
 400         }
 401         Some("patch") | None => CascadeBumpSeverity::Patch,
 402         Some(other) => {
 403             return Err(ConfigError::InvalidBumpSeverity {
 404                 found: other.to_string(),
 405             })
 406         }
 407     };
 408 
 409     let peer_escalation = cascade_raw.peer_escalation.unwrap_or(true);
 410     if cascade_raw.peer_escalation.is_some() {
 411         provenance.insert(ConfigKey::CASCADE_PEER_ESCALATION, ConfigProvenance::Explicit);
 412     }
 413 
 414     let preserve_npm_ranges = cascade_raw.preserve_npm_ranges.unwrap_or(true);
 415     if cascade_raw.preserve_npm_ranges.is_some() {
 416         provenance.insert(ConfigKey::CASCADE_PRESERVE_NPM_RANGES, ConfigProvenance::Explicit);
 417     }
 418 
 419     let validation_raw = raw.validation.unwrap_or_default();
 420     let allow_empty_changesets = validation_raw.allow_empty_changesets.unwrap_or(false);
 421     if validation_raw.allow_empty_changesets.is_some() {
 422         provenance.insert(ConfigKey::VALIDATION_ALLOW_EMPTY_CHANGESETS, ConfigProvenance::Explicit);
 423     }
 424 
 425     let mut registries = BTreeMap::new();
 426     registries.insert(
 427         RegistryKey(RegistryKey::CRATES_IO.to_string()),
 428         RegistryConfig {
 429             kind: Ecosystem::Cargo,
 430             url: None,
 431         },
 432     );
 433     registries.insert(
 434         RegistryKey(RegistryKey::NPM.to_string()),
 435         RegistryConfig {
 436             kind: Ecosystem::Npm,
 437             url: None,
 438         },
 439     );
 440 
 441     if let Some(raw_regs) = raw.registries {
 442         for (k_str, reg) in raw_regs {
 443             let key = RegistryKey(k_str);
 444             let kind = match reg.kind.as_deref() {
 445                 Some("cargo") => Ecosystem::Cargo,
 446                 Some("npm") | None => Ecosystem::Npm,
 447                 Some("pypi") => Ecosystem::Pypi,
 448                 Some(other) => {
 449                     return Err(ConfigError::UnknownKey {
 450                         path: callisto_toml.clone(),
 451                         key: format!("[registries] kind = {other:?}"),
 452                     })
 453                 }
 454             };
 455             registries.insert(key, RegistryConfig { kind, url: reg.url });
 456         }
 457     }
 458 
 459     let raw_groups = RawGroupTable {
 460         fixed: raw.fixed_group.unwrap_or_default(),
 461         linked: raw.linked_group.unwrap_or_default(),
 462     };
 463     GroupTable::validate_syntactic(&raw_groups)?;
 464 
 465     // Resolve [[package]] blocks into per-package override rules.
 466     // Order is preserved: first matching rule wins during package construction.
 467     let mut packages: Vec<(PackageId, PackageConfig)> = Vec::new();
 468     for raw_pkg in raw.package.unwrap_or_default() {
 469         let pattern = PackageId::parse(&raw_pkg.pattern).map_err(|e| ConfigError::UnknownKey {
 470             path: callisto_toml.clone(),
 471             key: format!("[[package]] match = {:?}: {e}", raw_pkg.pattern),
 472         })?;
 473 
 474         let cfg = parse_package_config_fields(
 475             &callisto_toml,
 476             "[[package]]",
 477             &raw_pkg.pattern,
 478             raw_pkg.release_unit.as_deref(),
 479             raw_pkg.release_trigger.as_deref(),
 480             raw_pkg.tag_template.as_deref(),
 481             raw_pkg.changelog.as_deref(),
 482             raw_pkg.pre_major_inference.as_deref(),
 483             raw_pkg.publish_to.as_deref(),
 484         )?;
 485 
 486         packages.push((pattern, cfg));
 487     }
 488 
 489     // Resolve [[package-set]] blocks into bulk config-override rules.
 490     // Semantics: each rule matches ALL packages whose PackageId matches the pattern.
 491     // A [[package]] rule takes priority; [[package-set]] is the fallback (see walk.rs).
 492     let mut package_sets: Vec<(PackagePattern, PackageConfig)> = Vec::new();
 493     for raw_pkg in raw.package_set.unwrap_or_default() {
 494         let pattern = PackagePattern::parse(&raw_pkg.pattern).map_err(|e| ConfigError::UnknownKey {
 495             path: callisto_toml.clone(),
 496             key: format!("[[package-set]] match = {:?}: {e}", raw_pkg.pattern),
 497         })?;
 498 
 499         let cfg = parse_package_config_fields(
 500             &callisto_toml,
 501             "[[package-set]]",
 502             &raw_pkg.pattern,
 503             raw_pkg.release_unit.as_deref(),
 504             raw_pkg.release_trigger.as_deref(),
 505             raw_pkg.tag_template.as_deref(),
 506             raw_pkg.changelog.as_deref(),
 507             raw_pkg.pre_major_inference.as_deref(),
 508             raw_pkg.publish_to.as_deref(),
 509         )?;
 510 
 511         package_sets.push((pattern, cfg));
 512     }
 513 
 514     Ok(ResolvedConfig {
 515         root: root.to_path_buf(),
 516         changesets_dir,
 517         cascade: CascadeConfig {
 518             mode,
 519             bump_severity,
 520             peer_escalation,
 521             preserve_npm_ranges,
 522         },
 523         validation: ValidationConfig { allow_empty_changesets },
 524         registries,
 525         packages,
 526         package_sets,
 527         groups: GroupTable::default(),
 528         raw_groups,
 529         promoted_siblings: BTreeMap::new(),
 530         package_ecosystems: BTreeMap::new(),
 531         provenance,
 532     })
 533 }
