1223     pub fn new(
1224         intent: &ReleaseIntentV1,
1225         mut entries: Vec<ArtifactManifestEntryV1>,
1226     ) -> Result<Self, ArtifactManifestError> {
1227         let SourceIdentity::GitCommit { sha } = &intent.snapshot.source else {
1228             return Err(ArtifactManifestError::NonGitSource);
1229         };
1230         entries.sort_by(|left, right| left.slot.cmp(&right.slot));
1231         if entries.windows(2).any(|pair| pair[0].slot == pair[1].slot) {
1232             return Err(ArtifactManifestError::DuplicateSlot);
1233         }
1234         let expected = &intent.artifact_slots;
1235         if entries.iter().map(|entry| &entry.slot).ne(expected.iter()) {
1236             return Err(ArtifactManifestError::MismatchedSlotRoster);
1237         }
1238         if entries.iter().any(|entry| {
1239             entry.digest != entry.attestation.subject_digest
1240                 || entry.attestation.source_commit != *sha
1241                 || entry.attestation.repository != entry.slot.attestation_policy.repository
1242                 || entry.attestation.workflow_path != entry.slot.attestation_policy.workflow_path
1243                 || entry.attestation.workflow_commit != entry.slot.attestation_policy.workflow_commit
1244         }) {
1245             return Err(ArtifactManifestError::MismatchedAttestation);
1246         }
1247         Ok(Self {
1248             schema_version: Self::SCHEMA_VERSION,
1249             intent_digest: intent.digest.clone(),
1250             source_commit: sha.clone(),
1251             entries,
1252         })
1253     }
