   2 //!
   3 //! The store owns no release policy and does not derive paths from mutable
   4 //! workspace configuration. Callers must supply the state path deliberately.
   5 
   6 use std::path::{Path, PathBuf};
   7 
   8 use callisto_model::{atomic::atomic_write, ApplyPermit, ReleaseExecutionStateV1, ReleaseIntentV1};
