 718     pub fn new(
 719         source: SourceIdentity,
 720         mut packages: Vec<ReleasePackageInputV1>,
 721     ) -> Result<Self, ReleaseInputSnapshotError> {
 722         packages.sort();
 723         if packages.windows(2).any(|pair| pair[0].package == pair[1].package) {
 724             return Err(ReleaseInputSnapshotError::DuplicatePackage);
 725         }
 726         Ok(Self {
 727             schema_version: Self::SCHEMA_VERSION,
