 733     pub fn digest(&self) -> SemanticInputDigest {
 734         let mut transcript = CanonicalTranscript::semantic_input_v1();
 735         transcript.push_bytes("schema", [self.schema_version]);
 736         match &self.source {
 737             SourceIdentity::GitCommit { sha } => transcript.push_str("source.git", sha.as_str()),
 738             SourceIdentity::HermeticContent { digest } => transcript.push_str("source.hermetic", digest.as_str()),
 739         }
 740         for package in &self.packages {
 741             transcript.push_str("package", &package.package.to_string());
 742             transcript.push_str("package.fingerprint", package.fingerprint.as_str());
 743         }
 744         SemanticInputDigest::from_transcript(&transcript)
 745     }
