1171 fn is_safe_workflow_path(value: &str) -> bool {
1172     value.starts_with(".github/workflows/")
1173         && value.ends_with(".yml")
1174         && !value.contains("..")
1175         && value
1176             .bytes()
1177             .all(|byte| byte.is_ascii_alphanumeric() || matches!(byte, b'.' | b'_' | b'-' | b'/'))
1178 }
1179 
1180 fn is_safe_artifact_component(value: &str) -> bool {
1181     !value.is_empty()
1182         && value.len() <= 255
1183         && !value.contains("..")
1184         && value
1185             .bytes()
1186             .all(|byte| byte.is_ascii_alphanumeric() || matches!(byte, b'.' | b'_' | b'-'))
1187 }
