1285 fn validated_registry_key(raw: String) -> Result<RegistryKey, ReleaseOperationError> {
1286     if raw.is_empty()
1287         || raw.len() > 128
1288         || !raw
1289             .bytes()
1290             .all(|byte| byte.is_ascii_alphanumeric() || matches!(byte, b'-' | b'_'))
1291     {
1292         return Err(ReleaseOperationError::MalformedRegistryKey { raw });
1293     }
