1322 impl<'de> Deserialize<'de> for ReleaseIntentV1 {
1323     fn deserialize<D>(deserializer: D) -> Result<Self, D::Error>
1324     where
1325         D: Deserializer<'de>,
1326     {
1327         let wire = ReleaseIntentV1Wire::deserialize(deserializer)?;
1328         check_schema_version::<D::Error>(wire.schema_version, Self::SCHEMA_VERSION, "release intent")?;
1329         check_schema_version::<D::Error>(
1330             wire.decision.schema_version,
1331             ReleaseDecisionV1::SCHEMA_VERSION,
1332             "release intent",
1333         )?;
1334         check_schema_version::<D::Error>(
1335             wire.snapshot.schema_version,
1336             ReleaseInputSnapshotV1::SCHEMA_VERSION,
1337             "release intent",
1338         )?;
1339         if wire.snapshot.packages.windows(2).any(|pair| pair[0] >= pair[1]) {
1340             return Err(serde::de::Error::custom("release input packages are not canonical"));
1341         }
1342         let intent = Self::new(
1343             wire.decision,
1344             wire.snapshot,
1345             wire.trust_profile,
1346             wire.operations,
1347             wire.artifact_slots,
1348         )
1349         .map_err(serde::de::Error::custom)?;
1350         if intent.digest != wire.digest {
1351             return Err(serde::de::Error::custom(
1352                 "release intent digest does not match canonical content",
1353             ));
1354         }
1355         Ok(intent)
1356     }
