1362     pub fn new(
1363         decision: ReleaseDecisionV1,
1364         snapshot: ReleaseInputSnapshotV1,
1365         trust_profile: ExecutionTrustProfileV1,
1366         operations: Vec<ReleaseOperation>,
1367         mut artifact_slots: Vec<ArtifactSlotId>,
1368     ) -> Result<Self, ReleaseIntentError> {
1369         if !matches!(trust_profile, ExecutionTrustProfileV1::GitCommit)
1370             || !matches!(snapshot.source, SourceIdentity::GitCommit { .. })
1371         {
1372             return Err(ReleaseIntentError::UnsupportedTrustProfile);
1373         }
1374         validate_operations(&operations)?;
1375         validate_operation_roster(&decision, &operations)?;
1376         artifact_slots.sort();
1377         if artifact_slots.windows(2).any(|pair| pair[0] == pair[1]) {
1378             return Err(ReleaseIntentError::DuplicateArtifactSlot);
1379         }
1380         if artifact_slots.iter().any(|slot| {
1381             !decision
1382                 .entries
1383                 .iter()
1384                 .any(|entry| entry.package == slot.package && entry.target_version == slot.version)
1385         }) {
1386             return Err(ReleaseIntentError::ArtifactSlotOutsideDecision);
1387         }
1388         validate_artifact_upload_roster(&operations, &artifact_slots)?;
1389         let digest = digest_intent(&decision, &snapshot, trust_profile, &operations, &artifact_slots);
1390         Ok(Self {
1391             schema_version: Self::SCHEMA_VERSION,
1392             decision,
1393             snapshot,
1394             trust_profile,
1395             operations,
1396             artifact_slots,
1397             digest,
1398         })
1399     }
