   1 //! Deterministic, graph-owned release roster decisions.
   2 //!
   3 //! This is deliberately separate from `PublishPlan`: it records the exact
   4 //! package/version authority that later intent construction consumes, without
   5 //! exposing a mutation route.
   6 
   7 use callisto_model::{
   8     BumpReason, CommandRunner, CommitSha, Ecosystem, Package, ReleaseDecisionEntry, ReleaseDecisionV1,
   9     ReleaseInclusionReason, ReleasePackageId, Version,
  10 };
  11 
  12 use crate::error::{
  13     CommandFailure, CommitVerificationFailure, ReleasePreconditionRequirement, ReleaseSelectionInvalidReason,
  14     UnsupportedReleaseFeature,
  15 };
  16 use crate::{DependencyResolver, GraphError, VersionPlan, Workspace};
  17 
  18 /// Computes one [`ReleasePackageId`] per canonical manifest, ecosystem-qualified
  19 /// against `package`'s name.
  20 ///
  21 /// This is the single derivation of release package identity shared by every
  22 /// site that computes or verifies release authority: [`derive_release_decision`],
  23 /// [`derive_release_commit_decision`], and `release::derive_release_inputs`.
  24 /// Per this module's own established lesson (see the doc comment on
  25 /// [`derive_release_commit_decision`]), independently reimplementing this
  26 /// mapping at each call site is exactly the kind of duplicated derivation
  27 /// that drifts -- so it lives here once instead.
  28 pub(crate) fn release_package_ids(package: &Package) -> Result<Vec<ReleasePackageId>, GraphError> {
  29     package
  30         .canonical_manifests()
  31         .map(|manifest| ReleasePackageId::new(manifest.ecosystem(), package.id.name()))
  32         .collect::<Result<Vec<_>, _>>()
  33         .map_err(GraphError::from)
  34 }
  35 
  36 /// Reject source-only identities wherever a durable decision grants authority,
  37 /// including causal references supplied in a serialized decision.
  38 pub(crate) fn validate_release_units<R: CommandRunner, D: DependencyResolver>(
  39     workspace: &Workspace<'_, R, D>,
  40     decision: &ReleaseDecisionV1,
  41 ) -> Result<(), GraphError> {
  42     let mut excluded = std::collections::BTreeSet::new();
  43     for package in workspace.graph.packages() {
  44         if !crate::config::is_release_unit(&workspace.config, &package.id)? {
  45             excluded.extend(release_package_ids(package)?);
  46         }
  47     }
  48     for entry in &decision.entries {
  49         for id in std::iter::once(&entry.package).chain(entry.reasons.iter().filter_map(|reason| match reason {
  50             ReleaseInclusionReason::Cascade { from, .. } => Some(from),
  51             _ => None,
  52         })) {
  53             if excluded.contains(id) {
  54                 return Err(GraphError::ReleasePackageNotSelected { package: id.clone() });
  55             }
  56         }
  57     }
  58     Ok(())
  59 }
  60 
  61 /// Derives the durable roster from a freshly computed version plan.
  62 ///
  63 /// The caller supplies the plan from the same workspace observation; this
  64 /// function never inspects `PublishPlan` or a caller-provided release roster.
  65 pub fn derive_release_decision<R: callisto_model::CommandRunner, D: DependencyResolver>(
  66     workspace: &Workspace<'_, R, D>,
  67     plan: &VersionPlan,
  68 ) -> Result<ReleaseDecisionV1, GraphError> {
  69     let mut package_ids = std::collections::BTreeMap::new();
  70     for package in workspace.graph.packages() {
  71         if !crate::config::is_release_unit(&workspace.config, &package.id)? {
  72             continue;
  73         }
  74         let ids = release_package_ids(package)?;
  75         package_ids.insert(package.id.clone(), ids);
  76     }
  77 
  78     let mut entries = Vec::new();
  79     for bump in &plan.bumps {
  80         if !crate::config::is_release_unit(&workspace.config, &bump.package)? {
  81             continue;
  82         }
  83         // `plan` is contractually derived from this same workspace
  84         // observation (see doc comment above), so every bump's package must
  85         // already be a key here -- a miss means the plan/workspace pairing
  86         // itself is inconsistent, not a recoverable operator condition.
  87         let ids = package_ids
  88             .get(&bump.package)
  89             .ok_or_else(|| GraphError::ReleaseInvariant {
  90                 detail: format!(
  91                     "version plan references package `{}`, which is absent from this workspace observation",
  92                     bump.package.display_name()
  93                 ),
  94             })?;
  95         for id in ids {
  96             entries.push(ReleaseDecisionEntry {
  97                 package: id.clone(),
  98                 target_version: bump.to.clone(),
  99                 reasons: vec![reason_from_bump(bump.reason.as_ref(), &package_ids)?],
 100             });
 101         }
 102     }
 103     ReleaseDecisionV1::new(entries).map_err(GraphError::from)
 104 }
