 106 /// Derives a durable decision for explicit, exact release identities.
 107 ///
 108 /// A linked group is one release unit: selecting any member includes every
 109 /// member of that linked group which the version plan selected. All other
 110 /// packages remain outside the authority boundary. The caller must pass
 111 /// ecosystem-qualified [`ReleasePackageId`] values; this function never uses
 112 /// `PackageId::matches`, whose bare-name wildcard semantics are unsuitable
 113 /// for release authority.
 114 pub fn derive_selected_release_decision<R: callisto_model::CommandRunner, D: DependencyResolver>(
 115     workspace: &Workspace<'_, R, D>,
 116     plan: &VersionPlan,
 117     selections: &[ReleasePackageId],
 118 ) -> Result<ReleaseDecisionV1, GraphError> {
 119     let complete = derive_release_decision(workspace, plan)?;
 120 
 121     let mut seen = std::collections::BTreeSet::new();
 122     if let Some(duplicate) = selections.iter().find(|selection| !seen.insert(*selection)) {
 123         return Err(GraphError::ReleaseSelectionInvalid {
 124             package: duplicate.clone(),
 125             reason: ReleaseSelectionInvalidReason::Duplicate,
 126         });
 127     }
 128 
 129     let selected = selections.iter().collect::<std::collections::BTreeSet<_>>();
 130     for selection in &selected {
 131         if !complete.entries.iter().any(|entry| &entry.package == *selection) {
 132             return Err(GraphError::ReleaseSelectionInvalid {
 133                 package: (*selection).clone(),
 134                 reason: ReleaseSelectionInvalidReason::NotInPlan,
 135             });
 136         }
 137     }
 138 
 139     let linked_groups = complete
 140         .entries
 141         .iter()
 142         .filter(|entry| selected.contains(&entry.package))
 143         .flat_map(|entry| entry.reasons.iter())
 144         .filter_map(|reason| match reason {
 145             ReleaseInclusionReason::LinkedGroup { group_id } => Some(group_id.clone()),
 146             _ => None,
 147         })
 148         .collect::<std::collections::BTreeSet<_>>();
 149 
 150     let entries = complete
 151         .entries
 152         .into_iter()
 153         .filter(|entry| {
 154             selected.contains(&entry.package)
 155                 || entry.reasons.iter().any(|reason| {
 156                     matches!(reason, ReleaseInclusionReason::LinkedGroup { group_id } if linked_groups.contains(group_id))
 157                 })
 158         })
 159         .collect();
 160     ReleaseDecisionV1::new(entries).map_err(GraphError::from)
 161 }
