 163 /// Verifies the release roster a merged release commit claims, against a
 164 /// release-decision file committed alongside it at `decision_path`.
 165 ///
 166 /// This is intentionally *not* a second computation of changeset, fixed-group,
 167 /// linked-group, cascade, or pre-release-policy inclusion. `plan_version`
 168 /// (via [`derive_release_decision`]) already computed that once, correctly,
 169 /// when the release PR was generated -- and `callisto version --emit-decision`
 170 /// commits its exact output alongside the manifest and changelog edits.
 171 /// Re-deriving that policy a second time here, from raw git diffs, is exactly
 172 /// the kind of duplicated logic that drifts: an earlier version of this
 173 /// function did just that, understood only a direct changeset match, and
 174 /// rejected every real release in this repository once a fixed-group cascade
 175 /// (a case its reimplementation never learned) touched an unnamed sibling.
 176 ///
 177 /// Instead, this function reads the committed decision back and confirms the
 178 /// commit's actual diff matches it exactly -- no more, no less.
 179 /// [`ReleaseDecisionV1`]'s own deserializer already rejects a decision whose
 180 /// entries don't match its content digest, so a hand-edited or corrupted
 181 /// decision file fails before this function's own diff cross-check runs.
 182 ///
 183 /// The caller must check out the exact merge commit in detached HEAD state
 184 /// before creating an intent. GitHub-specific PR/approval provenance belongs
 185 /// in the workflow boundary; this graph function verifies the local,
 186 /// provider-neutral commit delta only.
 187 pub fn derive_release_commit_decision<R: CommandRunner, D: DependencyResolver>(
 188     workspace: &Workspace<'_, R, D>,
 189     release_commit: &CommitSha,
 190     decision_path: &std::path::Path,
 191 ) -> Result<ReleaseDecisionV1, GraphError> {
 192     let head_args = ["rev-parse", "HEAD"];
 193     let head = git_stdout(workspace.runner, &workspace.root, &head_args)?;
 194     let head =
 195         CommitSha::parse(&head).map_err(|source| command_malformed_output("git", &head_args, source.to_string()))?;
 196     if &head != release_commit {
 197         return Err(GraphError::ReleaseCommitVerificationFailed {
 198             commit: release_commit.clone(),
 199             reason: CommitVerificationFailure::HeadMismatch,
 200         });
 201     }
 202 
 203     let parent_ref = format!("{}^", release_commit.as_str());
 204     let parent_args = ["rev-parse", parent_ref.as_str()];
 205     let parent = git_stdout(workspace.runner, &workspace.root, &parent_args)?;
 206     CommitSha::parse(&parent).map_err(|source| command_malformed_output("git", &parent_args, source.to_string()))?;
 207 
 208     let diff_tree_args = [
 209         "diff-tree",
 210         "--no-commit-id",
 211         "--name-status",
 212         "-r",
 213         "--no-renames",
 214         parent.as_str(),
 215         release_commit.as_str(),
 216     ];
 217     let changed = git_stdout(workspace.runner, &workspace.root, &diff_tree_args)?;
 218     let changed = parse_name_status(&changed, &diff_tree_args)?;
 219 
 220     // The decision must be freshly authored as part of *this* commit, not a
 221     // stale leftover an earlier release already committed and this one never
 222     // touched -- otherwise a commit that changes nothing real could still
 223     // carry forward a prior, unrelated decision's authority.
 224     let decision_path_str = decision_path.to_string_lossy().replace('\\', "/");
 225     let decision_freshly_written = changed
 226         .iter()
 227         .any(|(status, path)| path == &decision_path_str && matches!(status.as_str(), "A" | "M"));
 228     if !decision_freshly_written {
 229         return Err(GraphError::ReleaseCommitVerificationFailed {
 230             commit: release_commit.clone(),
 231             reason: CommitVerificationFailure::DecisionNotWrittenByCommit,
 232         });
 233     }
 234 
 235     // A cheap, independent sanity check that this commit is a real version
 236     // application and not just a hand-crafted decision file: some real
 237     // changeset was actually consumed. The decision's own entries, not this
 238     // changeset's content, remain the sole authority verified below.
 239     let changeset_dir = workspace.config.changesets_dir.to_string_lossy().replace('\\', "/");
 240     let changeset_prefix = format!("{}/", changeset_dir.trim_end_matches('/'));
 241     let consumed_a_changeset = changed
 242         .iter()
 243         .any(|(status, path)| status == "D" && path.starts_with(&changeset_prefix) && path.ends_with(".md"));
 244     if !consumed_a_changeset {
 245         return Err(GraphError::ReleaseCommitVerificationFailed {
 246             commit: release_commit.clone(),
 247             reason: CommitVerificationFailure::NoChangesetConsumed,
 248         });
 249     }
 250 
 251     let decision_source = git_file(
 252         workspace.runner,
 253         &workspace.root,
 254         release_commit.as_str(),
 255         &decision_path_str,
 256     )?;
 257     let decision: ReleaseDecisionV1 =
 258         serde_json::from_str(&decision_source).map_err(|error| GraphError::ReleaseDecisionDecode {
 259             path: decision_path.to_path_buf(),
 260             message: error.to_string(),
 261         })?;
 262     validate_release_units(workspace, &decision)?;
 263     let claimed = decision
 264         .entries
 265         .iter()
 266         .map(|entry| (entry.package.clone(), entry.target_version.clone()))
 267         .collect::<std::collections::BTreeMap<_, _>>();
 268 
 269     let changed_paths = changed
 270         .iter()
 271         .filter_map(|(status, path)| matches!(status.as_str(), "A" | "M").then_some(path.as_str()))
 272         .collect::<std::collections::BTreeSet<_>>();
 273 
 274     // Every canonical manifest path this workspace currently declares, in
 275     // the exact order `workspace.graph.packages()` and
 276     // `Package::canonical_manifests()` yield -- both are backed by ordered
 277     // (`BTreeMap`/`Vec`) storage with no interior mutation between calls, so
 278     // the second traversal below visits the same (package, manifest) pairs
 279     // in the same order. That lets it zip the batched `before`/`after`
 280     // results back on by position instead of re-keying by path, which would
 281     // misbehave if two packages ever declared an identical manifest path.
 282     let manifest_queries: Vec<(String, Ecosystem)> = workspace
 283         .graph
 284         .packages()
 285         .flat_map(Package::canonical_manifests)
 286         .map(|manifest| (manifest.path.to_string_lossy().into_owned(), manifest.ecosystem()))
 287         .collect();
 288     let query_paths: Vec<&str> = manifest_queries.iter().map(|(path, _)| path.as_str()).collect();
 289 
 290     // Exactly two `git cat-file --batch` subprocess invocations total (one
 291     // per commit), regardless of how many canonical manifests the
 292     // workspace has -- replaces what was previously 2*N separate `git
 293     // show` spawns (one `manifest_version_at` call per manifest per
 294     // commit).
 295     let before_blobs = batch_manifest_blobs_at(workspace.runner, &workspace.root, &parent, &query_paths)?;
 296     let after_blobs =
 297         batch_manifest_blobs_at(workspace.runner, &workspace.root, release_commit.as_str(), &query_paths)?;
 298     let before_versions = resolve_batch_versions(before_blobs, &manifest_queries)?;
 299     let after_versions = resolve_batch_versions(after_blobs, &manifest_queries)?;
 300 
 301     let mut observed = std::collections::BTreeSet::new();
 302     let mut manifest_index = 0usize;
 303     for package in workspace.graph.packages() {
 304         let package_ids = release_package_ids(package)?;
 305         let package_is_claimed = package_ids.iter().any(|id| claimed.contains_key(id));
 306         let releasable = crate::config::is_release_unit(&workspace.config, &package.id)?;
 307         if package_is_claimed {
 308             let changelog = package.changelog.as_ref().ok_or(GraphError::ReleasePreconditionUnmet {
 309                 requirement: ReleasePreconditionRequirement::ChangelogConfigured,
 310             })?;
 311             if !changed_paths.contains(changelog.to_string_lossy().as_ref()) {
 312                 return Err(GraphError::ReleaseCommitVerificationFailed {
 313                     commit: release_commit.clone(),
 314                     reason: CommitVerificationFailure::ChangelogNotTouched,
 315                 });
 316             }
 317         }
 318         for (manifest, id) in package.canonical_manifests().zip(package_ids) {
 319             let path = manifest.path.to_string_lossy();
 320             let before = &before_versions[manifest_index];
 321             let after = &after_versions[manifest_index];
 322             manifest_index += 1;
 323             let changed_version = before != after;
 324             match claimed.get(&id) {
 325                 Some(target_version) => {
 326                     if !changed_paths.contains(path.as_ref()) {
 327                         return Err(GraphError::ReleaseCommitVerificationFailed {
 328                             commit: release_commit.clone(),
 329                             reason: CommitVerificationFailure::ManifestNotInDiff,
 330                         });
