1236 /// Credential-free URL projection used only inside a digest transcript.
1237 #[derive(Debug, PartialEq, Eq)]
1238 struct RegistryBindingV1 {
1239     scheme: String,
1240     host: String,
1241     effective_port: Option<u16>,
1242     path: String,
1243 }
1244 
1245 impl RegistryBindingV1 {
1246     fn digest(&self) -> RegistryBindingDigest {
1247         let mut transcript = CanonicalTranscript::semantic_input_v1();
1248         transcript.push_str("registry.scheme", &self.scheme);
1249         transcript.push_str("registry.host", &self.host);
1250         transcript.push_str(
1251             "registry.port",
1252             &self.effective_port.map_or_else(String::new, |port| port.to_string()),
1253         );
1254         transcript.push_str("registry.path", &self.path);
1255         RegistryBindingDigest::from_normalized_binding(transcript.as_bytes())
1256     }
1257 
1258     fn endpoint(&self) -> String {
1259         let host = if self.host.contains(':') {
1260             format!("[{}]", self.host)
1261         } else {
1262             self.host.clone()
1263         };
1264         let port = match (&self.scheme[..], self.effective_port) {
1265             ("https", Some(443)) | ("http", Some(80)) | (_, None) => String::new(),
1266             (_, Some(port)) => format!(":{port}"),
1267         };
1268         format!("{}://{host}{port}{}", self.scheme, self.path)
1269     }
1270 }
