1934     /// Validates exact intent and operation-roster binding before reconciliation.
1935     pub fn validate_for_intent(&self, intent: &ReleaseIntentV1) -> Result<(), ReleaseReceiptError> {
1936         if self.schema_version != Self::SCHEMA_VERSION {
1937             return Err(ReleaseReceiptError::UnsupportedSchema {
1938                 found: self.schema_version,
1939             });
1940         }
1941         if self.intent_digest != intent.digest {
1942             return Err(ReleaseReceiptError::MismatchedIntent);
1943         }
1944         let expected: BTreeSet<_> = intent.operations.iter().map(|operation| operation.id.clone()).collect();
1945         let actual: BTreeSet<_> = self.outcomes.keys().cloned().collect();
1946         if actual != expected {
1947             return Err(ReleaseReceiptError::MismatchedOperationRoster);
1948         }
1949         Ok(())
1950     }
