1952     fn from_wire(wire: ReleaseReceiptV1Wire) -> Result<Self, ReleaseReceiptError> {
1953         if wire.schema_version != Self::SCHEMA_VERSION {
1954             return Err(ReleaseReceiptError::UnsupportedSchema {
1955                 found: wire.schema_version,
1956             });
1957         }
1958         let mut outcomes = BTreeMap::new();
1959         for entry in wire.outcomes {
1960             if !matches!(
1961                 entry.outcome,
1962                 OperationOutcome::Published | OperationOutcome::AlreadySatisfied
1963             ) {
1964                 return Err(ReleaseReceiptError::NonSuccessfulOperation {
1965                     id: Box::new(entry.operation),
1966                 });
1967             }
1968             if outcomes.insert(entry.operation.clone(), entry.outcome).is_some() {
1969                 return Err(ReleaseReceiptError::DuplicateOperation {
1970                     id: Box::new(entry.operation),
1971                 });
1972             }
1973         }
1974         Ok(Self {
1975             schema_version: wire.schema_version,
1976             intent_digest: wire.intent_digest,
1977             outcomes,
1978         })
1979     }
1980 }
