3493                 | ReleaseArtifactSlot::ChecksumManifest { .. }
3494                 | ReleaseArtifactSlot::ReleaseMetadata { .. } => None,
3495             })
3496             .collect::<Vec<_>>();
3497         entries.push(ChecksumRosterEntry {
3498             file_name: metadata_entry.slot.file_name().to_string(),
3499             digest: metadata_entry.digest.clone(),
3500         });
3501         entries.sort_by(|left, right| left.file_name.cmp(&right.file_name));
3502         if entries.len() != 5
3503             || entries.iter().any(|entry| entry.file_name == CHECKSUM_FILE_NAME)
3504             || entries.windows(2).any(|pair| pair[0].file_name == pair[1].file_name)
3505         {
3506             return Err(SuccessorError::InvalidChecksumRoster);
3507         }
3508         Ok(entries
3509             .into_iter()
3510             .flat_map(|entry| entry.line().into_bytes())
3511             .collect())
