1679     /// The locator is the release authority boundary: malformed membership
1680     /// must stop intent construction before source observation can invoke Git
1681     /// (and therefore before a later execution path could reach credentials
1682     /// or a provider). The child package makes this a real discoverable-member
1683     /// case rather than a root-only parse failure.
1684     #[test]
1685     fn malformed_root_membership_stops_intent_before_any_command_or_decision() {
1686         struct CountingRunner(AtomicUsize);
1687 
1688         impl CommandRunner for CountingRunner {
1689             fn run(&self, program: &str, _args: &[&str], _cwd: &Path) -> Result<CommandOutput, CommandError> {
1690                 self.0.fetch_add(1, Ordering::SeqCst);
1691                 Err(CommandError::Io {
1692                     program: program.to_owned(),
1693                     message: "membership failure must happen before any command".to_owned(),
1694                 })
1695             }
1696         }
1697 
1698         let dir = tempfile::tempdir().unwrap();
1699         let root = dir.path();
1700         std::fs::write(root.join("Cargo.toml"), "[workspace]\nmembers = [\"").unwrap();
1701         std::fs::create_dir_all(root.join("crates/discoverable")).unwrap();
1702         std::fs::write(
1703             root.join("crates/discoverable/Cargo.toml"),
1704             "[package]\nname = \"discoverable\"\nversion = \"1.0.0\"\n",
1705         )
1706         .unwrap();
1707 
1708         let runner = CountingRunner(AtomicUsize::new(0));
1709         let locator = crate::IgnoreWalkLocator::new(root);
1710         let decision = ReleaseDecisionV1::new(vec![callisto_model::ReleaseDecisionEntry {
1711             package: ReleasePackageId::new(Ecosystem::Cargo, "discoverable").unwrap(),
1712             target_version: Version::parse("1.0.0", VersionGrammar::SemVer).unwrap(),
1713             reasons: vec![callisto_model::ReleaseInclusionReason::ExplicitSelection],
1714         }])
1715         .unwrap();
1716         let result = build_release_intent(root, &locator, &runner, &decision, ExecutionTrustProfileV1::GitCommit);
1717 
1718         assert!(matches!(
1719             result,
