1775     /// Regression coverage for the callisto-graph derivation-drift finding:
1776     /// `derive_release_decision` and this module's `derive_release_inputs`
1777     /// each independently mapped a package's canonical manifests to
1778     /// `ReleasePackageId`s -- one via a plain per-manifest map, the other via
1779     /// a `BTreeSet<Ecosystem>` dedup step -- before both were migrated onto
1780     /// `release_decision::release_package_ids`. A dual-identity package (one
1781     /// directory, a Cargo manifest and an npm manifest, Case D) is exactly
1782     /// the shape that would have silently diverged had the two derivations
1783     /// disagreed: this proves the roster `derive_release_decision` computes
1784     /// and the snapshot `build_release_intent` derives from it agree on the
1785     /// exact same two `ReleasePackageId`s.
1786     #[test]
1787     fn dual_identity_package_release_ids_agree_between_decision_and_intent_derivation() {
1788         let dir = tempfile::tempdir().unwrap();
1789         std::fs::write(
1790             dir.path().join("Cargo.toml"),
1791             "[package]\nname = \"release-fixture\"\nversion = \"1.2.3\"\nedition = \"2021\"\n",
1792         )
1793         .unwrap();
1794         std::fs::write(
1795             dir.path().join("package.json"),
1796             r#"{"name":"release-fixture","version":"1.2.3"}"#,
1797         )
1798         .unwrap();
1799         // publish-to = [] keeps this test scoped to identity derivation --
1800         // no tag/registry operations, no git remote requirement.
1801         std::fs::write(
1802             dir.path().join("callisto.toml"),
1803             "[[package]]\nmatch = \"release-fixture\"\npublish-to = []\n",
1804         )
1805         .unwrap();
1806         for args in [
1807             ["init", "-q"].as_slice(),
1808             ["config", "user.email", "test@example.com"].as_slice(),
1809             ["config", "user.name", "Test"].as_slice(),
1810             ["config", "commit.gpgsign", "false"].as_slice(),
1811             ["add", "."].as_slice(),
1812             ["commit", "-q", "-m", "fixture"].as_slice(),
1813             ["checkout", "--detach", "-q", "HEAD"].as_slice(),
1814         ] {
1815             assert!(std::process::Command::new("git")
1816                 .args(args)
1817                 .current_dir(dir.path())
1818                 .status()
1819                 .unwrap()
1820                 .success());
1821         }
1822         let runner = RealGitRunner;
1823         let locator = crate::IgnoreWalkLocator::new(dir.path());
1824 
1825         let workspace = Workspace::load(dir.path().to_path_buf(), &locator, &runner).unwrap();
1826         let package_id = workspace
1827             .graph
1828             .packages()
1829             .next()
1830             .expect("workspace should discover the dual-identity package")
1831             .id
1832             .clone();
1833         assert_eq!(
1834             workspace.graph.packages().count(),
1835             1,
1836             "the Cargo and npm manifest must merge into one Case D package"
1837         );
1838 
1839         let plan = crate::VersionPlan {
1840             bumps: vec![crate::PlannedBump {
1841                 package: package_id,
1842                 from: Version::parse("1.2.3", VersionGrammar::SemVer).unwrap(),
1843                 to: Version::parse("1.3.0", VersionGrammar::SemVer).unwrap(),
1844                 severity: callisto_model::Severity::Minor,
1845                 governed_by: None,
1846                 reason: None,
1847                 writes: vec![],
1848             }],
1849             ..Default::default()
1850         };
1851         let decision = crate::commands::release_decision::derive_release_decision(&workspace, &plan).unwrap();
1852         let decided_ids: BTreeSet<_> = decision.entries.iter().map(|entry| entry.package.clone()).collect();
1853         assert_eq!(
1854             decided_ids,
1855             BTreeSet::from([
1856                 ReleasePackageId::new(Ecosystem::Cargo, "release-fixture").unwrap(),
1857                 ReleasePackageId::new(Ecosystem::Npm, "release-fixture").unwrap(),
1858             ]),
1859             "derive_release_decision must produce exactly the cargo and npm identities for the dual-identity package"
1860         );
1861 
1862         let intent = build_release_intent(
1863             dir.path(),
1864             &locator,
1865             &runner,
1866             &decision,
1867             ExecutionTrustProfileV1::GitCommit,
1868         )
1869         .unwrap();
1870         let intent_ids: BTreeSet<_> = intent
1871             .snapshot
1872             .packages
1873             .iter()
1874             .map(|input| input.package.clone())
1875             .collect();
1876         assert_eq!(
1877             intent_ids, decided_ids,
1878             "derive_release_inputs must agree with derive_release_decision on release package identity"
1879         );
1880     }
