2944     fn validate_slot_roster(
2945         release: &ProductReleaseId,
2946         destination: &ReleaseDestinationBinding,
2947         approved: &[ApprovedRegistryPackage],
2948         slots: &[ReleaseArtifactSlot],
2949     ) -> Result<(), SuccessorError> {
2950         if slots.windows(2).any(|pair| pair[0] == pair[1]) {
2951             return Err(SuccessorError::DuplicateSlot);
2952         }
2953         for slot in slots {
2954             slot.validate(release)?;
