2963             .iter()
2964             .filter_map(|slot| match slot {
2965                 ReleaseArtifactSlot::RegistryPackage {
2966                     package,
2967                     version,
2968                     registry,
2969                     format,
2970                     publication_policy,
2971                     ..
2972                 } if version == &release.version => Some(ApprovedRegistryPackage {
2973                     package: package.clone(),
2974                     registry: registry.clone(),
2975                     format: *format,
2976                     publication_policy: publication_policy.clone(),
2977                 }),
2978                 _ => None,
2979             })
2980             .collect::<BTreeSet<_>>();
