2982             != slots
2983                 .iter()
2984                 .filter(|slot| matches!(slot, ReleaseArtifactSlot::RegistryPackage { .. }))
2985                 .count()
2986             || registry_slots.iter().ne(approved.iter())
2987         {
2988             return Err(SuccessorError::RegistrySlotOutsideApprovedRoster);
2989         }
2990         let targets: BTreeSet<_> = slots
2991             .iter()
2992             .filter_map(|slot| match slot {
2993                 ReleaseArtifactSlot::ProductAsset { target, .. } => Some(*target),
2994                 _ => None,
2995             })
2996             .collect();
2997         if slots
2998             .iter()
2999             .filter(|slot| matches!(slot, ReleaseArtifactSlot::ProductAsset { .. }))
3000             .count()
3001             != ProductTarget::ALL.len()
3002             || targets.len() != ProductTarget::ALL.len()
3003             || !ProductTarget::ALL.iter().all(|target| targets.contains(target))
3004             || slots
3005                 .iter()
3006                 .filter(|slot| matches!(slot, ReleaseArtifactSlot::ChecksumManifest { .. }))
3007                 .count()
3008                 != 1
3009             || slots
3010                 .iter()
3011                 .filter(|slot| matches!(slot, ReleaseArtifactSlot::ReleaseMetadata { .. }))
3012                 .count()
3013                 != 1
3014         {
3015             return Err(SuccessorError::InvalidProductRoster);
3016         }
