3133     fn stable_order(
3134         prerequisites: &BTreeMap<ReleaseOperationId, Vec<ReleaseOperationId>>,
3135     ) -> Result<Vec<ReleaseOperationId>, SuccessorError> {
3136         let mut remaining: BTreeMap<_, _> = prerequisites
3137             .iter()
3138             .map(|(id, prerequisites)| (id.clone(), prerequisites.len()))
3139             .collect();
3140         let mut dependents = BTreeMap::<ReleaseOperationId, Vec<ReleaseOperationId>>::new();
3141         for (id, prerequisites) in prerequisites {
3142             for prerequisite in prerequisites {
3143                 dependents.entry(prerequisite.clone()).or_default().push(id.clone());
3144             }
3145         }
3146         let mut ready: BTreeSet<_> = remaining
3147             .iter()
3148             .filter_map(|(id, count)| (*count == 0).then_some(id.clone()))
3149             .collect();
3150         let mut ordered = Vec::with_capacity(prerequisites.len());
3151         while let Some(id) = ready.pop_first() {
3152             ordered.push(id.clone());
3153             for dependent in dependents.get(&id).into_iter().flatten() {
3154                 let count = remaining.get_mut(dependent).expect("known successor node");
3155                 *count -= 1;
3156                 if *count == 0 {
3157                     ready.insert(dependent.clone());
3158                 }
3159             }
3160         }
3161         (ordered.len() == prerequisites.len())
3162             .then_some(ordered)
3163             .ok_or(SuccessorError::CyclicPrerequisites)
3164     }
