3166     fn digest_intent(
3167         decision: &ReleaseDecisionV1,
3168         release: &ProductReleaseId,
3169         source: &CommitSha,
3170         destination: &ReleaseDestinationBinding,
3171         approved: &[ApprovedRegistryPackage],
3172         operations: &[ReleaseOperation],
3173         slots: &[ReleaseArtifactSlot],
3174     ) -> IntentDigest {
3175         let mut transcript = CanonicalTranscript::intent_v1();
3176         transcript.push_str("successor.schema", "1");
3177         transcript.push_bytes(
3178             "decision",
3179             serde_json::to_vec(decision).expect("validated release decision serializes"),
3180         );
3181         transcript.push_str("product", release.product.as_str());
3182         transcript.push_str("product.version", release.version.render());
3183         transcript.push_str("source", source.as_str());
3184         transcript.push_bytes(
3185             "destination",
3186             serde_json::to_vec(destination).expect("closed destination binding serializes"),
3187         );
3188         for registry in approved {
3189             transcript.push_bytes(
3190                 "approved-registry",
3191                 serde_json::to_vec(registry).expect("closed roster serializes"),
3192             );
3193         }
3194         for operation in operations {
3195             transcript.push_bytes(
3196                 "operation",
3197                 serde_json::to_vec(&operation.id).expect("closed operation serializes"),
3198             );
3199             for prerequisite in &operation.prerequisites {
3200                 transcript.push_bytes(
3201                     "prerequisite",
3202                     serde_json::to_vec(prerequisite).expect("closed operation serializes"),
3203                 );
3204             }
3205         }
3206         for slot in slots {
3207             transcript.push_bytes("slot", serde_json::to_vec(slot).expect("closed slot serializes"));
3208         }
3209         IntentDigest::from_transcript(&transcript)
3210     }
