3372 
3373         pub fn complete_with_generated_files(
3374             intent: &ReleaseIntent,
3375             payloads: &ValidatedPayloadEntries,
3376         ) -> Result<ReleaseArtifactBundle, SuccessorError> {
3377             payloads.validate_for(intent)?;
3378             let metadata = ReleaseDistributionMetadataV1::from_payloads(intent, payloads)?;
3379             let metadata_bytes = metadata.canonical_json();
3380             let metadata_slot = intent
3381                 .slots
3382                 .iter()
3383                 .find(|slot| matches!(slot, ReleaseArtifactSlot::ReleaseMetadata { .. }))
3384                 .expect("closed intent has metadata slot")
3385                 .clone();
3386             let metadata_entry = generated_entry(intent, metadata_slot, &metadata_bytes);
3387             let checksum_bytes = canonical_checksum_bytes(&payloads.entries, &metadata_entry)?;
3388             let checksum_slot = intent
3389                 .slots
3390                 .iter()
3391                 .find(|slot| matches!(slot, ReleaseArtifactSlot::ChecksumManifest { .. }))
3392                 .expect("closed intent has checksum slot")
3393                 .clone();
3394             let checksum_entry = generated_entry(intent, checksum_slot, &checksum_bytes);
3395             let mut entries = payloads.entries.clone();
3396             entries.extend([metadata_entry, checksum_entry]);
3397             entries.sort_by(|left, right| left.slot.cmp(&right.slot));
3398             validate_complete_entries(intent, &entries)?;
3399             Ok(ReleaseArtifactBundle {
3400                 manifest: Self {
3401                     schema_version: Self::SCHEMA_VERSION,
3402                     intent_digest: intent.digest.clone(),
3403                     source_commit: intent.source_commit.clone(),
3404                     entries,
3405                 },
3406                 metadata_bytes,
3407                 checksum_bytes,
3408             })
3409         }
