3411         pub fn validate_for_intent(&self, intent: &ReleaseIntent) -> Result<(), SuccessorError> {
3412             if self.schema_version != Self::SCHEMA_VERSION
3413                 || self.intent_digest != intent.digest
3414                 || self.source_commit != intent.source_commit
3415             {
3416                 return Err(SuccessorError::MismatchedManifest);
3417             }
3418             let payloads = ValidatedPayloadEntries::new(
3419                 intent,
3420                 self.entries
3421                     .iter()
3422                     .filter(|entry| {
3423                         matches!(
3424                             entry.slot,
3425                             ReleaseArtifactSlot::RegistryPackage { .. } | ReleaseArtifactSlot::ProductAsset { .. }
3426                         )
3427                     })
3428                     .cloned()
3429                     .collect(),
3430             )?;
3431             (*self == Self::complete(intent, &payloads)?)
3432                 .then_some(())
3433                 .ok_or(SuccessorError::MismatchedManifest)
