3423                         matches!(
3424                             entry.slot,
3425                             ReleaseArtifactSlot::RegistryPackage { .. } | ReleaseArtifactSlot::ProductAsset { .. }
3426                         )
3427                     })
3428                     .cloned()
3429                     .collect(),
3430             )?;
3431             (*self == Self::complete(intent, &payloads)?)
3432                 .then_some(())
3433                 .ok_or(SuccessorError::MismatchedManifest)
