3700                 | ReleaseArtifactSlot::ReleaseMetadata { .. } => None,
3701             })
3702             .collect::<Vec<_>>();
3703         entries.push(ChecksumRosterEntry {
3704             file_name: metadata_entry.slot.file_name().to_string(),
3705             digest: metadata_entry.digest.clone(),
3706         });
3707         entries.sort_by(|left, right| left.file_name.cmp(&right.file_name));
3708         if entries.len() != 5
3709             || entries.iter().any(|entry| entry.file_name == CHECKSUM_FILE_NAME)
3710             || entries.windows(2).any(|pair| pair[0].file_name == pair[1].file_name)
3711         {
3712             return Err(SuccessorError::InvalidChecksumRoster);
3713         }
3714         Ok(entries
3715             .into_iter()
3716             .flat_map(|entry| entry.line().into_bytes())
