3687     fn canonical_checksum_bytes(
3688         payload_entries: &[ReleaseArtifactEntry],
3689         metadata_entry: &ReleaseArtifactEntry,
3690     ) -> Result<Vec<u8>, SuccessorError> {
3691         let mut entries = payload_entries
3692             .iter()
3693             .filter_map(|entry| match entry.slot {
3694                 ReleaseArtifactSlot::ProductAsset { .. } => Some(ChecksumRosterEntry {
3695                     file_name: entry.slot.file_name().to_string(),
3696                     digest: entry.digest.clone(),
