4150     fn validate_evidence(
4151         intent: &ReleaseIntent,
4152         expected: &ObservationExpectations,
4153         entry: &ObservedOperation,
4154     ) -> Result<(), SuccessorError> {
4155         match (&entry.operation, &entry.evidence) {
4156             (
4157                 ReleaseOperationId::RegistryArtifactPublish {
4158                     package,
4159                     version,
4160                     registry,
4161                     slot,
4162                 },
4163                 ReleaseObservationEvidence::RegistryArtifact {
4164                     schema_version: 1,
4165                     package: evidence_package,
4166                     version: evidence_version,
4167                     registry: evidence_registry,
4168                     slot: evidence_slot,
4169                     digest,
4170                     byte_length,
4171                 },
4172             ) if package == evidence_package
4173                 && version == evidence_version
4174                 && registry == evidence_registry
4175                 && slot == evidence_slot
4176                 && expected.entries.get(slot) == Some(&(digest.clone(), *byte_length)) =>
4177             {
4178                 Ok(())
4179             }
4180             (
4181                 ReleaseOperationId::ProductTag { release, tag },
4182                 ReleaseObservationEvidence::RemoteTag {
4183                     schema_version: 1,
4184                     release: evidence_release,
4185                     name,
4186                     target,
4187                     annotation_digest,
4188                 },
4189             ) if release == evidence_release
4190                 && tag == name
4191                 && target == &intent.source_commit
4192                 && annotation_digest == &expected.tag_annotation_digest =>
4193             {
4194                 Ok(())
4195             }
4196             (
4197                 ReleaseOperationId::ForgePrepare { release, .. },
4198                 ReleaseObservationEvidence::ForgePrepare {
4199                     schema_version: 1,
4200                     release: evidence_release,
4201                     lifecycle: ForgePrepareLifecycle::Draft | ForgePrepareLifecycle::PublishedSuccessor,
4202                 },
4203             ) if release == evidence_release => Ok(()),
4204             (
4205                 ReleaseOperationId::ForgePublish { release, .. },
4206                 ReleaseObservationEvidence::ForgePublish {
4207                     schema_version: 1,
4208                     release: evidence_release,
4209                     asset_roster_digest,
4210                 },
4211             ) if release == evidence_release && asset_roster_digest == &expected.asset_roster_digest => Ok(()),
4212             (
4213                 ReleaseOperationId::ArtifactUpload { release, slot },
4214                 ReleaseObservationEvidence::ForgeAsset {
4215                     schema_version: 1,
4216                     release: evidence_release,
4217                     slot: evidence_slot,
4218                     digest,
4219                     byte_length,
4220                 },
4221             ) if release == evidence_release
4222                 && slot == evidence_slot
4223                 && expected.entries.get(slot) == Some(&(digest.clone(), *byte_length)) =>
4224             {
4225                 Ok(())
4226             }
4227             _ => Err(SuccessorError::MismatchedObservationEvidence),
4228         }
4229     }
