 264         .entries
 265         .iter()
 266         .map(|entry| (entry.package.clone(), entry.target_version.clone()))
 267         .collect::<std::collections::BTreeMap<_, _>>();
 268 
 269     let changed_paths = changed
 270         .iter()
 271         .filter_map(|(status, path)| matches!(status.as_str(), "A" | "M").then_some(path.as_str()))
