1272 fn target_fingerprint<R: CommandRunner, D: DependencyResolver>(
1273     workspace: &Workspace<'_, R, D>,
1274     target: &PublishTarget,
1275 ) -> Result<SemanticInputDigest, GraphError> {
1276     let mut transcript = CanonicalTranscript::semantic_input_v1();
1277     // Single source of truth for the "kind" string, shared with
1278     // `PublishTarget::config_str`'s other diagnostic/config-parsing callers
1279     // instead of re-hardcoding these per-variant literals here too.
1280     transcript.push_str("target.kind", target.config_str());
1281     match target {
1282         PublishTarget::CratesIo | PublishTarget::GitHubRelease | PublishTarget::None => {}
1283         PublishTarget::Npm { access, .. } => {
1284             push_registry_binding(&mut transcript, prepared_registry_binding(workspace, target)?.identity)?;
1285             transcript.push_str(
1286                 "target.access",
1287                 match access {
1288                     Some(callisto_model::NpmAccess::Public) => "public",
1289                     Some(callisto_model::NpmAccess::Restricted) => "restricted",
1290                     None => "default",
1291                 },
1292             );
1293         }
1294         PublishTarget::Pypi { .. } | PublishTarget::NuGet { .. } => {
1295             push_registry_binding(&mut transcript, prepared_registry_binding(workspace, target)?.identity)?;
1296         }
1297         #[allow(unreachable_patterns)]
1298         _ => {
1299             return Err(GraphError::UnsupportedRelease {
1300                 feature: UnsupportedReleaseFeature::PublishTarget,
1301             })
1302         }
1303     }
1304     Ok(SemanticInputDigest::from_transcript(&transcript))
1305 }
