1387     if !matches!(parsed.scheme(), "http" | "https") {
1388         return Err(GraphError::UnsafeRegistryBinding {
1389             registry: registry.to_string(),
1390             reason: "URL scheme must be http or https",
1391         });
1392     }
1393     if !parsed.username().is_empty() || parsed.password().is_some() {
1394         return Err(GraphError::UnsafeRegistryBinding {
1395             registry: registry.to_string(),
1396             reason: "userinfo is forbidden",
1397         });
1398     }
