1405     if parsed.fragment().is_some() {
1406         return Err(GraphError::UnsafeRegistryBinding {
1407             registry: registry.to_string(),
1408             reason: "fragment is forbidden",
1409         });
1410     }
1411     Ok(RegistryBindingV1 {
1412         scheme: parsed.scheme().to_ascii_lowercase(),
1413         host: parsed.host_str().expect("validated authority").to_ascii_lowercase(),
1414         effective_port: parsed.port_or_known_default(),
1415         path: parsed.path().to_string(),
1416     })
1417 }
