1851         let decision = crate::commands::release_decision::derive_release_decision(&workspace, &plan).unwrap();
1852         let decided_ids: BTreeSet<_> = decision.entries.iter().map(|entry| entry.package.clone()).collect();
1853         assert_eq!(
