190 // --- SPEC-ARCH-RELEASE-ERROR-TAXONOMY (PR1-PR4, complete) ----------------
191 //
192 // Enforcement for the `GraphError::ReleaseIntentStale` (E124) struct-variant
193 // migration: staleness carries a real `StaleReason`, constructible only
194 // from `commands/release.rs`. The `StaleReason::legacy_unclassified()`
195 // migration ratchet used during PR1-PR3 reached zero callers across all
196 // three release-executor files in PR4 and was deleted, along with the
197 // ratchet's own pinned-count test.
198 
199 /// This crate's own `src/` directory, independent of `workspace_root()`
200 /// (which points at the whole-workspace root two levels up).
201 fn graph_crate_src_dir() -> PathBuf {
202     PathBuf::from(env!("CARGO_MANIFEST_DIR")).join("src")
203 }
204 
205 /// Reads `relative` (forward-slash separated, relative to this crate's
206 /// `src/`, e.g. `"commands/release.rs"`) with `#[cfg(test)] mod tests { ... }`
207 /// blocks stripped.
208 fn read_production_source(relative: &str) -> String {
209     let path = graph_crate_src_dir().join(relative);
210     let content = fs::read_to_string(&path).unwrap_or_else(|e| panic!("could not read {path:?}: {e}"));
211     strip_test_modules(&content)
212 }
