214 /// `StaleReason`'s four fresh-re-observation constructors (AC-001).
215 const STALE_REASON_REAL_CONSTRUCTORS: [&str; 4] = [
216     "trust_evidence_changed",
217     "source_identity_changed",
218     "git_remote_changed",
219     "intent_differs_from_fresh_derivation",
220 ];
