222 /// AC-002: `GraphError::ReleaseIntentStale` is constructed only via one of
223 /// `StaleReason`'s four fresh-re-observation constructors, and only from
224 /// `commands/release.rs` -- the SPEC-ARCH-RELEASE-ERROR-TAXONOMY migration
225 /// (PR1-PR4) eliminated every other construction site workspace-wide.
226 #[test]
227 fn release_intent_stale_is_constructed_only_by_fresh_reobservation() {
228     let release_rs = graph_crate_src_dir().join("commands/release.rs");
229     let mut files = Vec::new();
230     collect_rust_src_files(&graph_crate_src_dir(), &mut files);
231 
232     let mut violations = Vec::new();
233     for file in files {
234         if file == release_rs {
235             continue;
236         }
237         let Ok(content) = fs::read_to_string(&file) else {
238             continue;
239         };
240         let production = strip_test_modules(&content);
241         for name in STALE_REASON_REAL_CONSTRUCTORS {
242             if production.contains(name) {
243                 violations.push(format!("{}: references `{name}`", file.display()));
244             }
245         }
246     }
247 
248     assert!(
249         violations.is_empty(),
250         "StaleReason's fresh-re-observation constructors must be referenced only from \
251          commands/release.rs: {violations:#?}"
252     );
