 12 pub fn handle(args: TagArgs, global: &GlobalArgs) -> Result<ExitCode, CliError> {
 13     let runner = CliCommandRunner;
 14     let ws = load_workspace(global, &runner)?;
 15 
 16     // Promote graph diagnostics (including crosscheck failures) per
 17     // `--strict`/`--strict-graph` and abort before creating any tags.
 18     abort_on_crosscheck_failures(ws.graph.diagnostics(), args.strict, args.strict_graph)?;
 19 
 20     let plan_text = crate::commands::read_json_arg(&args.plan)?;
 21 
 22     let plan: PublishPlan =
 23         serde_json::from_str(&plan_text).map_err(|e| CliError::Other(format!("Failed to parse publish plan: {e}")))?;
 24 
 25     match global.format {
 26         OutputFormat::Json => write_json(&mut std::io::stdout(), &plan)?,
 27         OutputFormat::Text => {
 28             let _floating_major = args.floating_major;
 29             println!("Tag preview only; no Git tags were created. Use `callisto release execute` after validating a durable release intent.");
 30         }
 31     }
 32 
 33     Ok(ExitCode::SUCCESS)
 34 }
