2924             release.product.clone(),
2925             decision.entries.iter().map(|entry| entry.target_version.clone()),
2926         )?;
2927         if &derived != release {
2928             return Err(SuccessorError::DecisionProductMismatch);
2929         }
2930         let decision_versions = decision
2931             .entries
2932             .iter()
2933             .map(|entry| (&entry.package, &entry.target_version))
2934             .collect::<BTreeMap<_, _>>();
2935         if approved
2936             .iter()
2937             .any(|entry| decision_versions.get(&entry.package).copied() != Some(&release.version))
2938         {
2939             return Err(SuccessorError::RegistryPackageOutsideDecision);
2940         }
2941         Ok(())
