3024     fn validate_operations(
3025         release: &ProductReleaseId,
3026         destination: &ReleaseDestinationBinding,
3027         approved: &[ApprovedRegistryPackage],
3028         operations: &[ReleaseOperation],
3029         slots: &[ReleaseArtifactSlot],
3030     ) -> Result<(), SuccessorError> {
3031         let ids: BTreeSet<_> = operations.iter().map(|operation| operation.id.clone()).collect();
3032         if ids.len() != operations.len() {
3033             return Err(SuccessorError::DuplicateOperation);
3034         }
3035         for operation in operations {
3036             operation.id.validate(release)?;
3037             if operation.prerequisites.windows(2).any(|pair| pair[0] >= pair[1])
3038                 || operation.prerequisites.iter().any(|id| !ids.contains(id))
3039             {
3040                 return Err(SuccessorError::InvalidPrerequisite);
3041             }
3042         }
3043         let expected_uploads: BTreeSet<_> = slots.iter().filter(|slot| slot.release().is_some()).cloned().collect();
3044         let uploads: BTreeSet<_> = operations
3045             .iter()
3046             .filter_map(|operation| match &operation.id {
3047                 ReleaseOperationId::ArtifactUpload { slot, .. } => Some(slot.clone()),
3048                 _ => None,
3049             })
3050             .collect();
3051         if uploads != expected_uploads {
3052             return Err(SuccessorError::InvalidProductRoster);
3053         }
3054         let registry_operations: BTreeSet<_> = operations
3055             .iter()
3056             .filter_map(|operation| match &operation.id {
3057                 ReleaseOperationId::RegistryArtifactPublish { slot, .. } => Some(slot.clone()),
3058                 _ => None,
3059             })
3060             .collect();
3061         let registry_slots: BTreeSet<_> = slots
3062             .iter()
3063             .filter(|slot| matches!(slot, ReleaseArtifactSlot::RegistryPackage { .. }))
3064             .cloned()
3065             .collect();
3066         if registry_operations != registry_slots || registry_slots.len() != approved.len() {
3067             return Err(SuccessorError::InvalidPackageOperation);
3068         }
3069         let tags = operations
3070             .iter()
3071             .filter(|operation| matches!(operation.id, ReleaseOperationId::ProductTag { .. }))
3072             .collect::<Vec<_>>();
3073         let prepares = operations
3074             .iter()
3075             .filter(|operation| matches!(operation.id, ReleaseOperationId::ForgePrepare { .. }))
3076             .collect::<Vec<_>>();
3077         let publishes = operations
3078             .iter()
3079             .filter(|operation| matches!(operation.id, ReleaseOperationId::ForgePublish { .. }))
3080             .collect::<Vec<_>>();
3081         if tags.len() != 1 || prepares.len() != 1 || publishes.len() != 1 {
3082             return Err(SuccessorError::InvalidProductOperation);
3083         }
3084         let mut registry_ids = operations
3085             .iter()
3086             .filter_map(|operation| {
3087                 matches!(operation.id, ReleaseOperationId::RegistryArtifactPublish { .. })
3088                     .then_some(operation.id.clone())
3089             })
3090             .collect::<Vec<_>>();
3091         registry_ids.sort();
3092         if tags[0].prerequisites != registry_ids
3093             || prepares[0].prerequisites != [tags[0].id.clone()]
3094             || operations.iter().any(|operation| {
3095                 matches!(operation.id, ReleaseOperationId::ArtifactUpload { .. })
3096                     && operation.prerequisites != [prepares[0].id.clone()]
3097             })
3098         {
3099             return Err(SuccessorError::InvalidPrerequisite);
3100         }
3101         let prepare_repository = match &prepares[0].id {
3102             ReleaseOperationId::ForgePrepare { repository, .. } => repository,
3103             _ => unreachable!("filtered ForgePrepare"),
3104         };
3105         let publish_repository = match &publishes[0].id {
3106             ReleaseOperationId::ForgePublish { repository, .. } => repository,
3107             _ => unreachable!("filtered ForgePublish"),
3108         };
3109         if prepare_repository != publish_repository || prepare_repository != destination.forge_repository() {
3110             return Err(SuccessorError::MismatchedForgeRepository);
3111         }
3112         let mut upload_ids = operations
3113             .iter()
3114             .filter_map(|operation| {
3115                 matches!(operation.id, ReleaseOperationId::ArtifactUpload { .. }).then_some(operation.id.clone())
3116             })
3117             .collect::<Vec<_>>();
3118         upload_ids.sort();
3119         if publishes[0].prerequisites != upload_ids {
3120             return Err(SuccessorError::InvalidPrerequisite);
3121         }
3122         let edges: BTreeMap<_, _> = operations
3123             .iter()
3124             .map(|operation| (operation.id.clone(), operation.prerequisites.clone()))
3125             .collect();
3126         let canonical = stable_order(&edges)?;
3127         if operations.iter().map(|operation| &operation.id).ne(canonical.iter()) {
3128             return Err(SuccessorError::NonCanonicalOperationOrder);
3129         }
3130         Ok(())
3131     }
