3101         let uploads: BTreeSet<_> = operations
3102             .iter()
3103             .filter_map(|operation| match &operation.id {
3104                 ReleaseOperationId::ArtifactUpload { slot, .. } => Some(slot.clone()),
3105                 _ => None,
