3107             .collect();
3108         if uploads != expected_uploads {
3109             return Err(SuccessorError::InvalidProductRoster);
3110         }
3111         let registry_operations: BTreeSet<_> = operations
3112             .iter()
3113             .filter_map(|operation| match &operation.id {
3114                 ReleaseOperationId::RegistryArtifactPublish { slot, .. } => Some(slot.clone()),
3115                 _ => None,
3116             })
