3118         let registry_slots: BTreeSet<_> = slots
3119             .iter()
3120             .filter(|slot| matches!(slot, ReleaseArtifactSlot::RegistryPackage { .. }))
3121             .cloned()
3122             .collect();
3123         if registry_operations != registry_slots || registry_slots.len() != approved.len() {
3124             return Err(SuccessorError::InvalidPackageOperation);
3125         }
3126         let tags = operations
3127             .iter()
3128             .filter(|operation| matches!(operation.id, ReleaseOperationId::ProductTag { .. }))
3129             .collect::<Vec<_>>();
3130         let prepares = operations
3131             .iter()
3132             .filter(|operation| matches!(operation.id, ReleaseOperationId::ForgePrepare { .. }))
3133             .collect::<Vec<_>>();
3134         let publishes = operations
3135             .iter()
3136             .filter(|operation| matches!(operation.id, ReleaseOperationId::ForgePublish { .. }))
3137             .collect::<Vec<_>>();
3138         if tags.len() != 1 || prepares.len() != 1 || publishes.len() != 1 {
