3153                     && operation.prerequisites != [prepares[0].id.clone()]
3154             })
3155         {
3156             return Err(SuccessorError::InvalidPrerequisite);
3157         }
3158         let prepare_repository = match &prepares[0].id {
3159             ReleaseOperationId::ForgePrepare { repository, .. } => repository,
3160             _ => unreachable!("filtered ForgePrepare"),
3161         };
3162         let publish_repository = match &publishes[0].id {
3163             ReleaseOperationId::ForgePublish { repository, .. } => repository,
3164             _ => unreachable!("filtered ForgePublish"),
3165         };
3166         if prepare_repository != publish_repository || prepare_repository != destination.forge_repository() {
3167             return Err(SuccessorError::MismatchedForgeRepository);
3168         }
3169         let mut upload_ids = operations
3170             .iter()
3171             .filter_map(|operation| {
3172                 matches!(operation.id, ReleaseOperationId::ArtifactUpload { .. }).then_some(operation.id.clone())
3173             })
3174             .collect::<Vec<_>>();
3175         upload_ids.sort();
3176         if publishes[0].prerequisites != upload_ids {
3177             return Err(SuccessorError::InvalidPrerequisite);
3178         }
3179         let edges: BTreeMap<_, _> = operations
