3223     fn digest_intent(
3224         decision: &ReleaseDecisionV1,
3225         release: &ProductReleaseId,
3226         source: &CommitSha,
3227         destination: &ReleaseDestinationBinding,
3228         approved: &[ApprovedRegistryPackage],
3229         operations: &[ReleaseOperation],
3230         slots: &[ReleaseArtifactSlot],
3231     ) -> IntentDigest {
3232         let mut transcript = CanonicalTranscript::intent_v1();
3233         transcript.push_str("successor.schema", "1");
3234         transcript.push_bytes(
3235             "decision",
3236             serde_json::to_vec(decision).expect("validated release decision serializes"),
3237         );
3238         transcript.push_str("product", release.product.as_str());
3239         transcript.push_str("product.version", release.version.render());
3240         transcript.push_str("source", source.as_str());
3241         transcript.push_bytes(
3242             "destination",
3243             serde_json::to_vec(destination).expect("closed destination binding serializes"),
3244         );
3245         for registry in approved {
3246             transcript.push_bytes(
3247                 "approved-registry",
3248                 serde_json::to_vec(registry).expect("closed roster serializes"),
3249             );
3250         }
3251         for operation in operations {
3252             transcript.push_bytes(
3253                 "operation",
3254                 serde_json::to_vec(&operation.id).expect("closed operation serializes"),
3255             );
3256             for prerequisite in &operation.prerequisites {
3257                 transcript.push_bytes(
3258                     "prerequisite",
3259                     serde_json::to_vec(prerequisite).expect("closed operation serializes"),
3260                 );
3261             }
3262         }
3263         for slot in slots {
3264             transcript.push_bytes("slot", serde_json::to_vec(slot).expect("closed slot serializes"));
3265         }
3266         IntentDigest::from_transcript(&transcript)
3267     }
