 83     /// Returns the immutable, normalized endpoint set selected by a named
 84     /// profile for one supported ecosystem. This is the only durable release
 85     /// lookup; callers must not fall back to `RegistryConfig::url`.
 86     pub fn release_registry(
 87         &self,
 88         profile_name: &str,
 89         ecosystem: Ecosystem,
 90     ) -> Result<(&RegistryKey, &RegistryEndpoints), ConfigError> {
 91         let (_, profile) = self.release_profile(profile_name)?;
 92         let key = profile
 93             .registry_for(ecosystem)
 94             .ok_or(ConfigError::UnsupportedReleaseRegistryEcosystem { ecosystem })?;
 95         let registry = validated_registry_binding(&self.registries, profile_name, key, ecosystem)?;
 96         let endpoints = registry
 97             .endpoints
 98             .as_ref()
 99             .ok_or_else(|| ConfigError::IncompleteReleaseRegistry {
100                 profile: profile_name.to_string(),
101                 registry: key.as_str().to_string(),
102             })?;
103         Ok((key, endpoints))
104     }
