6843     /// Residual instance of the same defect class fixed above for
6844     /// `attestation_policy`: `ReleaseOperationId::cmp` used to key on
6845     /// `version.render()` alone, dropping `version.grammar()`. The same
6846     /// literal string parses under more than one grammar -- `"1.2.3"` is
6847     /// valid both as SemVer and PEP 440 -- so two `ReleaseOperationId`s
6848     /// that are Eq-distinct only by `Version::grammar` collapsed to
6849     /// `Ordering::Equal` under the old `render()`-only `Ord`, violating
6850     /// the invariant `BTreeSet`/`BTreeMap` require: `a.cmp(b) == Equal`
6851     /// iff `a == b`.
6852     #[test]
6853     fn operation_ids_differing_only_by_version_grammar_stay_distinct_under_ord() {
6854         let package = ReleasePackageId::parse("cargo/demo").unwrap();
6855         let v_semver = Version::parse("1.2.3", VersionGrammar::SemVer).unwrap();
6856         let v_pep440 = Version::parse("1.2.3", VersionGrammar::Pep440).unwrap();
6857 
6858         // Precondition: the identical literal renders identically under both
6859         // grammars, but the parsed Versions are NOT the same value -- this is
6860         // exactly the collision `version_ord_key` must resolve.
6861         assert_eq!(v_semver.render(), v_pep440.render());
6862         assert_ne!(
6863             v_semver, v_pep440,
6864             "SemVer and PEP 440 parses of the identical literal must remain Eq-distinct"
6865         );
6866 
6867         let id_a = ReleaseOperationId::tag(package.clone(), v_semver);
6868         let id_b = ReleaseOperationId::tag(package, v_pep440);
6869 
6870         assert_ne!(id_a, id_b, "distinct version grammars must stay Eq-distinct");
6871         assert_ne!(
6872             id_a.cmp(&id_b),
6873             Ordering::Equal,
6874             "distinct version grammars must not compare Ord::Equal"
6875         );
6876 
6877         let mut ids = BTreeSet::new();
6878         assert!(ids.insert(id_a.clone()), "first id must insert");
6879         assert!(
6880             ids.insert(id_b.clone()),
6881             "second id must NOT be displaced by the first in a BTreeSet"
6882         );
6883         assert_eq!(ids.len(), 2, "BTreeSet must not silently collapse distinct-grammar ids");
6884 
6885         // Sanity check the ordinary case still behaves: several distinct
6886         // plain SemVer versions of the same package/role must all survive
6887         // as separate BTreeSet entries too, not just the grammar-collision
6888         // edge case above.
6889         let mut ordinary_ids = BTreeSet::new();
6890         for raw in ["1.0.0", "1.2.3", "2.0.0", "0.9.9"] {
6891             let id = ReleaseOperationId::tag(
6892                 ReleasePackageId::parse("cargo/demo").unwrap(),
6893                 Version::parse(raw, VersionGrammar::SemVer).unwrap(),
6894             );
6895             assert!(
6896                 ordinary_ids.insert(id),
6897                 "version {raw} must not collide with a prior entry"
6898             );
6899         }
6900         assert_eq!(ordinary_ids.len(), 4);
6901     }
