282 /// Parses and canonicalizes a credential-free HTTP(S) registry endpoint.
283 ///
284 /// One resolver owns this normalization so observation and dispatch never
285 /// disagree about a destination because of host casing, a default port, or a
286 /// trailing slash. Credentials, query parameters, and fragments are rejected
287 /// rather than normalized away because they must never become durable config.
288 fn normalize_registry_url(registry: &str, field: &'static str, raw: &str) -> Result<String, ConfigError> {
289     let mut url = Url::parse(raw).map_err(|error| ConfigError::InvalidRegistryEndpoint {
290         registry: registry.to_string(),
291         field,
292         value: raw.to_string(),
293         reason: error.to_string(),
294     })?;
295     if !matches!(url.scheme(), "http" | "https") {
296         return Err(ConfigError::InvalidRegistryEndpoint {
297             registry: registry.to_string(),
298             field,
299             value: raw.to_string(),
300             reason: "scheme must be http or https".to_string(),
301         });
302     }
303     if url.host_str().is_none() || url.cannot_be_a_base() {
304         return Err(ConfigError::InvalidRegistryEndpoint {
305             registry: registry.to_string(),
306             field,
307             value: raw.to_string(),
308             reason: "URL must have an authority and hierarchical path".to_string(),
309         });
310     }
311     let authority_contains_userinfo = raw
312         .split_once("://")
313         .map(|(_, remainder)| remainder.split('/').next().unwrap_or_default().contains('@'))
314         .unwrap_or(false);
315     if authority_contains_userinfo || !url.username().is_empty() || url.password().is_some() {
316         return Err(ConfigError::InvalidRegistryEndpoint {
317             registry: registry.to_string(),
318             field,
319             value: raw.to_string(),
320             reason: "userinfo is forbidden".to_string(),
321         });
322     }
323     if url.query().is_some() || url.fragment().is_some() {
324         return Err(ConfigError::InvalidRegistryEndpoint {
325             registry: registry.to_string(),
326             field,
327             value: raw.to_string(),
328             reason: "query parameters and fragments are forbidden".to_string(),
329         });
330     }
331 
332     if matches!((url.scheme(), url.port()), ("http", Some(80)) | ("https", Some(443))) {
333         url.set_port(None).map_err(|()| ConfigError::InvalidRegistryEndpoint {
334             registry: registry.to_string(),
335             field,
336             value: raw.to_string(),
337             reason: "default port could not be normalized".to_string(),
338         })?;
339     }
340     let normalized_path = if url.path() == "/" {
341         "/".to_string()
342     } else {
343         url.path().trim_end_matches('/').to_string()
344     };
345     url.set_path(&normalized_path);
346     Ok(url.to_string())
347 }
