271 fn parse_release_repository(field: &'static str, raw: &str) -> Result<GitHubRepository, ConfigError> {
272     // GitHub repository routing is case-insensitive. Lowercasing here makes
273     // equality and rehearsal-isolation checks operate on external identity,
274     // not on a cosmetic spelling difference.
275     GitHubRepository::parse(&raw.to_ascii_lowercase()).map_err(|error| ConfigError::InvalidReleaseRepository {
276         field,
