422 fn registry_binding<'a>(
423     registries: &'a BTreeMap<RegistryKey, RegistryConfig>,
424     profile: &str,
425     key: &str,
426     expected: Ecosystem,
427 ) -> Result<(RegistryKey, &'a RegistryEndpoints), ConfigError> {
428     let registry_key = RegistryKey(key.to_string());
429     let registry = validated_registry_binding(registries, profile, &registry_key, expected)?;
430     let endpoints = registry
431         .endpoints
432         .as_ref()
433         .ok_or_else(|| ConfigError::IncompleteReleaseRegistry {
434             profile: profile.to_string(),
435             registry: key.to_string(),
436         })?;
437     Ok((registry_key, endpoints))
438 }
439 
440 fn validated_registry_binding<'a>(
441     registries: &'a BTreeMap<RegistryKey, RegistryConfig>,
442     profile: &str,
443     registry_key: &RegistryKey,
444     expected: Ecosystem,
445 ) -> Result<&'a RegistryConfig, ConfigError> {
446     let registry = registries
447         .get(registry_key)
448         .ok_or_else(|| ConfigError::UnknownReleaseRegistry {
449             profile: profile.to_string(),
450             registry: registry_key.as_str().to_string(),
451         })?;
452     if registry.kind != expected {
453         return Err(ConfigError::ReleaseRegistryEcosystemMismatch {
454             profile: profile.to_string(),
455             registry: registry_key.as_str().to_string(),
456             expected,
457             found: registry.kind,
458         });
459     }
460     Ok(registry)
461 }
