463 fn resolve_release_config(
464     raw: crate::config::raw::RawReleaseConfig,
465     registries: &BTreeMap<RegistryKey, RegistryConfig>,
466 ) -> Result<ReleaseConfig, ConfigError> {
467     if !is_canonical_release_name(&raw.product.name) {
468         return Err(ConfigError::InvalidReleaseProductName { name: raw.product.name });
469     }
470     let provenance_repository = parse_release_repository(
471         "release.product.provenance-repository",
472         &raw.product.provenance_repository,
473     )?;
474     if !is_safe_build_workflow(&raw.product.build_workflow) {
475         return Err(ConfigError::InvalidReleaseWorkflow {
476             workflow: raw.product.build_workflow,
477         });
478     }
479     let product = ReleaseProductConfig {
480         name: raw.product.name,
481         provenance_repository,
482         build_workflow: raw.product.build_workflow,
483     };
484 
485     let mut profiles = BTreeMap::new();
486     let mut production_profile = None;
487     let mut rehearsal_count = 0usize;
488     for (name, raw_profile) in raw.profiles {
489         if !is_canonical_release_name(&name) {
490             return Err(ConfigError::InvalidReleaseProfileName { name });
491         }
492         let kind = match raw_profile.kind.as_str() {
493             "production" => ReleaseProfileKind::Production,
494             "rehearsal" => ReleaseProfileKind::Rehearsal,
495             _ => {
496                 return Err(ConfigError::InvalidReleaseProfileKind {
497                     profile: name,
498                     kind: raw_profile.kind,
499                 })
500             }
501         };
502         let forge_repository =
503             parse_release_repository("release.profiles.*.forge-repository", &raw_profile.forge_repository)?;
504         let (cargo_registry, _) = registry_binding(registries, &name, &raw_profile.cargo_registry, Ecosystem::Cargo)?;
505         let (npm_registry, _) = registry_binding(registries, &name, &raw_profile.npm_registry, Ecosystem::Npm)?;
506         let (pypi_registry, _) = registry_binding(registries, &name, &raw_profile.pypi_registry, Ecosystem::Pypi)?;
507 
508         if kind == ReleaseProfileKind::Production {
509             if production_profile.replace(name.clone()).is_some() {
510                 return Err(ConfigError::InvalidProductionProfileCount { found: 2 });
511             }
512         } else {
513             rehearsal_count += 1;
514         }
515         profiles.insert(
516             name,
517             ReleaseProfileConfig {
518                 kind,
519                 forge_repository,
520                 cargo_registry,
521                 npm_registry,
522                 pypi_registry,
523             },
524         );
525     }
526 
527     let production_profile = production_profile.ok_or(ConfigError::InvalidProductionProfileCount { found: 0 })?;
528     if rehearsal_count == 0 {
529         return Err(ConfigError::InvalidRehearsalProfileCount { found: 0 });
530     }
531     let production = profiles
532         .get(&production_profile)
533         .expect("production profile name came from this map");
534     for (name, rehearsal) in profiles
535         .iter()
536         .filter(|(_, profile)| profile.kind == ReleaseProfileKind::Rehearsal)
537     {
538         if rehearsal.forge_repository == production.forge_repository {
539             return Err(ConfigError::RehearsalDestinationNotIsolated {
540                 profile: name.clone(),
541                 destination: "forge repository",
542             });
543         }
544         for (ecosystem, rehearsal_key, production_key) in [
545             (Ecosystem::Cargo, &rehearsal.cargo_registry, &production.cargo_registry),
546             (Ecosystem::Npm, &rehearsal.npm_registry, &production.npm_registry),
547             (Ecosystem::Pypi, &rehearsal.pypi_registry, &production.pypi_registry),
548         ] {
549             let rehearsal_endpoints = registries
550                 .get(rehearsal_key)
551                 .and_then(|registry| registry.endpoints.as_ref())
552                 .expect("profile registry was validated above");
553             let production_endpoints = registries
554                 .get(production_key)
555                 .and_then(|registry| registry.endpoints.as_ref())
556                 .expect("profile registry was validated above");
557             if rehearsal_endpoints
558                 .urls()
559                 .iter()
560                 .any(|candidate| production_endpoints.urls().contains(candidate))
561             {
562                 return Err(ConfigError::RehearsalDestinationNotIsolated {
563                     profile: name.clone(),
564                     destination: match ecosystem {
565                         Ecosystem::Cargo => "Cargo endpoint set",
566                         Ecosystem::Npm => "npm endpoint set",
567                         Ecosystem::Pypi => "PyPI endpoint set",
568                         _ => unreachable!("only releasable registry ecosystems are compared"),
569                     },
570                 });
571             }
572         }
573     }
574 
575     Ok(ReleaseConfig {
576         product,
577         profiles,
578         production_profile,
579     })
580 }
