 240 impl std::fmt::Debug for ValidatedReleaseIntent<'_> {
 241     fn fmt(&self, formatter: &mut std::fmt::Formatter<'_>) -> std::fmt::Result {
 242         formatter
 243             .debug_struct("ValidatedReleaseIntent")
 244             .field("intent", &self.intent)
 245             .finish_non_exhaustive()
 246     }
 247 }
 248 
 249 impl ValidatedReleaseIntent<'_> {
 250     pub fn intent(&self) -> &ReleaseIntent {
 251         &self.intent
 252     }
 253 
 254     #[allow(dead_code)] // consumed by the durable executor batch
 255     fn prepared(&self) -> &PreparedReleaseInputs {
 256         &self.prepared
 257     }
 258 
 259     pub(super) fn runner(&self) -> &dyn CommandRunner {
 260         self.runner
 261     }
 262 
 263     pub(super) fn root(&self) -> &Path {
 264         &self.prepared.root
 265     }
 266 
 267     pub(super) fn prepared_operation(&self, id: &ReleaseOperationId) -> Option<PreparedOperationView<'_>> {
 268         self.prepared.operations.get(id).map(|operation| match operation {
 269             PreparedOperation::RegistryArtifactPublish { artifact, registry, .. } => {
 270                 PreparedOperationView::RegistryArtifactPublish {
 271                     artifact,
 272                     registry_key: &registry.key,
 273                     binding_digest: &registry.identity,
 274                     endpoints: match &registry.endpoints {
 275                         PreparedRegistryEndpoints::Cargo { index, api } => {
 276                             PreparedRegistryEndpointsView::Cargo { index, api }
 277                         }
 278                         PreparedRegistryEndpoints::Npm { registry } => PreparedRegistryEndpointsView::Npm { registry },
 279                         PreparedRegistryEndpoints::Pypi {
 280                             upload,
 281                             metadata,
 282                             simple,
 283                         } => PreparedRegistryEndpointsView::Pypi {
 284                             upload,
 285                             metadata,
 286                             simple,
 287                         },
 288                     },
 289                 }
 290             }
 291             PreparedOperation::ProductTag {
 292                 name,
 293                 target,
 294                 annotation,
 295                 remote,
 296             } => PreparedOperationView::ProductTag {
 297                 name,
 298                 target,
 299                 annotation,
 300                 remote_name: remote.remote_name,
 301                 repository: &remote.github_repository,
 302             },
 303             PreparedOperation::ForgePrepare { repository, tag } => {
 304                 PreparedOperationView::ForgePrepare { repository, tag }
 305             }
 306             PreparedOperation::ArtifactUpload { slot } => PreparedOperationView::ArtifactUpload { slot },
 307             PreparedOperation::ForgePublish { repository, tag } => {
 308                 PreparedOperationView::ForgePublish { repository, tag }
 309             }
 310         })
 311     }
 312 
 313     /// Re-observes the held workspace immediately before an effect.
 314     #[allow(dead_code)] // consumed by the durable execution coordinator
 315     pub(crate) fn recheck_trust(&self) -> Result<(), GraphError> {
 316         let evidence =
 317             callisto_vcs::GitAccess::discover(&self.prepared.root, self.runner).observe_git_commit_trust()?;
 318         if evidence != self.prepared.trust || evidence.head() != &self.prepared.source {
 319             return Err(GraphError::ReleaseIntentStale {
 320                 reason: StaleReason::trust_evidence_changed(),
 321             });
 322         }
 323         if prepared_git_remote(&self.prepared.root, self.runner).as_ref() != Ok(&self.prepared.git_remote) {
 324             return Err(GraphError::ReleaseIntentStale {
 325                 reason: StaleReason::git_remote_changed(),
 326             });
 327         }
 328         Ok(())
 329     }
 330 }
