 332 /// Builds a release intent from a fresh root-bound observation.
 333 pub fn build_release_intent<L: ProjectLocator, R: CommandRunner>(
 334     root: &Path,
 335     locator: &L,
 336     runner: &R,
 337     decision: &ReleaseDecisionV1,
 338     profile_name: &str,
 339 ) -> Result<ReleaseIntent, GraphError> {
 340     let root = canonical_root(root)?;
 341     let workspace = Workspace::load(root.clone(), locator, runner)?;
 342     let source = observe_source(&workspace)?;
 343     let intent = derive_product_release(&workspace, decision, source.clone(), profile_name)?.intent;
 344 
 345     // Recheck after all input reads. A concurrent edit or checkout cannot be
 346     // authorized merely because it happened after the first check.
 347     if observe_source(&workspace)? != source {
 348         return Err(GraphError::ReleaseIntentStale {
 349             reason: StaleReason::source_identity_changed(),
 350         });
 351     }
 352     Ok(intent)
 353 }
 354 
 355 /// Re-observes root, config, package discovery, manifests, Git evidence, and
 356 /// the exact operation DAG before creating an opaque authorization capability.
 357 pub fn validate_release_intent<'a, L: ProjectLocator, R: CommandRunner>(
 358     root: &Path,
 359     locator: &L,
 360     runner: &'a R,
 361     received: ReleaseIntent,
 362 ) -> Result<ValidatedReleaseIntent<'a>, GraphError> {
 363     validate_release_intent_with_state_directory(root, locator, runner, None, received)
 364 }
 365 
 366 /// Validates an intent while placing its workspace lock under an explicit
 367 /// caller-owned state directory.
 368 ///
 369 /// CI callers that supply an explicit durable state file must use its parent
 370 /// here as well.  Otherwise validation would still depend on the runner's
 371 /// implicit platform state location, defeating hermetic job handoff.
 372 pub fn validate_release_intent_with_state_directory<'a, L: ProjectLocator, R: CommandRunner>(
 373     root: &Path,
 374     locator: &L,
 375     runner: &'a R,
 376     state_directory: Option<&Path>,
 377     received: ReleaseIntent,
 378 ) -> Result<ValidatedReleaseIntent<'a>, GraphError> {
 379     let root = canonical_root(root)?;
 380     let workspace = Workspace::load(root.clone(), locator, runner)?;
 381     let initial_trust = observe_git_trust(&workspace)?;
 382     let lock = ReleaseWorkspaceLock::acquire(&root, state_directory)?;
 383     let trust = observe_git_trust(&workspace)?;
 384     if trust != initial_trust {
 385         return Err(GraphError::ReleaseIntentStale {
 386             reason: StaleReason::trust_evidence_changed(),
 387         });
 388     }
 389     let source = trust.head().clone();
 390     let prepared = derive_product_release(
 391         &workspace,
 392         received.decision(),
 393         source.clone(),
 394         received.destination().profile_name(),
 395     )?;
 396     let final_trust = observe_git_trust(&workspace)?;
 397     if prepared.intent != received || final_trust != trust {
 398         return Err(GraphError::ReleaseIntentStale {
 399             reason: StaleReason::intent_differs_from_fresh_derivation(),
 400         });
 401     }
 402 
 403     Ok(ValidatedReleaseIntent {
 404         prepared: PreparedReleaseInputs {
 405             root,
 406             source,
 407             trust: final_trust,
 408             git_remote: prepared.git_remote,
 409             _lock: lock,
 410             operations: prepared.operations,
 411         },
 412         intent: received,
 413         runner,
 414     })
 415 }
 416 
 417 fn canonical_root(root: &Path) -> Result<std::path::PathBuf, GraphError> {
 418     dunce::canonicalize(root).map_err(|error| GraphError::ReleaseInputRead {
 419         path: root.to_path_buf(),
 420         message: error.to_string(),
 421     })
 422 }
 423 
 424 fn observe_source<R: CommandRunner, D: DependencyResolver>(
 425     workspace: &Workspace<'_, R, D>,
 426 ) -> Result<CommitSha, GraphError> {
 427     Ok(observe_git_trust(workspace)?.head().clone())
 428 }
