 430 fn observe_git_trust<R: CommandRunner, D: DependencyResolver>(
 820         program: program.to_string(),
 821         args: args.iter().map(ToString::to_string).collect(),
 822         failure: CommandFailure::MalformedOutput { detail },
 823     };
 824     let (headers, body) = stdout
 825         .rsplit_once("\r\n\r\n")
 826         .or_else(|| stdout.rsplit_once("\n\n"))
 827         .ok_or_else(|| malformed("response has no blank line separating headers from body".to_string()))?;
 828     let status_line = headers
 829         .lines()
 830         .rev()
 831         .find(|line| line.trim_end_matches('\r').starts_with("HTTP/"))
 832         .ok_or_else(|| malformed("response headers contain no HTTP status line".to_string()))?;
 833     let status = status_line
 834         .split_whitespace()
 835         .nth(1)
 836         .ok_or_else(|| malformed(format!("HTTP status line has no status code: {status_line:?}")))?
 837         .parse::<u16>()
 838         .map_err(|error| malformed(format!("HTTP status code is not a valid number: {error}")))?;
 839     Ok((status, body))
 840 }
