 946                 package_id.clone(),
 947                 binding.id()?,
 948                 format,
 949                 publication_policy.clone(),
 950                 file_name.clone(),
 951             )?;
 952             let slot = ReleaseArtifactSlot::registry_artifact(&artifact, version.clone(), provenance.clone());
