 357 pub fn validate_release_intent<'a, L: ProjectLocator, R: CommandRunner>(
 358     root: &Path,
 359     locator: &L,
 360     runner: &'a R,
 361     received: ReleaseIntent,
 362 ) -> Result<ValidatedReleaseIntent<'a>, GraphError> {
 363     validate_release_intent_with_state_directory(root, locator, runner, None, received)
 364 }
