 842 fn derive_product_release<R: CommandRunner, D: DependencyResolver>(
 843     workspace: &Workspace<'_, R, D>,
 844     decision: &ReleaseDecisionV1,
 845     source: CommitSha,
 846     profile_name: &str,
 847 ) -> Result<PreparedDerivation, GraphError> {
 848     super::release_decision::validate_release_units(workspace, decision)?;
 849     let mut selected = BTreeMap::new();
 850     for package in workspace.graph.packages() {
 851         if !crate::config::is_release_unit(&workspace.config, &package.id)? {
 852             continue;
 853         }
 854         for id in super::release_decision::release_package_ids(package)?
 855             .into_iter()
 856             .collect::<BTreeSet<_>>()
 857         {
 858             if let Some(entry) = decision.entries.iter().find(|entry| entry.package == id) {
 859                 selected.insert(id.clone(), (package, entry.target_version.clone()));
 860             }
 861         }
 862     }
 863     for entry in &decision.entries {
 864         let id = &entry.package;
 865         if !selected.contains_key(id) {
 866             return Err(GraphError::ReleasePackageNotSelected { package: id.clone() });
 867         }
 868     }
 869 
 870     let (product, profile) = workspace.config.release_profile(profile_name)?;
 871     let release = ProductReleaseId::from_coordinated_versions(
 872         ProductName::parse(&product.name)?,
 873         decision.entries.iter().map(|entry| entry.target_version.clone()),
 874     )?;
 875     let destination_kind = match profile.kind {
 876         crate::config::ReleaseProfileKind::Production => ReleaseDestinationKind::Production,
 877         crate::config::ReleaseProfileKind::Rehearsal => ReleaseDestinationKind::Rehearsal,
 878     };
 879     let cargo = prepared_registry_binding(&workspace.config, profile_name, Ecosystem::Cargo)?;
 880     let npm = prepared_registry_binding(&workspace.config, profile_name, Ecosystem::Npm)?;
 881     let pypi = prepared_registry_binding(&workspace.config, profile_name, Ecosystem::Pypi)?;
 882     let destination = ReleaseDestinationBinding::new(
 883         profile_name,
 884         destination_kind,
 885         profile.forge_repository.clone(),
 886         cargo.id()?,
 887         npm.id()?,
 888         pypi.id()?,
 889     )?;
 890     let git_remote = prepared_git_remote(&workspace.root, workspace.runner)?;
 891     if git_remote.github_repository != *destination.forge_repository() {
 892         return Err(GraphError::UnsafeGitRemote {
 893             reason: "origin repository does not match the selected release profile",
 894         });
 895     }
 896     let provenance = callisto_model::ProvenancePolicy::new(
 897         product.provenance_repository.clone(),
 898         product.build_workflow.clone(),
 899         source.clone(),
 900     )?;
 901 
 902     let registry_bindings = BTreeMap::from([
 903         (Ecosystem::Cargo, cargo),
 904         (Ecosystem::Npm, npm),
 905         (Ecosystem::Pypi, pypi),
 906     ]);
 907     let mut approved = Vec::new();
 908     let mut slots = Vec::new();
 909     let mut prepared = BTreeMap::new();
 910     let mut operations = BTreeMap::new();
 911     for (package_id, (package, version)) in &selected {
 912         let matching_targets = package
 913             .publish_to
 914             .iter()
 915             .filter(|target| target.ecosystem() == Some(package_id.ecosystem()))
 916             .collect::<Vec<_>>();
 917         let Some(target) = matching_targets.first().copied() else {
 918             continue;
 919         };
 920         if matching_targets.len() != 1 {
 921             return Err(GraphError::ReleaseSelectionInvalid {
 922                 package: package_id.clone(),
 923                 reason: ReleaseSelectionInvalidReason::DuplicateRegistryTarget,
 924             });
 925         }
 926         let binding = registry_bindings
 927             .get(&package_id.ecosystem())
 928             .ok_or(GraphError::UnsupportedRelease {
 929                 feature: UnsupportedReleaseFeature::Ecosystem,
 930             })?;
 931         for (format, file_name) in registry_artifact_files(package_id, version)? {
 932             let publication_policy = match target {
 933                 callisto_model::PublishTarget::CratesIo => RegistryPublicationPolicy::cargo(),
 934                 callisto_model::PublishTarget::Npm { access, .. } => RegistryPublicationPolicy::npm(
 935                     access.unwrap_or(NpmAccess::Public),
 936                     if version.is_prerelease() { "next" } else { "latest" },
 937                 )?,
 938                 callisto_model::PublishTarget::Pypi { .. } => RegistryPublicationPolicy::pypi(),
 939                 _ => {
 940                     return Err(GraphError::UnsupportedRelease {
 941                         feature: UnsupportedReleaseFeature::PublishTarget,
 942                     })
 943                 }
 944             };
 945             let artifact = ApprovedRegistryArtifact::new(
 946                 package_id.clone(),
 947                 binding.id()?,
 948                 format,
 949                 publication_policy.clone(),
 950                 file_name.clone(),
 951             )?;
 952             let slot = ReleaseArtifactSlot::registry_artifact(&artifact, version.clone(), provenance.clone());
 953             let id = ReleaseOperationId::RegistryArtifactPublish {
 954                 package: package_id.clone(),
 955                 version: version.clone(),
 956                 registry: binding.id()?,
 957                 slot: slot.clone(),
 958             };
 959             let operation = ReleaseOperation::new(id.clone(), vec![])?;
 960             if prepared
 961                 .insert(
 962                     id.clone(),
 963                     PreparedOperation::RegistryArtifactPublish {
 964                         package_dir: package_dir(package)?,
 965                         artifact: artifact.clone(),
 966                         registry: binding.clone(),
 967                     },
 968                 )
 969                 .is_some()
 970             {
 971                 return Err(GraphError::ReleaseSelectionInvalid {
 972                     package: package_id.clone(),
 973                     reason: ReleaseSelectionInvalidReason::DuplicateRegistryTarget,
 974                 });
 975             }
 976             operations.insert(id, operation);
 977             approved.push(artifact);
 978             slots.push(slot);
 979         }
 980     }
 981 
 982     let mut registry_ids = operations.keys().cloned().collect::<Vec<_>>();
 983     registry_ids.sort();
 984     for target in ProductTarget::ALL {
 985         slots.push(ReleaseArtifactSlot::product_asset(
 986             release.clone(),
 987             target,
 988             provenance.clone(),
 989         ));
 990     }
 991     slots.push(ReleaseArtifactSlot::checksum_manifest(
 992         release.clone(),
 993         provenance.clone(),
 994     ));
 995     slots.push(ReleaseArtifactSlot::release_metadata(release.clone(), provenance));
 996 
 997     let tag_text = release.tag();
 998     // `ProductReleaseId::tag` combines a validated lowercase product name,
 999     // one literal `@`, and validated SemVer, so it is already a safe Git ref.
1000     let tag_name = TagName::new_unchecked(tag_text.clone());
1001     let tag_id = ReleaseOperationId::ProductTag {
1002         release: release.clone(),
1003         tag: tag_text,
1004     };
1005     operations.insert(tag_id.clone(), ReleaseOperation::new(tag_id.clone(), registry_ids)?);
1006     prepared.insert(
1007         tag_id.clone(),
1008         PreparedOperation::ProductTag {
1009             name: tag_name.clone(),
1010             target: source.clone(),
1011             annotation: format!("Release {tag_name}"),
1012             remote: git_remote.clone(),
1013         },
1014     );
1015     let prepare_id = ReleaseOperationId::ForgePrepare {
1016         release: release.clone(),
1017         repository: destination.forge_repository().clone(),
1018     };
1019     operations.insert(
1020         prepare_id.clone(),
1021         ReleaseOperation::new(prepare_id.clone(), vec![tag_id])?,
1022     );
1023     prepared.insert(
1024         prepare_id.clone(),
1025         PreparedOperation::ForgePrepare {
1026             repository: destination.forge_repository().clone(),
1027             tag: tag_name.clone(),
1028         },
1029     );
1030     let mut upload_ids = Vec::new();
1031     for slot in slots.iter().filter(|slot| slot.release().is_some()) {
1032         let id = ReleaseOperationId::ArtifactUpload {
1033             release: release.clone(),
1034             slot: slot.clone(),
1035         };
1036         operations.insert(id.clone(), ReleaseOperation::new(id.clone(), vec![prepare_id.clone()])?);
1037         prepared.insert(id.clone(), PreparedOperation::ArtifactUpload { slot: slot.clone() });
1038         upload_ids.push(id);
1039     }
1040     upload_ids.sort();
1041     let publish_id = ReleaseOperationId::ForgePublish {
1042         release: release.clone(),
1043         repository: destination.forge_repository().clone(),
1044     };
1045     operations.insert(
1046         publish_id.clone(),
1047         ReleaseOperation::new(publish_id.clone(), upload_ids)?,
1048     );
1049     prepared.insert(
1050         publish_id,
1051         PreparedOperation::ForgePublish {
1052             repository: destination.forge_repository().clone(),
1053             tag: tag_name,
1054         },
1055     );
1056 
1057     let operations = canonical_operation_order(operations)?;
1058     let intent = ReleaseIntent::new(
1059         decision.clone(),
1060         release,
1061         source,
1062         destination,
1063         approved,
1064         operations,
1065         slots,
1066     )?;
1067     let intent_ids = intent
1068         .operations()
1069         .iter()
1070         .map(|operation| operation.id().clone())
1071         .collect::<BTreeSet<_>>();
1072     if intent_ids != prepared.keys().cloned().collect() {
1073         return Err(GraphError::ReleaseInvariant {
1074             detail: "prepared operation map does not exactly match the derived intent".to_string(),
1075         });
1076     }
1077     Ok(PreparedDerivation {
1078         intent,
1079         operations: prepared,
1080         git_remote,
1081     })
1082 }
