1515     /// The locator is the release authority boundary: malformed membership
1516     /// must stop intent construction before source observation can invoke Git
1517     /// (and therefore before a later execution path could reach credentials
1518     /// or a provider). The child package makes this a real discoverable-member
1519     /// case rather than a root-only parse failure.
1520     #[test]
1521     fn malformed_root_membership_stops_intent_before_any_command_or_decision() {
1522         struct CountingRunner(AtomicUsize);
1523 
1524         impl CommandRunner for CountingRunner {
1525             fn run(&self, program: &str, _args: &[&str], _cwd: &Path) -> Result<CommandOutput, CommandError> {
1526                 self.0.fetch_add(1, Ordering::SeqCst);
1527                 Err(CommandError::Io {
1528                     program: program.to_owned(),
1529                     message: "membership failure must happen before any command".to_owned(),
1530                 })
1531             }
1532         }
1533 
1534         let dir = tempfile::tempdir().unwrap();
1535         let root = dir.path();
1536         std::fs::write(root.join("Cargo.toml"), "[workspace]\nmembers = [\"").unwrap();
1537         std::fs::create_dir_all(root.join("crates/discoverable")).unwrap();
1538         std::fs::write(
1539             root.join("crates/discoverable/Cargo.toml"),
1540             "[package]\nname = \"discoverable\"\nversion = \"1.0.0\"\n",
1541         )
1542         .unwrap();
1543 
1544         let runner = CountingRunner(AtomicUsize::new(0));
1545         let locator = crate::IgnoreWalkLocator::new(root);
1546         let decision = ReleaseDecisionV1::new(vec![callisto_model::ReleaseDecisionEntry {
1547             package: ReleasePackageId::new(Ecosystem::Cargo, "discoverable").unwrap(),
1548             target_version: Version::parse("1.0.0", VersionGrammar::SemVer).unwrap(),
1549             reasons: vec![callisto_model::ReleaseInclusionReason::ExplicitSelection],
1550         }])
1551         .unwrap();
1552         let result = build_release_intent(root, &locator, &runner, &decision, "production");
1553 
1554         assert!(matches!(
