1668         // publish-to = [] keeps this test scoped to identity derivation --
1669         // no tag/registry operations, no git remote requirement.
1670         std::fs::write(
1671             dir.path().join("callisto.toml"),
1672             release_config("[[package]]\nmatch = \"release-fixture\"\npublish-to = []\n"),
1673         )
1674         .unwrap();
1675         for args in [
1676             ["init", "-q"].as_slice(),
