1680             [
1681                 "remote",
1682                 "add",
1683                 "origin",
1684                 "https://github.com/example/release-fixture.git",
1685             ]
1686             .as_slice(),
1687             ["add", "."].as_slice(),
1688             ["commit", "-q", "-m", "fixture"].as_slice(),
1689             ["checkout", "--detach", "-q", "HEAD"].as_slice(),
1690         ] {
1691             assert!(std::process::Command::new("git")
1692                 .args(args)
1693                 .current_dir(dir.path())
1694                 .status()
1695                 .unwrap()
1696                 .success());
1697         }
1698         let runner = RealGitRunner;
1699         let locator = crate::IgnoreWalkLocator::new(dir.path());
1700 
1701         let workspace = Workspace::load(dir.path().to_path_buf(), &locator, &runner).unwrap();
1702         let package_id = workspace
