1727         let decision = crate::commands::release_decision::derive_release_decision(&workspace, &plan).unwrap();
1728         let decided_ids: BTreeSet<_> = decision.entries.iter().map(|entry| entry.package.clone()).collect();
1729         assert_eq!(
