1738         let intent = build_release_intent(dir.path(), &locator, &runner, &decision, "production").unwrap();
1739         let intent_ids: BTreeSet<_> = intent
1740             .decision()
1741             .entries
1742             .iter()
1743             .map(|input| input.package.clone())
1744             .collect();
1745         assert_eq!(
1746             intent_ids, decided_ids,
1747             "derive_product_release must agree with derive_release_decision on release package identity"
1748         );
