1497     impl CommandRunner for RealGitRunner {
1498         fn run(&self, program: &str, args: &[&str], cwd: &Path) -> Result<CommandOutput, CommandError> {
1499             let output = std::process::Command::new(program)
1500                 .args(args)
1501                 .current_dir(cwd)
1502                 .output()
1503                 .map_err(|error| CommandError::Io {
1504                     program: program.to_string(),
1505                     message: error.to_string(),
1506                 })?;
1507             Ok(CommandOutput {
1508                 exit_code: output.status.code(),
1509                 stdout: String::from_utf8_lossy(&output.stdout).into_owned(),
1510                 stderr: String::from_utf8_lossy(&output.stderr).into_owned(),
1511             })
1512         }
1513     }
