 180 /// entries don't match its content digest, so a hand-edited or corrupted
 181 /// decision file fails before this function's own diff cross-check runs.
 182 ///
 183 /// The caller must check out the exact merge commit in detached HEAD state
 184 /// before creating an intent. GitHub-specific PR/approval provenance belongs
 185 /// in the workflow boundary; this graph function verifies the local,
 186 /// provider-neutral commit delta only.
 187 pub fn derive_release_commit_decision<R: CommandRunner, D: DependencyResolver>(
 188     workspace: &Workspace<'_, R, D>,
 189     release_commit: &CommitSha,
 190     decision_path: &std::path::Path,
 191 ) -> Result<ReleaseDecisionV1, GraphError> {
 192     let head_args = ["rev-parse", "HEAD"];
 193     let head = git_stdout(workspace.runner, &workspace.root, &head_args)?;
 194     let head =
 195         CommitSha::parse(&head).map_err(|source| command_malformed_output("git", &head_args, source.to_string()))?;
 196     if &head != release_commit {
 197         return Err(GraphError::ReleaseCommitVerificationFailed {
 198             commit: release_commit.clone(),
 199             reason: CommitVerificationFailure::HeadMismatch,
 200         });
 201     }
 202 
 203     let parent_ref = format!("{}^", release_commit.as_str());
 204     let parent_args = ["rev-parse", parent_ref.as_str()];
 205     let parent = git_stdout(workspace.runner, &workspace.root, &parent_args)?;
 206     CommitSha::parse(&parent).map_err(|source| command_malformed_output("git", &parent_args, source.to_string()))?;
 207 
 208     let diff_tree_args = [
 209         "diff-tree",
 210         "--no-commit-id",
 211         "--name-status",
 212         "-r",
 213         "--no-renames",
 214         parent.as_str(),
 215         release_commit.as_str(),
 216     ];
 217     let changed = git_stdout(workspace.runner, &workspace.root, &diff_tree_args)?;
 218     let changed = parse_name_status(&changed, &diff_tree_args)?;
 219 
 220     // The decision must be freshly authored as part of *this* commit, not a
 221     // stale leftover an earlier release already committed and this one never
 222     // touched -- otherwise a commit that changes nothing real could still
 223     // carry forward a prior, unrelated decision's authority.
 224     let decision_path_str = decision_path.to_string_lossy().replace('\\', "/");
 225     let decision_freshly_written = changed
 226         .iter()
 227         .any(|(status, path)| path == &decision_path_str && matches!(status.as_str(), "A" | "M"));
 228     if !decision_freshly_written {
 229         return Err(GraphError::ReleaseCommitVerificationFailed {
 230             commit: release_commit.clone(),
 231             reason: CommitVerificationFailure::DecisionNotWrittenByCommit,
 232         });
 233     }
 234 
 235     // A cheap, independent sanity check that this commit is a real version
 236     // application and not just a hand-crafted decision file: some real
 237     // changeset was actually consumed. The decision's own entries, not this
 238     // changeset's content, remain the sole authority verified below.
 239     let changeset_dir = workspace.config.changesets_dir.to_string_lossy().replace('\\', "/");
 240     let changeset_prefix = format!("{}/", changeset_dir.trim_end_matches('/'));
 241     let consumed_a_changeset = changed
 242         .iter()
 243         .any(|(status, path)| status == "D" && path.starts_with(&changeset_prefix) && path.ends_with(".md"));
 244     if !consumed_a_changeset {
 245         return Err(GraphError::ReleaseCommitVerificationFailed {
 246             commit: release_commit.clone(),
 247             reason: CommitVerificationFailure::NoChangesetConsumed,
 248         });
 249     }
 250 
 251     let decision_source = git_file(
 252         workspace.runner,
 253         &workspace.root,
 254         release_commit.as_str(),
 255         &decision_path_str,
 256     )?;
 257     let decision: ReleaseDecisionV1 =
 258         serde_json::from_str(&decision_source).map_err(|error| GraphError::ReleaseDecisionDecode {
 259             path: decision_path.to_path_buf(),
 260             message: error.to_string(),
 261         })?;
 262     validate_release_units(workspace, &decision)?;
 263     let claimed = decision
 264         .entries
 265         .iter()
 266         .map(|entry| (entry.package.clone(), entry.target_version.clone()))
 267         .collect::<std::collections::BTreeMap<_, _>>();
 268 
 269     let changed_paths = changed
 270         .iter()
 271         .filter_map(|(status, path)| matches!(status.as_str(), "A" | "M").then_some(path.as_str()))
 272         .collect::<std::collections::BTreeSet<_>>();
 273 
