 210         "--no-commit-id",
 211         "--name-status",
 212         "-r",
 213         "--no-renames",
 214         parent.as_str(),
 215         release_commit.as_str(),
 216     ];
 217     let changed = git_stdout(workspace.runner, &workspace.root, &diff_tree_args)?;
 218     let changed = parse_name_status(&changed, &diff_tree_args)?;
