 221     // stale leftover an earlier release already committed and this one never
 222     // touched -- otherwise a commit that changes nothing real could still
 223     // carry forward a prior, unrelated decision's authority.
 224     let decision_path_str = decision_path.to_string_lossy().replace('\\', "/");
 225     let decision_freshly_written = changed
 226         .iter()
 227         .any(|(status, path)| path == &decision_path_str && matches!(status.as_str(), "A" | "M"));
 228     if !decision_freshly_written {
 229         return Err(GraphError::ReleaseCommitVerificationFailed {
