355         raw.index_url.is_some(),
356         raw.api_url.is_some(),
357         raw.registry_url.is_some(),
358         raw.upload_url.is_some(),
359         raw.metadata_url.is_some(),
360         raw.simple_url.is_some(),
361     ];
362     if !present.into_iter().any(|value| value) {
363         return Ok(None);
364     }
365 
366     let invalid_shape = || ConfigError::InvalidRegistryEndpointShape {
367         registry: registry.to_string(),
368         ecosystem: kind,
369     };
370     match kind {
371         Ecosystem::Cargo
372             if raw.index_url.is_some()
373                 && raw.api_url.is_some()
374                 && raw.registry_url.is_none()
375                 && raw.upload_url.is_none()
376                 && raw.metadata_url.is_none()
377                 && raw.simple_url.is_none() =>
378         {
379             Ok(Some(RegistryEndpoints::Cargo {
380                 index: normalize_registry_url(registry, "index-url", raw.index_url.as_deref().expect("checked"))?,
381                 api: normalize_registry_url(registry, "api-url", raw.api_url.as_deref().expect("checked"))?,
382             }))
383         }
384         Ecosystem::Npm
385             if raw.index_url.is_none()
386                 && raw.api_url.is_none()
387                 && raw.registry_url.is_some()
388                 && raw.upload_url.is_none()
389                 && raw.metadata_url.is_none()
390                 && raw.simple_url.is_none() =>
391         {
392             Ok(Some(RegistryEndpoints::Npm {
393                 registry: normalize_registry_url(
394                     registry,
395                     "registry-url",
396                     raw.registry_url.as_deref().expect("checked"),
397                 )?,
398             }))
399         }
400         Ecosystem::Pypi
401             if raw.index_url.is_none()
402                 && raw.api_url.is_none()
403                 && raw.registry_url.is_none()
404                 && raw.upload_url.is_some()
405                 && raw.metadata_url.is_some()
406                 && raw.simple_url.is_some() =>
407         {
408             Ok(Some(RegistryEndpoints::Pypi {
409                 upload: normalize_registry_url(registry, "upload-url", raw.upload_url.as_deref().expect("checked"))?,
410                 metadata: normalize_registry_url(
411                     registry,
412                     "metadata-url",
413                     raw.metadata_url.as_deref().expect("checked"),
414                 )?,
415                 simple: normalize_registry_url(registry, "simple-url", raw.simple_url.as_deref().expect("checked"))?,
416             }))
417         }
418         _ => Err(invalid_shape()),
419     }
420 }
