  63 impl<W> ReleaseStateStore<W>
  64 where
  65     W: ReleaseStateWriter,
  66 {
  67     /// Creates a store with a narrow writer seam, primarily for deterministic
  68     /// failure tests. The path remains explicit and is never config-derived.
  69     pub fn with_writer(path: impl Into<PathBuf>, writer: W) -> Self {
  70         Self {
  71             path: path.into(),
  72             writer,
  73         }
  74     }
  75 
  76     /// Returns the caller-chosen durable state location.
  77     pub fn path(&self) -> &Path {
  78         &self.path
  79     }
  80 
  81     /// Loads state if it exists and rejects any state not exactly bound to
  82     /// `intent`. A missing file is not evidence of a completed release.
  83     pub fn load(&self, intent: &ReleaseIntent) -> Result<Option<ReleaseExecutionState>, GraphError> {
  84         let content = match std::fs::read_to_string(&self.path) {
  85             Ok(content) => content,
  86             Err(error) if error.kind() == std::io::ErrorKind::NotFound => return Ok(None),
  87             Err(error) => {
  88                 return Err(GraphError::ReleaseStateRead {
  89                     path: self.path.clone(),
  90                     message: error.to_string(),
  91                 });
  92             }
  93         };
  94         let state: ReleaseExecutionState =
  95             serde_json::from_str(&content).map_err(|error| GraphError::ReleaseStateDecode {
  96                 path: self.path.clone(),
  97                 message: error.to_string(),
  98             })?;
  99         state
 100             .validate_for_intent(intent)
 101             .map_err(|source| GraphError::ReleaseExecutionState { source })?;
 102         Ok(Some(state))
 103     }
 104 
 105     /// Loads existing state or atomically writes the exact pending roster.
 106     pub fn load_or_initialize(
 107         &self,
 108         intent: &ReleaseIntent,
 109         permit: &ApplyPermit,
 110     ) -> Result<ReleaseExecutionState, GraphError> {
 111         if let Some(state) = self.load(intent)? {
 112             return Ok(state);
 113         }
 114         let state = ReleaseExecutionState::pending(intent);
 115         self.save(intent, &state, permit)?;
 116         Ok(state)
 117     }
 118 
 119     /// Atomically persists only state proven to belong to `intent`.
 120     pub fn save(
 121         &self,
 122         intent: &ReleaseIntent,
 123         state: &ReleaseExecutionState,
 124         permit: &ApplyPermit,
 125     ) -> Result<(), GraphError> {
 126         state
 127             .validate_for_intent(intent)
 128             .map_err(|source| GraphError::ReleaseExecutionState { source })?;
 129         let content = serde_json::to_string_pretty(state).expect("release state serialization is infallible") + "\n";
 130         self.writer
 131             .write(&self.path, &content, permit)
 132             .map_err(|error| GraphError::ReleaseStateWrite {
 133                 path: self.path.clone(),
 134                 message: error.to_string(),
 135             })
 136     }
 137 }
