1306         reason: "remote path is invalid",
1307     })?;
1308     let owner = components
1309         .next()
1310         .filter(|value| !value.is_empty())

282 /// Parses and canonicalizes a credential-free HTTP(S) registry endpoint.
283 ///
284 /// One resolver owns this normalization so observation and dispatch never
285 /// disagree about a destination because of host casing, a default port, or a
286 /// trailing slash. Credentials, query parameters, and fragments are rejected
287 /// rather than normalized away because they must never become durable config.
288 fn normalize_registry_url(registry: &str, field: &'static str, raw: &str) -> Result<String, ConfigError> {
289     let mut url = Url::parse(raw).map_err(|error| ConfigError::InvalidRegistryEndpoint {
290         registry: registry.to_string(),
291         field,
292         reason: error.to_string(),
293     })?;
294     if !matches!(url.scheme(), "http" | "https") {
295         return Err(ConfigError::InvalidRegistryEndpoint {
296             registry: registry.to_string(),
297             field,
298             reason: "scheme must be http or https".to_string(),
299         });
300     }
301     if url.host_str().is_none() || url.cannot_be_a_base() {
302         return Err(ConfigError::InvalidRegistryEndpoint {
303             registry: registry.to_string(),
304             field,
305             reason: "URL must have an authority and hierarchical path".to_string(),
306         });
307     }
308     let authority_contains_userinfo = raw
309         .split_once("://")
310         .map(|(_, remainder)| remainder.split('/').next().unwrap_or_default().contains('@'))
311         .unwrap_or(false);
312     if authority_contains_userinfo || !url.username().is_empty() || url.password().is_some() {
313         return Err(ConfigError::InvalidRegistryEndpoint {
314             registry: registry.to_string(),
315             field,
316             reason: "userinfo is forbidden".to_string(),
317         });
318     }
319     if url.query().is_some() || url.fragment().is_some() {
320         return Err(ConfigError::InvalidRegistryEndpoint {
321             registry: registry.to_string(),
322             field,
323             reason: "query parameters and fragments are forbidden".to_string(),
324         });
325     }
326 
327     if matches!((url.scheme(), url.port()), ("http", Some(80)) | ("https", Some(443))) {
328         url.set_port(None).map_err(|()| ConfigError::InvalidRegistryEndpoint {
329             registry: registry.to_string(),
330             field,
331             reason: "default port could not be normalized".to_string(),
332         })?;
333     }
334     let mut normalized = url.to_string();
335     if url.path() != "/" {
336         while normalized.ends_with('/') {
337             normalized.pop();
338         }
339     }
340     Ok(normalized)
341 }
