/// One independently actionable piece of provider work proven to be missing.
#[derive(Clone, Debug, PartialEq, Eq, PartialOrd, Ord)]
pub(super) enum MissingWork {
    RegistryArtifact(ReleaseArtifactSlot),
    ForgeAsset(ReleaseArtifactSlot),
    PublishForgeRelease(ProductReleaseId),
}

/// Exact provider facts already present plus the closed work still missing.
#[derive(Clone, Debug, PartialEq, Eq)]
pub(super) struct VerifiedPartialEvidence {
    exact: Vec<ReleaseObservationEvidence>,
    missing: BTreeSet<MissingWork>,
}

impl VerifiedPartialEvidence {
    fn new(exact: Vec<ReleaseObservationEvidence>, missing: BTreeSet<MissingWork>) -> Self {
        debug_assert!(!missing.is_empty());
        Self { exact, missing }
    }

    pub(super) fn exact(&self) -> &[ReleaseObservationEvidence] {
        &self.exact
    }

    pub(super) fn missing(&self) -> &BTreeSet<MissingWork> {
        &self.missing
    }
}

/// Closed reasons why a named external object cannot satisfy the intent.
#[derive(Clone, Debug, PartialEq, Eq)]
pub(super) enum ExternalConflict {
    RemoteTag(RemoteAnnotatedTagConflict),
    RemoteTagMissingForForge,
    RegistryDigest {
        slot: ReleaseArtifactSlot,
        observed: ArtifactDigest,
    },
    RegistryLength {
        slot: ReleaseArtifactSlot,
        observed: u64,
    },
    UnexpectedRegistryDistribution {
        package: ReleasePackageId,
        version: Version,
        file_name: String,
    },
    ForgeReleaseTag,
    ForgeAssetDigest {
        slot: ReleaseArtifactSlot,
        observed: ArtifactDigest,
    },
    ForgeAssetLength {
        slot: ReleaseArtifactSlot,
        observed: u64,
    },
    UnexpectedForgeAsset {
        file_name: String,
    },
    PublishedReleaseIncomplete {
        release: ProductReleaseId,
    },
}

#[derive(Clone, Copy, Debug, PartialEq, Eq)]
pub(super) enum ObservationProvider {
    Git,
    GitHub,
    Cargo,
    Npm,
    Pypi,
    ArtifactCapability,
    PreparedCapability,
}

/// Closed provider-failure taxonomy. Raw provider output is intentionally not
/// retained: stderr can contain credentials and is not durable evidence.
#[derive(Clone, Debug, PartialEq, Eq)]
pub(super) enum ObservationFailure {
    Command {
        provider: ObservationProvider,
    },
    HttpStatus {
        provider: ObservationProvider,
        status: u16,
    },
    MalformedResponse {
        provider: ObservationProvider,
    },
    MissingDigest {
        provider: ObservationProvider,
        file_name: String,
    },
    Capability {
        provider: ObservationProvider,
    },
}

/// The only observation vocabulary consumed by convergence.
#[derive(Clone, Debug, PartialEq, Eq)]
pub(super) enum OperationObservation {
    Absent,
    Incomplete(VerifiedPartialEvidence),
    Exact(ReleaseObservationEvidence),
    Conflict(ExternalConflict),
    Unverifiable(ObservationFailure),
}

#[derive(Clone, Debug, PartialEq, Eq)]
struct GitHubAsset {
    digest: Option<ArtifactDigest>,
