        .pypi_versions
        .entry(key)
        .or_insert_with(|| fetch_pypi_version(validated, metadata_endpoint, &normalized, version))
        .clone();
    let Some(distributions) = (match observed {
        Ok(value) => value,
        Err(failure) => return OperationObservation::Unverifiable(failure),
    }) else {
        return OperationObservation::Absent;
    };

    let expected_slots = validated
        .intent()
        .operations()
        .iter()
        .filter_map(|operation| match operation.id() {
            ReleaseOperationId::RegistryArtifactPublish {
                package: candidate_package,
                version: candidate_version,
                registry: candidate_registry,
                slot,
            } if candidate_package == package && candidate_version == version && candidate_registry == &registry => {
                Some(slot.clone())
            }
            _ => None,
        })
        .collect::<Vec<_>>();
    let expected_names = expected_slots
        .iter()
        .map(|slot| slot.file_name().to_string())
        .collect::<BTreeSet<_>>();
    if let Some(file_name) = distributions.keys().find(|name| !expected_names.contains(*name)) {
        return OperationObservation::Conflict(ExternalConflict::UnexpectedRegistryDistribution {
            package: package.clone(),
            version: version.clone(),
            file_name: file_name.clone(),
        });
    }

