        self.validated_intent
    }

    #[allow(dead_code)] // consumed by provider observation and receipt assembly in T3/T4
    pub(super) fn expectations(&self) -> callisto_model::ObservationExpectations {
        callisto_model::ObservationExpectations::from_manifest(self.validated_intent.intent(), &self.manifest)
            .expect("validated artifact capability retains its verified intent/manifest binding")
    }

    #[allow(dead_code)] // consumed by exact-byte provider dispatch in T3-DISPATCH
    pub(super) fn snapshot(&self, slot: &ReleaseArtifactSlot) -> Result<ArtifactSnapshot, GraphError> {
