    )?;
    let final_trust = observe_git_trust(&workspace)?;
    if prepared.intent != received || final_trust != trust {
        return Err(GraphError::ReleaseIntentStale {
            reason: StaleReason::intent_differs_from_fresh_derivation(),
        });
    }

    Ok(ValidatedReleaseIntent {
        prepared: PreparedReleaseInputs {
            root,
            source,
            trust: final_trust,
            git_remote: prepared.git_remote,
            _lock: lock,
            operations: prepared.operations,
        },
        intent: received,
        runner,
    })
}

fn canonical_root(root: &Path) -> Result<std::path::PathBuf, GraphError> {
    dunce::canonicalize(root).map_err(|error| GraphError::ReleaseInputRead {
        path: root.to_path_buf(),
        message: error.to_string(),
    })
}

fn observe_source<R: CommandRunner, D: DependencyResolver>(
    workspace: &Workspace<'_, R, D>,
) -> Result<CommitSha, GraphError> {
    Ok(observe_git_trust(workspace)?.head().clone())
}

fn observe_git_trust<R: CommandRunner, D: DependencyResolver>(
    workspace: &Workspace<'_, R, D>,
) -> Result<GitCommitTrustEvidence, GraphError> {
    let evidence = workspace.git_access().observe_git_commit_trust()?;
    if evidence.canonical_root() != workspace.root {
        return Err(GraphError::ReleasePreconditionUnmet {
            requirement: ReleasePreconditionRequirement::CanonicalRootMatchesWorkspace,
        });
    }
    if evidence.head_disposition() != GitHeadDisposition::Detached {
        return Err(GraphError::ReleasePreconditionUnmet {
            requirement: ReleasePreconditionRequirement::DetachedHead,
        });
    }
    Ok(evidence)
}

impl ValidatedReleaseIntent<'_> {
    /// Dispatches exactly one graph-private operation prepared during fresh
    /// validation. This is intentionally the only production effect path: it
    /// never accepts a path, endpoint, tag, package name, or version from a
    /// caller.
    pub(crate) fn dispatch_prepared(
        &self,
        permit: &ApplyPermit,
        id: &ReleaseOperationId,
    ) -> Result<OperationOutcome, GraphError> {
        let operation = self
            .prepared
            .operations
            .get(id)
            .ok_or_else(|| GraphError::ReleaseInvariant {
                detail: format!("dispatch_prepared: no prepared operation for `{id:?}`"),
            })?;
        match operation {
            PreparedOperation::ProductTag {
                name,
                target,
                annotation,
                ..
            } => self.dispatch_tag(permit, name, target, annotation),
            PreparedOperation::RegistryArtifactPublish { .. }
            | PreparedOperation::ForgePrepare { .. }
            | PreparedOperation::ArtifactUpload { .. }
            | PreparedOperation::ForgePublish { .. } => Err(GraphError::ReleaseInvariant {
                detail: format!(
                    "dispatch for promoted product operation `{id:?}` is owned by the coordinated PM-005/T3 cutover"
                ),
            }),
        }
    }
}

/// Ecosystems whose publish gets confirmed against the registry before the
/// operation is marked done. Npm and Cargo are checked; PyPI has the
/// identical propagation-lag gap, deliberately deferred -- no PyPI package
/// or credentials in this workspace to test a fix against. The single
/// source of truth `dispatch_registry` actually consults, so a test on this
/// function directly proves the runtime gate, not a copy of it.
fn ecosystem_requires_registry_confirmation(ecosystem: Ecosystem) -> bool {
    matches!(ecosystem, Ecosystem::Npm | Ecosystem::Cargo)
}

/// A successful publish-client exit isn't a receipt: confirms the registry
/// itself has caught up before treating the operation as done. If not, it
/// stays `Attempting` for reconciliation, reported via its own variant
/// rather than `ReleaseIntentStale`'s false "no operation was authorized".
fn require_registry_confirmation(is_published: bool, package: &str, version: &Version) -> Result<(), GraphError> {
    if is_published {
        return Ok(());
    }
    Err(GraphError::RegistryPublishUnconfirmed {
        package: package.to_string(),
        version: version.clone(),
    })
}

/// Retries after this many unconfirmed checks: 3 retries (4 checks total).
const REGISTRY_CONFIRMATION_MAX_RETRIES: u32 = 3;

/// Exponential backoff between confirmation checks: 2s, 4s, 8s (14s worst
/// case) -- registry index propagation is normally sub-second, so this only
/// costs time on the rare lagging case, not the common one.
fn registry_confirmation_backoff(retry: u32) -> std::time::Duration {
    std::time::Duration::from_secs(2u64.pow(retry + 1))
}

/// Retries `check` up to `max_retries` more times, sleeping `backoff(retry)`
/// between attempts, and returns as soon as it reports published. Returns
/// `Ok(false)` if it never does. `sleep` is injected so tests can verify the
/// retry count and schedule without a real wall-clock wait.
fn poll_until_published(
    mut check: impl FnMut() -> Result<bool, GraphError>,
    max_retries: u32,
    backoff: impl Fn(u32) -> std::time::Duration,
    sleep: impl Fn(std::time::Duration),
) -> Result<bool, GraphError> {
    for retry in 0..=max_retries {
        if check()? {
            return Ok(true);
        }
        if retry < max_retries {
            sleep(backoff(retry));
        }
    }
    Ok(false)
}

impl ValidatedReleaseIntent<'_> {
    /// Runs a [`registry_argv::Argv`] built by the pure argv layer. This is
    /// the only place `dispatch_registry` touches [`CommandRunner`] --
    /// everything about *what* to run (program, args, cwd) was already
    /// decided by `registry_argv`.
    fn run_argv(&self, argv: &registry_argv::Argv) -> Result<CommandOutput, GraphError> {
        let args: Vec<&str> = argv.args.iter().map(String::as_str).collect();
        Ok(self.runner.run(&argv.program, &args, &argv.cwd)?)
    }

    fn npm_version_is_published(
        &self,
        package_name: &str,
        version: &Version,
        registry: Option<&str>,
    ) -> Result<bool, GraphError> {
        let spec = format!("{package_name}@{}", version.render());
        let mut args = vec!["view", spec.as_str(), "--json"];
        if let Some(registry) = registry {
            args.extend(["--registry", registry]);
        }
        let output = self
            .runner
            .run_quiet("npm", &args, &self.prepared.root, std::time::Duration::from_secs(300))?;
        if output.success() {
            return Ok(!output.stdout_trimmed().is_empty());
        }
        let details = format!("{}\n{}", output.stdout, output.stderr).to_ascii_lowercase();
        if details.contains("e404")
            || details.contains("etarget")
            || details.contains("no matching version")
            || details.contains("is not in this registry")
        {
            return Ok(false);
        }
        Err(GraphError::ReleaseCommand {
            program: "npm".to_string(),
            args: args.iter().map(ToString::to_string).collect(),
            failure: CommandFailure::NonZeroExit {
                exit_code: output.exit_code,
                stderr: output.stderr,
            },
        })
    }

    fn cargo_version_is_published(
        &self,
        package_name: &str,
        version: &Version,
        registry_key: Option<&str>,
    ) -> Result<bool, GraphError> {
        let spec = format!("{package_name}@{}", version.render());
        let mut args = vec!["info", spec.as_str()];
        if let Some(registry) = registry_key {
            args.extend(["--registry", registry]);
        }
        let output = self
            .runner
            .run_quiet("cargo", &args, &self.prepared.root, std::time::Duration::from_secs(300))?;
        registry_argv::classify_cargo_info_output(&output).map_err(|source| GraphError::Registry {
            package: package_name.to_string(),
            source,
        })
    }

    fn dispatch_tag(
        &self,
        permit: &ApplyPermit,
        name: &TagName,
        target: &CommitSha,
        annotation: &str,
    ) -> Result<OperationOutcome, GraphError> {
        if let Some(observed) = self.observed_tag(name)? {
            return if observed.target == *target && observed.annotation == annotation {
                Ok(OperationOutcome::AlreadySatisfied)
            } else {
                Err(GraphError::ReleaseRemoteConflict {
                    conflict: RemoteConflict::TagTargetDiffers,
                })
            };
        }
        // Delegates to `GitAccess::create_tag` rather than inlining `git
        // tag` argv, so this inherits its `--` end-of-options separator
        // (defends `name` against being misread as a flag) on top of the
        // `--no-sign` this durable path has always needed (this repo's CI
        // sets `tag.gpgSign`/`commit.gpgsign` globally in some contexts,
        // with no tag-signing key available here).
        let git = GitAccess::discover(&self.prepared.root, self.runner);
        git.create_tag(
            name.as_str(),
            target,
            Some(annotation),
            TagSignPolicy::ForceUnsigned,
            permit,
        )?;
        let remote_endpoint = self.checked_git_remote()?.endpoint.clone();
        let push_args = ["push", remote_endpoint.as_str(), name.as_str()];
        let pushed = self.runner.run("git", &push_args, &self.prepared.root)?;
        if pushed.exit_code != Some(0) {
            return Err(GraphError::ReleaseCommand {
                program: "git".to_string(),
                args: push_args.iter().map(ToString::to_string).collect(),
                failure: CommandFailure::NonZeroExit {
                    exit_code: pushed.exit_code,
                    stderr: pushed.stderr,
                },
            });
        }
        if self
            .observed_tag(name)?
            .is_some_and(|observed| observed.target == *target && observed.annotation == annotation)
        {
            Ok(OperationOutcome::Published)
        } else {
            Err(GraphError::ReleaseRemoteConflict {
                conflict: RemoteConflict::TagNotObservedAfterPush,
            })
        }
    }

    fn dispatch_forge_release(&self, tag: &TagName) -> Result<OperationOutcome, GraphError> {
        let remote = self.checked_git_remote()?;
        let repository = remote.github_repository.as_slug();
        match self.observed_forge_release_target(tag, &repository)? {
            ForgeReleaseObservation::Exact => return Ok(OperationOutcome::AlreadySatisfied),
            ForgeReleaseObservation::Conflict => {
                return Err(GraphError::ReleaseRemoteConflict {
                    conflict: RemoteConflict::ForgeReleaseDiffers,
                })
            }
            ForgeReleaseObservation::Missing => {}
        }
        let create_args = [
            "release",
            "create",
            tag.as_str(),
            "--repo",
            repository.as_str(),
            "--verify-tag",
            "--generate-notes",
        ];
        let created = self.runner.run("gh", &create_args, &self.prepared.root)?;
        if created.exit_code != Some(0) {
            return Err(GraphError::ReleaseCommand {
                program: "gh".to_string(),
                args: create_args.iter().map(ToString::to_string).collect(),
                failure: CommandFailure::NonZeroExit {
                    exit_code: created.exit_code,
                    stderr: created.stderr,
                },
            });
        }
        if self.observed_forge_release_target(tag, &repository)? == ForgeReleaseObservation::Exact {
            Ok(OperationOutcome::Published)
        } else {
            Err(GraphError::ReleaseRemoteConflict {
                conflict: RemoteConflict::ForgeReleaseNotObservedAfterCreate,
            })
        }
    }

    fn observed_tag(&self, name: &TagName) -> Result<Option<ObservedTag>, GraphError> {
        let reference = format!("refs/tags/{name}^{{commit}}");
        let rev_parse_args = ["rev-parse", "--verify", "--quiet", reference.as_str()];
        let observed = self.runner.run("git", &rev_parse_args, &self.prepared.root)?;
        if observed.exit_code != Some(0) {
            return Ok(None);
        }
        let target = CommitSha::parse(observed.stdout.trim()).map_err(|error| GraphError::ReleaseCommand {
            program: "git".to_string(),
            args: rev_parse_args.iter().map(ToString::to_string).collect(),
            failure: CommandFailure::MalformedOutput {
                detail: error.to_string(),
            },
        })?;
        let for_each_ref_target = format!("refs/tags/{name}");
        let for_each_ref_args = [
            "for-each-ref",
            "--format=%(objecttype)%00%(contents:subject)%00%(contents:body)",
            for_each_ref_target.as_str(),
        ];
        let details = self.runner.run("git", &for_each_ref_args, &self.prepared.root)?;
        if details.exit_code != Some(0) {
            return Err(GraphError::ReleaseCommand {
                program: "git".to_string(),
                args: for_each_ref_args.iter().map(ToString::to_string).collect(),
                failure: CommandFailure::NonZeroExit {
                    exit_code: details.exit_code,
                    stderr: details.stderr,
                },
            });
        }
        let line = details.stdout.trim_end_matches(['\r', '\n']);
        let mut fields = line.split('\0');
        let object_type = fields.next();
        let annotation = fields.next();
        let body = fields.next();
        if object_type != Some("tag") || body.is_none_or(|body| !body.trim().is_empty()) || fields.next().is_some() {
            return Err(GraphError::ReleaseCommand {
                program: "git".to_string(),
                args: for_each_ref_args.iter().map(ToString::to_string).collect(),
                failure: CommandFailure::MalformedOutput {
                    detail: format!("unexpected for-each-ref output: {line:?}"),
                },
            });
        }
        let annotation = annotation.ok_or_else(|| GraphError::ReleaseInvariant {
            detail: "for-each-ref line validated as `tag`/empty-body but carried no annotation field".to_string(),
        })?;
        Ok(Some(ObservedTag {
            target,
            annotation: annotation.to_string(),
        }))
    }

    fn observed_forge_release_target(
        &self,
        tag: &TagName,
        repository: &str,
    ) -> Result<ForgeReleaseObservation, GraphError> {
        let endpoint = format!("repos/{repository}/releases/tags/{tag}");
        let api_args = [
            "api",
            "--include",
            "--method",
            "GET",
            endpoint.as_str(),
            "--repo",
            repository,
        ];
        let observed = self.runner.run("gh", &api_args, &self.prepared.root)?;
        if observed.exit_code != Some(0) {
            return Err(GraphError::ReleaseCommand {
                program: "gh".to_string(),
                args: api_args.iter().map(ToString::to_string).collect(),
                failure: CommandFailure::NonZeroExit {
                    exit_code: observed.exit_code,
                    stderr: observed.stderr,
                },
            });
        }
        let (status, body) = parse_github_api_response("gh", &api_args, &observed.stdout)?;
        if status == 404 {
            return Ok(ForgeReleaseObservation::Missing);
        }
        if status != 200 {
            return Err(GraphError::ReleaseRemoteConflict {
                conflict: RemoteConflict::ForgeApiStatus,
            });
        }
        let value: serde_json::Value = serde_json::from_str(body).map_err(|error| GraphError::ReleaseCommand {
            program: "gh".to_string(),
            args: api_args.iter().map(ToString::to_string).collect(),
            failure: CommandFailure::MalformedOutput {
                detail: error.to_string(),
            },
        })?;
        let expected = self.prepared.source.as_str();
        Ok(
            if value.get("tag_name").and_then(serde_json::Value::as_str) == Some(tag.as_str())
                && value.get("target_commitish").and_then(serde_json::Value::as_str) == Some(expected)
            {
                ForgeReleaseObservation::Exact
            } else {
                ForgeReleaseObservation::Conflict
            },
        )
    }

    fn checked_git_remote(&self) -> Result<&PreparedGitRemote, GraphError> {
        let expected = &self.prepared.git_remote;
        if prepared_git_remote(&self.prepared.root, self.runner)? != *expected {
            return Err(GraphError::ReleaseIntentStale {
                reason: StaleReason::git_remote_changed(),
            });
        }
        Ok(expected)
    }
}

fn parse_github_api_response<'a>(program: &str, args: &[&str], stdout: &'a str) -> Result<(u16, &'a str), GraphError> {
    let malformed = |detail: String| GraphError::ReleaseCommand {
        program: program.to_string(),

output.text:
                            password_env_name,
                            username,
                        },
                    },
                }
            }
            PreparedOperation::ProductTag {
                name,
                target,
                annotation,
                remote,
            } => PreparedOperationView::ProductTag {
                name,
                target,
                annotation,
                remote_name: remote.remote_name,
                repository: &remote.github_repository,
            },
            PreparedOperation::ForgePrepare { repository, tag } => {
                PreparedOperationView::ForgePrepare { repository, tag }
            }
            PreparedOperation::ArtifactUpload { slot } => PreparedOperationView::ArtifactUpload { slot },
            PreparedOperation::ForgePublish { repository, tag } => {
                PreparedOperationView::ForgePublish { repository, tag }
            }
        })
    }

    /// Re-observes the held workspace immediately before an effect.
    #[allow(dead_code)] // consumed by the durable execution coordinator
    pub(crate) fn recheck_trust(&self) -> Result<(), GraphError> {
        let evidence =
            callisto_vcs::GitAccess::discover(&self.prepared.root, self.runner).observe_git_commit_trust()?;
        if evidence != self.prepared.trust || evidence.head() != &self.prepared.source {
            return Err(GraphError::ReleaseIntentStale {
                reason: StaleReason::trust_evidence_changed(),
            });
        }
        if prepared_git_remote(&self.prepared.root, self.runner).as_ref() != Ok(&self.prepared.git_remote) {
            return Err(GraphError::ReleaseIntentStale {
                reason: StaleReason::git_remote_changed(),
            });
        }
        Ok(())
    }
}

/// Builds a release intent from a fresh root-bound observation.
pub fn build_release_intent<L: ProjectLocator, R: CommandRunner>(
    root: &Path,
    locator: &L,
    runner: &R,
    decision: &ReleaseDecisionV1,
    profile_name: &str,
) -> Result<ReleaseIntent, GraphError> {
    let root = canonical_root(root)?;
    let workspace = Workspace::load(root.clone(), locator, runner)?;
    let source = observe_source(&workspace)?;
    let intent = derive_product_release(&workspace, decision, source.clone(), profile_name)?.intent;

    // Recheck after all input reads. A concurrent edit or checkout cannot be
    // authorized merely because it happened after the first check.
    if observe_source(&workspace)? != source {
        return Err(GraphError::ReleaseIntentStale {
            reason: StaleReason::source_identity_changed(),
        });
    }
    Ok(intent)
}

/// Re-observes root, config, package discovery, manifests, Git evidence, and
/// the exact operation DAG before creating an opaque authorization capability.
pub fn validate_release_intent<'a, L: ProjectLocator, R: CommandRunner>(
    root: &Path,
    locator: &L,
    runner: &'a R,
    received: ReleaseIntent,
) -> Result<ValidatedReleaseIntent<'a>, GraphError> {
    validate_release_intent_with_state_directory(root, locator, runner, None, received)
}

/// Validates an intent while placing its workspace lock under an explicit
/// caller-owned state directory.
///
/// CI callers that supply an explicit durable state file must use its parent
/// here as well.  Otherwise validation would still depend on the runner's
/// implicit platform state location, defeating hermetic job handoff.
pub fn validate_release_intent_with_state_directory<'a, L: ProjectLocator, R: CommandRunner>(
    root: &Path,
    locator: &L,
    runner: &'a R,
    state_directory: Option<&Path>,
    received: ReleaseIntent,
) -> Result<ValidatedReleaseIntent<'a>, GraphError> {
    let root = canonical_root(root)?;
    let workspace = Workspace::load(root.clone(), locator, runner)?;
    let initial_trust = observe_git_trust(&workspace)?;
    let lock = ReleaseWorkspaceLock::acquire(&root, state_directory)?;
    let trust = observe_git_trust(&workspace)?;
    if trust != initial_trust {
        return Err(GraphError::ReleaseIntentStale {
            reason: StaleReason::trust_evidence_changed(),
        });
    }
    let source = trust.head().clone();
    let approved_decision = super::release_decision::derive_release_commit_decision(
        &workspace,
        received.source_commit(),
        Path::new(super::release_decision::CANONICAL_RELEASE_DECISION_PATH),
    )?;
    if &approved_decision != received.decision() {
        return Err(GraphError::ReleaseIntentStale {
            reason: StaleReason::intent_differs_from_fresh_derivation(),
        });
    }
    let prepared = derive_product_release(
        &workspace,
        &approved_decision,
        source.clone(),
        received.destination().profile_name(),
    )?;
    let final_trust = observe_git_trust(&workspace)?;
    if prepared.intent != received || final_trust != trust {
        return Err(GraphError::ReleaseIntentStale {
            reason: StaleReason::intent_differs_from_fresh_derivation(),
        });
    }

    Ok(ValidatedReleaseIntent {
        prepared: PreparedReleaseInputs {
            root,
            source,
            trust: final_trust,
            git_remote: prepared.git_remote,
            _lock: lock,
            operations: prepared.operations,
        },
        intent: received,
        runner,
    })
}

