fn observe_npm_bytes(
    validated: &ValidatedReleaseIntent<'_>,
    package: &str,
    version: &Version,
    registry: &str,
) -> Result<Option<Vec<u8>>, ObservationFailure> {
    let directory = tempfile::tempdir().map_err(|_| ObservationFailure::Capability {
        provider: ObservationProvider::Npm,
    })?;
    let spec = format!("{package}@{}", version.render());
    let destination = directory.path().to_string_lossy();
    let args = [
        "pack",
        spec.as_str(),
        "--json",
        "--ignore-scripts",
        "--pack-destination",
        destination.as_ref(),
        "--registry",
        registry,
    ];
    let output = validated
        .runner()
        .run_quiet("npm", &args, validated.root(), OBSERVATION_TIMEOUT)
        .map_err(|_| ObservationFailure::Command {
            provider: ObservationProvider::Npm,
        })?;
    if !output.success() {
        if npm_structured_error_code(&output).is_some_and(|code| matches!(code, "E404" | "ETARGET")) {
            return Ok(None);
        }
        return Err(ObservationFailure::Command {
            provider: ObservationProvider::Npm,
        });
    }
    let value: serde_json::Value =
        serde_json::from_str(&output.stdout).map_err(|_| ObservationFailure::MalformedResponse {
            provider: ObservationProvider::Npm,
        })?;
    let entries = value.as_array().ok_or(ObservationFailure::MalformedResponse {
        provider: ObservationProvider::Npm,
    })?;
    if entries.len() != 1 {
        return Err(ObservationFailure::MalformedResponse {
            provider: ObservationProvider::Npm,
        });
    }
    let file_name = entries[0].get("filename").and_then(serde_json::Value::as_str).ok_or(
        ObservationFailure::MalformedResponse {
            provider: ObservationProvider::Npm,
        },
    )?;
    if Path::new(file_name).components().count() != 1 {
        return Err(ObservationFailure::MalformedResponse {
            provider: ObservationProvider::Npm,
        });
    }
    let mut url = url::Url::parse(endpoint).ok()?;
    if url.path_segments()?.next_back() != Some("new") {
        return None;
    }
    let rendered_version = version.render();
    {
        let mut segments = url.path_segments_mut().ok()?;
        segments.pop_if_empty();
        segments.pop();
        segments.extend([package, rendered_version]);
    }
    Some(url.to_string())
}

fn append_url_segments(base: &str, segments: &[&str]) -> Option<String> {
    let mut url = url::Url::parse(base).ok()?;
    {
        let mut path = url.path_segments_mut().ok()?;
        path.pop_if_empty();
        path.extend(segments.iter().copied());
    }
    Some(url.to_string())
}

fn malformed(provider: ObservationProvider) -> OperationObservation {
    OperationObservation::Unverifiable(ObservationFailure::MalformedResponse { provider })
}

#[cfg(test)]
mod tests {
    use std::{
        collections::VecDeque,
        path::Path,
        sync::{Arc, Mutex},
    };

    use callisto_model::{CommandError, CommandRunner};

    use super::*;

    #[derive(Clone, Default)]
    struct RecordingRunner {
        calls: Arc<Mutex<Vec<(String, Vec<String>)>>>,
        outputs: Arc<Mutex<VecDeque<Result<CommandOutput, CommandError>>>>,
    }

    impl CommandRunner for RecordingRunner {
        fn run(&self, program: &str, args: &[&str], _cwd: &Path) -> Result<CommandOutput, CommandError> {
            self.calls.lock().unwrap().push((
                program.to_string(),
                args.iter().map(|value| value.to_string()).collect(),
            ));
            self.outputs.lock().unwrap().pop_front().unwrap()
        }
    }

    fn output(exit_code: i32, stdout: &str, stderr: &str) -> Result<CommandOutput, CommandError> {
        Ok(CommandOutput {
            exit_code: Some(exit_code),
            stdout: stdout.to_string(),
            stderr: stderr.to_string(),
        })
    }

    #[test]
    fn github_parser_accepts_real_nonzero_404_response_without_accepting_bare_error_text() {
        let response = CommandOutput {
            exit_code: Some(1),
            stdout: "HTTP/2 404 Not Found\r\ncontent-type: application/json\r\n\r\n{\"message\":\"Not Found\"}".into(),
            stderr: "gh: Not Found (HTTP 404)".into(),
        };
        assert_eq!(parse_http_response(&response).map(|(status, _)| status), Some(404));
        let bare = CommandOutput {
            exit_code: Some(1),
            stdout: String::new(),
            stderr: "gh: Not Found (HTTP 404)".into(),
        };
        assert_eq!(parse_http_response(&bare), None);
    }

    #[test]
    fn github_asset_parser_requires_sha256_and_rejects_duplicate_names() {
        let digest = "a".repeat(64);
        let assets = serde_json::json!([
            {"name":"callisto.tar.gz","size":12,"digest":format!("sha256:{digest}")}
        ]);
        let parsed = parse_github_assets(Some(&assets)).unwrap();
        assert_eq!(parsed["callisto.tar.gz"].digest.as_ref().unwrap().as_str(), digest);
        let duplicate = serde_json::json!([
            {"name":"same","size":1,"digest":format!("sha256:{digest}")},
            {"name":"same","size":1,"digest":format!("sha256:{digest}")}
        ]);
        assert!(parse_github_assets(Some(&duplicate)).is_none());
    }

    #[test]
    fn github_release_uses_supported_api_argv_and_includes_assets() {
        let runner = RecordingRunner::default();
        runner.outputs.lock().unwrap().push_back(output(
            0,
            &format!(
                "HTTP/2 200 OK\r\ncontent-type: application/json\r\n\r\n{{\"tag_name\":\"callisto@1.2.3\",\"draft\":true,\"assets\":[{{\"name\":\"a\",\"size\":1,\"digest\":\"sha256:{}\"}}]}}",
                "a".repeat(64)
            ),
            "",
        ));
        let repository = GitHubRepository::parse("owner/repository").unwrap();
        let tag = TagName::parse("callisto@1.2.3").unwrap();
        let endpoint = format!("repos/{}/releases/tags/{}", repository.as_slug(), tag.as_str());
        let args = ["api", "--include", "--method", "GET", endpoint.as_str()];
        let first = runner
            .run_quiet("gh", &args, Path::new("."), OBSERVATION_TIMEOUT)
            .unwrap();
        assert_eq!(parse_http_response(&first).unwrap().0, 200);
        let calls = runner.calls.lock().unwrap();
        assert_eq!(calls[0].1, args);
        assert!(!calls[0].1.contains(&"--repo".to_string()));
    }

    #[test]
    fn provider_failures_are_not_classified_as_absence() {
        let unauthorized = CommandOutput {
            exit_code: Some(1),
            stdout: "HTTP/2 401 Unauthorized\r\n\r\n{}".into(),
            stderr: String::new(),
        };
        let malformed = CommandOutput {
            exit_code: Some(1),
            stdout: String::new(),
            stderr: "not an HTTP response".into(),
        };
        assert_eq!(parse_http_response(&unauthorized).unwrap().0, 401);
        assert_eq!(parse_http_response(&malformed), None);
    }

    #[test]
    fn npm_absence_requires_an_exact_structured_error_code() {
        let absent = CommandOutput {
            exit_code: Some(1),
            stdout: serde_json::json!({"error":{"code":"E404","summary":"missing"}}).to_string(),
            stderr: String::new(),
        };
        assert_eq!(npm_structured_error_code(&absent), Some("E404"));

        let unauthorized = CommandOutput {
            exit_code: Some(1),
            stdout: serde_json::json!({"error":{"code":"E401","summary":"package-e404 is private"}}).to_string(),
            stderr: String::new(),
        };
        assert_eq!(npm_structured_error_code(&unauthorized), Some("E401"));

        let arbitrary_text = CommandOutput {
            exit_code: Some(1),
            stdout: String::new(),
            stderr: "package-e404 returned a provider failure".to_string(),
        };
        assert_eq!(npm_structured_error_code(&arbitrary_text), None);
    }

    #[test]
    fn registry_http_classifies_only_real_404_as_absent() {
        let runner = RecordingRunner::default();
        runner.outputs.lock().unwrap().extend([
            output(0, "HTTP/1.1 404 Not Found\r\n\r\n{}", ""),
            output(0, "HTTP/1.1 401 Unauthorized\r\n\r\n{}", ""),
            output(0, "HTTP/1.1 200 OK\r\n\r\nnot-json", ""),
        ]);
        assert_eq!(
            observe_json_http(
                &runner,
                Path::new("."),
                "https://registry.example/item",
                ObservationProvider::Cargo,
            ),
            Ok(None)
        );
        assert_eq!(
            observe_json_http(
                &runner,
                Path::new("."),
                "https://registry.example/item",
                ObservationProvider::Cargo,
            ),
            Err(ObservationFailure::HttpStatus {
                provider: ObservationProvider::Cargo,
                status: 401,
            })
        );
        assert_eq!(
            observe_json_http(
                &runner,
                Path::new("."),
                "https://registry.example/item",
                ObservationProvider::Cargo,
            ),
            Err(ObservationFailure::MalformedResponse {
                provider: ObservationProvider::Cargo,
            })
        );
    }

    #[test]
    fn registry_urls_preserve_typed_base_and_encode_identity_segments() {
        let version = Version::semver(1, 2, 3);
        assert_eq!(
            cargo_metadata_url("https://crates.example/api/v1/crates/new", "scope/name", &version).unwrap(),
            "https://crates.example/api/v1/crates/scope%2Fname/1.2.3"
        );
        assert_eq!(
            append_url_segments("https://pypi.example/pypi/", &["demo-name", "1.2.3", "json"]).unwrap(),
            "https://pypi.example/pypi/demo-name/1.2.3/json"
        );
    }

    #[test]
    fn partial_evidence_never_has_an_open_missing_work_vocabulary() {
        let release = ProductReleaseId::new(
            callisto_model::ProductName::parse("callisto").unwrap(),
            Version::semver(1, 2, 3),
        )
        .unwrap();
        let partial = VerifiedPartialEvidence::new(
            vec![],
            BTreeSet::from([MissingWork::PublishForgeRelease(release.clone())]),
        );
        assert!(partial.exact().is_empty());
        assert_eq!(
            partial.missing(),
            &BTreeSet::from([MissingWork::PublishForgeRelease(release)])
        );
    }

