                "HTTP/2 200 OK\r\ncontent-type: application/json\r\n\r\n{{\"tag_name\":\"callisto@1.2.3\",\"draft\":true,\"assets\":[{{\"name\":\"a\",\"size\":1,\"digest\":\"sha256:{}\"}}]}}",
                "a".repeat(64)
            ),
