        ));
        let repository = GitHubRepository::parse("owner/repository").unwrap();
        let tag = TagName::parse("callisto@1.2.3").unwrap();
        let endpoint = format!("repos/{}/releases/tags/{}", repository.as_slug(), tag.as_str());
