type CachedObservation<T> = Result<Option<T>, ObservationFailure>;

/// Invocation-local provider cache. A convergence pass shares one session so
/// every GitHub operation sees one release/asset snapshot and every PyPI
/// operation for a version sees one distribution roster.
#[derive(Default)]
pub(super) struct ObservationSession {
    github_releases: BTreeMap<(String, String), CachedObservation<GitHubRelease>>,
    pypi_versions: BTreeMap<(String, String, String), CachedObservation<BTreeMap<String, PypiDistribution>>>,
}

impl ObservationSession {
    /// Starts a fresh observation phase after any external effect.
    ///
    /// Provider snapshots are invocation-local, but a dispatcher can observe,
    /// mutate, and then verify within one invocation. Clearing every cached
    /// provider fact is deliberately broader than operation-specific
    /// invalidation: one effect can change both a release roster and the state
    /// observed by a dependent operation.
    pub(super) fn invalidate_after_effect(&mut self) {
        self.github_releases.clear();
        self.pypi_versions.clear();
    }
}

/// Observes exactly one operation from the immutable prepared capability.
pub(super) fn observe_prepared(
    session: &mut ObservationSession,
    artifacts: &ValidatedArtifactManifest<'_, '_>,
    id: &ReleaseOperationId,
) -> OperationObservation {
    let validated = artifacts.validated_intent();
    if validated.recheck_trust().is_err() {
        return OperationObservation::Unverifiable(ObservationFailure::TrustChanged {
            provider: ObservationProvider::Git,
        });
    }
    let Some(prepared) = validated.prepared_operation(id) else {
        return OperationObservation::Unverifiable(ObservationFailure::Capability {
            provider: ObservationProvider::PreparedCapability,
        });
    };
    match (id, prepared) {
        (
            ReleaseOperationId::RegistryArtifactPublish {
                package,
                version,
                registry,
                slot,
            },
            PreparedOperationView::RegistryArtifactPublish {
                artifact,
                binding_digest,
                endpoints,
                ..
            },
        ) if artifact.package() == package
            && artifact.registry() == registry
            && registry.binding_digest() == binding_digest
            && artifact.file_name() == slot.file_name() =>
        {
            observe_registry(
                session,
                artifacts,
                validated,
                package,
                version,
                registry.clone(),
                slot,
    release: &ProductReleaseId,
    slot: &ReleaseArtifactSlot,
) -> OperationObservation {
    if let Some(failure) = require_exact_remote_tag(artifacts, validated) {
        return failure;
    }
    let repository = validated.intent().destination().forge_repository();
    let tag = release.tag();
    let Ok(tag) = TagName::parse(&tag) else {
        return malformed(ObservationProvider::PreparedCapability);
    };
    let observed = match github_release(session, validated, repository, &tag) {
        Ok(Some(observed)) => observed,
        Ok(None) => return OperationObservation::Absent,
        Err(failure) => return OperationObservation::Unverifiable(failure),
    };
    if !observed.tag_matches {
        return OperationObservation::Conflict(ExternalConflict::ForgeReleaseTag);
    }
    let Some(asset) = observed.assets.get(slot.file_name()) else {
        return OperationObservation::Absent;
    };
    compare_forge_asset(artifacts, release, slot, asset)
}

fn observe_forge_publish(
    session: &mut ObservationSession,
    artifacts: &ValidatedArtifactManifest<'_, '_>,
    validated: &ValidatedReleaseIntent<'_>,
    release: &ProductReleaseId,
    repository: &GitHubRepository,
    tag: &TagName,
) -> OperationObservation {
    if let Some(failure) = require_exact_remote_tag(artifacts, validated) {
        return failure;
    }
    let observed = match github_release(session, validated, repository, tag) {
        Ok(Some(observed)) => observed,
        Ok(None) => return OperationObservation::Absent,
        Err(failure) => return OperationObservation::Unverifiable(failure),
    };
    if !observed.tag_matches {
        return OperationObservation::Conflict(ExternalConflict::ForgeReleaseTag);
    }
    let expected_slots = validated
        .intent()
        .slots()
        .iter()
        .filter(|slot| slot.release() == Some(release))
        .cloned()
        .collect::<Vec<_>>();
    let expected_names = expected_slots
        .iter()
        .map(|slot| slot.file_name().to_string())
        .collect::<BTreeSet<_>>();
    if let Some(file_name) = observed.assets.keys().find(|name| !expected_names.contains(*name)) {
        return OperationObservation::Conflict(ExternalConflict::UnexpectedForgeAsset {
            file_name: file_name.clone(),
        });
    }
    let mut exact = Vec::new();
    let mut missing = BTreeSet::new();
    for slot in expected_slots {
        let Some(asset) = observed.assets.get(slot.file_name()) else {
            missing.insert(MissingWork::ForgeAsset(slot));
            continue;
        };
        match compare_forge_asset(artifacts, release, &slot, asset) {
            OperationObservation::Exact(evidence) => exact.push(evidence),
            other => return other,
        }
    }
    if observed.draft {
        missing.insert(MissingWork::PublishForgeRelease(release.clone()));
        return OperationObservation::Incomplete(VerifiedPartialEvidence::new(exact, missing));
    }
    if !missing.is_empty() {
        return OperationObservation::Incomplete(VerifiedPartialEvidence::new(exact, missing));
    }
    OperationObservation::Exact(ReleaseObservationEvidence::forge_publish(
        release.clone(),
        artifacts.expectations().asset_roster_digest().clone(),
    ))
}

