/// Closed provider-failure taxonomy. Raw provider output is intentionally not
/// retained: stderr can contain credentials and is not durable evidence.
#[derive(Clone, Debug, PartialEq, Eq)]
pub(super) enum ObservationFailure {
    TrustChanged {
        provider: ObservationProvider,
    },
    Command {
        provider: ObservationProvider,
    },
    HttpStatus {
        provider: ObservationProvider,
        status: u16,
    },
    MalformedResponse {
        provider: ObservationProvider,
    },
    MissingDigest {
        provider: ObservationProvider,
        file_name: String,
    },
    Capability {
        provider: ObservationProvider,
    },
}

/// The only observation vocabulary consumed by convergence.
#[derive(Clone, Debug, PartialEq, Eq)]
pub(super) enum OperationObservation {
    Absent,
    Incomplete(VerifiedPartialEvidence),
    Exact(ReleaseObservationEvidence),
    Conflict(ExternalConflict),
    Unverifiable(ObservationFailure),
}

