    #[test]
    fn provider_failures_are_not_classified_as_absence() {
        let unauthorized = CommandOutput {
            exit_code: Some(1),
            stdout: "HTTP/2 401 Unauthorized\r\n\r\n{}".into(),
            stderr: String::new(),
        };
        let malformed = CommandOutput {
            exit_code: Some(1),
            stdout: String::new(),
            stderr: "not an HTTP response".into(),
        };
        assert_eq!(parse_http_response(&unauthorized).unwrap().0, 401);
        assert_eq!(parse_http_response(&malformed), None);
    }

    #[test]
    fn npm_absence_requires_an_exact_structured_error_code() {
        let absent = CommandOutput {
            exit_code: Some(1),
            stdout: serde_json::json!({"error":{"code":"E404","summary":"missing"}}).to_string(),
            stderr: String::new(),
        };
        assert_eq!(npm_structured_error_code(&absent).as_deref(), Some("E404"));

        let unauthorized = CommandOutput {
            exit_code: Some(1),
            stdout: serde_json::json!({"error":{"code":"E401","summary":"package-e404 is private"}}).to_string(),
            stderr: String::new(),
        };
        assert_eq!(npm_structured_error_code(&unauthorized).as_deref(), Some("E401"));

        let arbitrary_text = CommandOutput {
            exit_code: Some(1),
            stdout: String::new(),
            stderr: "package-e404 returned a provider failure".to_string(),
        };
        assert_eq!(npm_structured_error_code(&arbitrary_text), None);
    }

