//! Pure argv construction for publishing an exact npm-compatible tarball.
//!
//! This module only selects the package-manager-specific argv from already
//! validated facts; it never invokes a [`callisto_model::CommandRunner`] or
//! interprets provider state. Actually invoking the command is the caller's
//! job --
//! see `super::release::ValidatedReleaseIntent::dispatch_prepared`, the
//! durable release executor's single production publish path.
//!
//! The only filesystem observation here is npm package-manager detection from
//! lockfiles. It never reads a source package or shells out.

use callisto_model::NpmAccess;
use std::path::Path;

/// One subprocess invocation: program, args, and working directory. Building
/// this is the entire job of the `*_publish_argv` functions below --
/// executing it is the caller's.
#[derive(Debug, Clone, PartialEq, Eq)]
pub(super) struct Argv {
    pub(super) program: String,
    pub(super) args: Vec<String>,
}

// ------------------------------------------------------------------ npm

/// The npm-compatible package manager a workspace uses, detected from
/// lockfile presence. Each one needs a materially different exact-tarball
/// invocation; see [`npm_tarball_publish_argv`].
#[derive(Debug, Clone, Copy, PartialEq, Eq)]
pub(super) enum NpmPackageManager {
    Pnpm,
    Yarn,
    Bun,
    Npm,
}

/// Detects the npm-compatible package manager for `workspace_root` from
/// lockfile presence. Detection priority: pnpm > yarn > bun > npm (default).
///
/// This is real, live-today correctness content: the durable release
/// executor's `dispatch_registry` used to hardcode plain `npm publish`
/// regardless of which package manager a workspace actually uses, so a pnpm
/// or yarn workspace published with the wrong tool.
pub(super) fn detect_npm_package_manager(workspace_root: &Path) -> NpmPackageManager {
    if workspace_root.join("pnpm-lock.yaml").exists() {
        NpmPackageManager::Pnpm
    } else if workspace_root.join("yarn.lock").exists() {
        NpmPackageManager::Yarn
    } else if workspace_root.join("bun.lockb").exists() || workspace_root.join("bun.lock").exists() {
        // bun.lockb is the legacy binary lockfile format; bun.lock (text) is
        // written by Bun >= 1.1.1. Both signal a bun-managed workspace.
        NpmPackageManager::Bun
    } else {
        NpmPackageManager::Npm
    }
}

/// Builds an npm-compatible invocation whose only package input is one
/// private, already-validated tarball. No variant is permitted to repack a
/// workspace, and scripts are disabled explicitly.
pub(super) fn npm_tarball_publish_argv(
    tarball: &Path,
    package_manager: NpmPackageManager,
    tag: &str,
    access: NpmAccess,
    registry: &str,
) -> Argv {
    let tarball_argument = tarball.to_string_lossy().into_owned();
    let (program, mut args) = match package_manager {
        NpmPackageManager::Pnpm => (
            "pnpm",
            vec![
                "publish".to_string(),
                tarball_argument,
                "--ignore-scripts".to_string(),
                "--no-git-checks".to_string(),
            ],
        ),
        NpmPackageManager::Yarn => (
            "yarn",
            vec![
                "publish".to_string(),
                tarball_argument,
                "--ignore-scripts".to_string(),
                "--non-interactive".to_string(),
            ],
        ),
        NpmPackageManager::Bun => (
            "bun",
            vec!["publish".to_string(), tarball_argument, "--ignore-scripts".to_string()],
        ),
        NpmPackageManager::Npm => (
            "npm",
            vec!["publish".to_string(), tarball_argument, "--ignore-scripts".to_string()],
        ),
    };
    args.extend([
        "--tag".to_string(),
        tag.to_string(),
        "--access".to_string(),
        match access {
            NpmAccess::Public => "public".to_string(),
            NpmAccess::Restricted => "restricted".to_string(),
        },
        "--registry".to_string(),
        registry.to_string(),
    ]);
    Argv {
        program: program.to_string(),
        args,
    }
}

