mod tests {
    use super::*;

    // ------------------------------------------------------------------ npm

    #[test]
    fn detects_pnpm_from_lockfile() {
        let dir = tempfile::tempdir().unwrap();
        std::fs::write(dir.path().join("pnpm-lock.yaml"), "").unwrap();
