    }

    #[test]
    fn pnpm_publish_argv_uses_only_exact_tarball_and_no_scripts() {
        let argv = npm_tarball_publish_argv(
            Path::new("/private/pkg-a.tgz"),
            NpmPackageManager::Pnpm,
            "next",
            NpmAccess::Public,
            "https://registry.example.test/",
        );
        assert_eq!(argv.program, "pnpm");
        assert_eq!(
            argv.args,
            vec![
                "publish",
                "/private/pkg-a.tgz",
                "--ignore-scripts",
                "--no-git-checks",
                "--tag",
                "next",
                "--access",
                "public",
                "--registry",
                "https://registry.example.test/",
            ]
        );
    }

    #[test]
    fn yarn_publish_argv_uses_only_exact_tarball() {
        let argv = npm_tarball_publish_argv(
            Path::new("/private/pkg-a.tgz"),
            NpmPackageManager::Yarn,
            "latest",
            NpmAccess::Restricted,
            "https://registry.example.test/",
        );
        assert_eq!(argv.program, "yarn");
        assert!(argv.args.starts_with(&[
            "publish".to_string(),
            "/private/pkg-a.tgz".to_string(),
            "--ignore-scripts".to_string(),
        ]));
    }

    #[test]
    fn bun_publish_argv_uses_only_exact_tarball() {
        let argv = npm_tarball_publish_argv(
            Path::new("/private/pkg-a.tgz"),
            NpmPackageManager::Bun,
            "latest",
            NpmAccess::Public,
            "https://registry.example.test/",
        );
        assert_eq!(argv.program, "bun");
        assert!(argv.args.contains(&"/private/pkg-a.tgz".to_string()));
        assert!(argv.args.contains(&"--ignore-scripts".to_string()));
    }

    #[test]
    fn npm_publish_argv_uses_only_exact_tarball() {
        let argv = npm_tarball_publish_argv(
            Path::new("/private/pkg-a.tgz"),
            NpmPackageManager::Npm,
            "latest",
            NpmAccess::Public,
            "https://registry.example.test/",
        );
        assert_eq!(argv.program, "npm");
        assert!(argv.args.contains(&"/private/pkg-a.tgz".to_string()));
        assert!(!argv.args.iter().any(|argument| argument == "--workspace"));
    }
}

