//! Observation-authoritative convergence for one validated release.
//!
//! Local execution state is diagnostic only. Every invocation derives its
//! authority from fresh provider observation, performs each proven-missing
//! effect at most once, and persists a receipt only after a separate final
//! pass proves the complete canonical operation roster exact.

use std::collections::{BTreeMap, BTreeSet};

use callisto_model::{
    ApplyPermit, CompleteObservationReceipt, ObservationProvenance, ObservedOperation, OperationOutcome,
    ReleaseExecutionState, ReleaseIntent, ReleaseOperationId, ReleaseOperationState,
};

use crate::GraphError;

use super::{
    release::ValidatedReleaseIntent,
    release_artifacts::ValidatedArtifactManifest,
    release_observation::{
        observe_prepared, MissingWork, ObservationSession, OperationObservation, VerifiedPartialEvidence,
    },
    release_receipt_store::{ReleaseReceiptStore, ReleaseReceiptWriter},
};

/// Converges one validated release from external truth and writes its strict
/// final observation receipt atomically. No journal or prior receipt is read.
pub fn converge_release<W: ReleaseReceiptWriter>(
    capability: &ValidatedReleaseIntent<'_>,
    artifacts: &ValidatedArtifactManifest<'_, '_>,
    receipt_store: &ReleaseReceiptStore<W>,
    permit: &ApplyPermit,
) -> Result<CompleteObservationReceipt, GraphError> {
    let intent = capability.intent();
    let mut observations = ObservationSession::default();
    let mut provenance = BTreeMap::new();

    for operation in intent.operations() {
        let id = operation.id();
        let observed = observe_prepared(&mut observations, artifacts, id);
        if observation_satisfies_operation(id, &observed) {
            provenance.insert(id.clone(), ObservationProvenance::AlreadyPresent);
            continue;
        }
        require_dispatchable_missing_work(id, &observed)?;
        let outcome = capability.dispatch_prepared(artifacts, &mut observations, permit, id)?;
        provenance.insert(
            id.clone(),
            match outcome {
                OperationOutcome::Published => ObservationProvenance::NewlyProduced,
                OperationOutcome::AlreadySatisfied => ObservationProvenance::AlreadyPresent,
                OperationOutcome::Failed | OperationOutcome::Blocked { .. } => {
                    return Err(GraphError::ReleaseOperationNotMissing { operation: id.clone() });
                }
            },
        );
    }

    observations.invalidate_after_effect();
    let mut exact = Vec::with_capacity(intent.operations().len());
    for operation in intent.operations() {
        let id = operation.id();
        let evidence = match observe_prepared(&mut observations, artifacts, id) {
            OperationObservation::Exact(evidence) => evidence,
            OperationObservation::Conflict(_) => {
                return Err(GraphError::ReleaseObservationConflict { operation: id.clone() });
            }
            OperationObservation::Unverifiable(_) => {
                return Err(GraphError::ReleaseObservationUnverifiable { operation: id.clone() });
            }
            OperationObservation::Absent | OperationObservation::Incomplete(_) => {
                return Err(GraphError::ReleaseOperationNotMissing { operation: id.clone() });
            }
        };
        exact.push(ObservedOperation::new(
            id.clone(),
            evidence,
            provenance
                .get(id)
                .copied()
                .unwrap_or(ObservationProvenance::AlreadyPresent),
        ));
    }

    let expectations = artifacts.expectations();
    let receipt = CompleteObservationReceipt::new(intent, &expectations, exact).map_err(|source| {
        GraphError::ReleaseInvariant {
            detail: format!("final exact observation roster did not form a receipt: {source}"),
        }
    })?;
    receipt_store.save(intent, &expectations, &receipt, permit)?;
    Ok(receipt)
}

fn observation_satisfies_operation(id: &ReleaseOperationId, observed: &OperationObservation) -> bool {
    match observed {
        OperationObservation::Exact(_) => true,
        OperationObservation::Incomplete(partial) => match id {
            ReleaseOperationId::RegistryArtifactPublish { slot, .. } => {
                !partial.missing().contains(&MissingWork::RegistryArtifact(slot.clone()))
            }
            _ => false,
        },
        OperationObservation::Absent | OperationObservation::Conflict(_) | OperationObservation::Unverifiable(_) => {
            false
        }
    }
}

fn require_dispatchable_missing_work(
    id: &ReleaseOperationId,
    observed: &OperationObservation,
) -> Result<(), GraphError> {
    match observed {
        OperationObservation::Absent
            if matches!(
                id,
                ReleaseOperationId::RegistryArtifactPublish { .. }
                    | ReleaseOperationId::ProductTag { .. }
                    | ReleaseOperationId::ForgePrepare { .. }
                    | ReleaseOperationId::ArtifactUpload { .. }
            ) =>
        {
            Ok(())
        }
        OperationObservation::Incomplete(partial) if incomplete_authorizes_operation(id, partial) => Ok(()),
        OperationObservation::Conflict(_) => Err(GraphError::ReleaseObservationConflict { operation: id.clone() }),
        OperationObservation::Unverifiable(_) => {
            Err(GraphError::ReleaseObservationUnverifiable { operation: id.clone() })
        }
        OperationObservation::Absent | OperationObservation::Incomplete(_) | OperationObservation::Exact(_) => {
            Err(GraphError::ReleaseOperationNotMissing { operation: id.clone() })
        }
    }
}

fn incomplete_authorizes_operation(id: &ReleaseOperationId, partial: &VerifiedPartialEvidence) -> bool {
    match id {
        ReleaseOperationId::RegistryArtifactPublish { slot, .. } => {
            partial.missing().contains(&MissingWork::RegistryArtifact(slot.clone()))
        }
        ReleaseOperationId::ForgePublish { release, .. } => {
            partial.missing().len() == 1
                && partial
                    .missing()
                    .contains(&MissingWork::PublishForgeRelease(release.clone()))
        }
        ReleaseOperationId::ProductTag { .. }
        | ReleaseOperationId::ForgePrepare { .. }
        | ReleaseOperationId::ArtifactUpload { .. } => false,
    }
}

/// Read-only interpretation of a diagnostic journal. Convergence never reads it.
#[derive(Clone, Debug, PartialEq, Eq)]
pub struct ReconciledReleaseExecution {
    eligible: Vec<ReleaseOperationId>,
}

impl ReconciledReleaseExecution {
    pub fn eligible(&self) -> &[ReleaseOperationId] {
        &self.eligible
    }
}

pub fn reconcile_release_execution(
    intent: &ReleaseIntent,
    state: &ReleaseExecutionState,
) -> Result<ReconciledReleaseExecution, GraphError> {
    state
        .validate_for_intent(intent)
        .map_err(|source| GraphError::ReleaseExecutionState { source })?;
    let prerequisites: BTreeMap<_, _> = intent
        .operations()
        .iter()
        .map(|operation| (operation.id().clone(), operation.prerequisites().to_vec()))
        .collect();
    let mut eligible = Vec::new();
    for operation in intent.operations() {
        if state.operation_state(operation.id()) != Some(ReleaseOperationState::Pending) {
            continue;
        }
        let mut visited = BTreeSet::new();
        if prerequisites_satisfied_transitively(operation.id(), &prerequisites, state, &mut visited) {
            eligible.push(operation.id().clone());
        }
    }
    Ok(ReconciledReleaseExecution { eligible })
}

fn prerequisites_satisfied_transitively(
    id: &ReleaseOperationId,
    prerequisites: &BTreeMap<ReleaseOperationId, Vec<ReleaseOperationId>>,
    state: &ReleaseExecutionState,
    visited: &mut BTreeSet<ReleaseOperationId>,
) -> bool {
    if !visited.insert(id.clone()) {
        return false;
    }
    let result = prerequisites.get(id).is_some_and(|direct| {
        direct.iter().all(|prerequisite| {
            matches!(
                state.operation_state(prerequisite),
                Some(ReleaseOperationState::Published | ReleaseOperationState::AlreadySatisfied)
            ) && prerequisites_satisfied_transitively(prerequisite, prerequisites, state, visited)
        })
    });
    visited.remove(id);
    result
}

