//! Pure argv construction for publishing an exact npm-compatible tarball.
//!
//! This module only selects the package-manager-specific argv from already
//! validated facts; it never invokes a [`callisto_model::CommandRunner`] or
//! interprets provider state. Actually invoking the command is the caller's
//! job --
//! see `super::release::ValidatedReleaseIntent::dispatch_prepared`, the
//! durable release executor's single production publish path.
//!
//! It never reads a source package or shells out.

use callisto_model::NpmAccess;
use std::path::Path;

/// One subprocess invocation: program, args, and working directory. Building
/// this is the entire job of the `*_publish_argv` functions below --
/// executing it is the caller's.
#[derive(Debug, Clone, PartialEq, Eq)]
pub(super) struct Argv {
    pub(super) program: String,
    pub(super) args: Vec<String>,
}

// ------------------------------------------------------------------ npm

/// Builds the one canonical npm invocation whose only package input is a
/// private, already-validated tarball. Workspace package-manager selection is
/// intentionally irrelevant: pnpm, Yarn Berry, and Bun do not share one
/// stable exact-tarball publish contract, while the registry protocol is npm's
/// and the canonical npm client accepts the artifact directly.
pub(super) fn npm_tarball_publish_argv(tarball: &Path, tag: &str, access: NpmAccess, registry: &str) -> Argv {
    let tarball_argument = tarball.to_string_lossy().into_owned();
    let mut args = vec!["publish".to_string(), tarball_argument, "--ignore-scripts".to_string()];
    args.extend([
        "--tag".to_string(),
        tag.to_string(),
        "--access".to_string(),
        match access {
            NpmAccess::Public => "public".to_string(),
            NpmAccess::Restricted => "restricted".to_string(),
        },
        "--registry".to_string(),
        registry.to_string(),
    ]);
    Argv {
        program: "npm".to_string(),
        args,
    }
}

#[cfg(test)]
mod tests {
    use super::*;

    // ------------------------------------------------------------------ npm

    #[test]
    fn every_workspace_manager_converges_on_canonical_npm_exact_tarball_publish() {
        let argv = npm_tarball_publish_argv(
            Path::new("/private/pkg-a.tgz"),
            "next",
            NpmAccess::Public,
            "https://registry.example.test/",
        );
        assert_eq!(argv.program, "npm");
        assert_eq!(
            argv.args,
            vec![
                "publish",
                "/private/pkg-a.tgz",
                "--ignore-scripts",
                "--tag",
                "next",
                "--access",
                "public",
                "--registry",
                "https://registry.example.test/",
            ]
        );
    }
}
