#[test]
fn partial_evidence_never_has_an_open_missing_work_vocabulary() {
    let release = ProductReleaseId::new(
        callisto_model::ProductName::parse("callisto").unwrap(),
        Version::semver(1, 2, 3),
    )
    .unwrap();
    let partial = VerifiedPartialEvidence::new(
        vec![],
        BTreeSet::from([MissingWork::PublishForgeRelease(release.clone())]),
    );
    assert!(partial.exact().is_empty());
    assert_eq!(
        partial.missing(),
        &BTreeSet::from([MissingWork::PublishForgeRelease(release)])
    );
}

#[test]
fn effect_invalidation_discards_all_provider_snapshots() {
    let mut session = ObservationSession::default();
    session
        .github_releases
        .insert(("owner/repository".to_string(), "callisto@1.2.3".to_string()), Ok(None));
    session.pypi_versions.insert(
        (
            "https://pypi.example/pypi/".to_string(),
            "demo".to_string(),
            "1.2.3".to_string(),
        ),
        Ok(None),
    );

    session.invalidate_after_effect();

    assert!(session.github_releases.is_empty());
    assert!(session.pypi_versions.is_empty());
}

#[test]
fn validated_capability_drives_all_observation_outcomes_and_provider_branches() {
    use crate::commands::release::{build_release_intent, validate_release_intent, PreparedOperationView};

    let (workspace, decision) = capability_workspace();
    let root = workspace.path();
    let runner = CapabilityRunner::default();
    let locator = crate::IgnoreWalkLocator::new(root);
    let intent = build_release_intent(root, &locator, &runner, &decision, "production").unwrap();
    let validated = validate_release_intent(root, &locator, &runner, intent).unwrap();
    let (_artifact_directory, artifacts) = artifact_fixture(&validated, &runner);
    let expectations = artifacts.expectations();
    let mut session = ObservationSession::default();

    let operation_ids = validated
        .intent()
        .operations()
        .iter()
        .map(|operation| operation.id().clone())
        .collect::<Vec<_>>();
    let tag_id = operation_ids
        .iter()
        .find(|id| matches!(id, ReleaseOperationId::ProductTag { .. }))
        .unwrap()
        .clone();
    let prepare_id = operation_ids
        .iter()
        .find(|id| matches!(id, ReleaseOperationId::ForgePrepare { .. }))
        .unwrap()
        .clone();
    let publish_id = operation_ids
        .iter()
        .find(|id| matches!(id, ReleaseOperationId::ForgePublish { .. }))
        .unwrap()
        .clone();
    let upload_id = operation_ids
        .iter()
        .find(|id| matches!(id, ReleaseOperationId::ArtifactUpload { .. }))
        .unwrap()
        .clone();
    let registry_id = |ecosystem| {
        operation_ids
            .iter()
            .find(|id| {
                matches!(
                    id,
                    ReleaseOperationId::RegistryArtifactPublish { package, .. }
                        if package.ecosystem() == ecosystem
                )
            })
            .unwrap()
            .clone()
    };
    let cargo_id = registry_id(Ecosystem::Cargo);
    let npm_id = registry_id(Ecosystem::Npm);
    let pypi_id = registry_id(Ecosystem::Pypi);

    // A local checkout cannot stand in for the configured remote tag.
    assert_eq!(
        observe_prepared(&mut session, &artifacts, &tag_id),
        OperationObservation::Absent
    );
    let (tag_name, tag_target, tag_annotation) = match validated.prepared_operation(&tag_id).unwrap() {
        PreparedOperationView::ProductTag {
            name,
            target,
            annotation,
            ..
        } => (name.clone(), target.clone(), annotation.to_string()),
        _ => unreachable!(),
    };
    runner.set_exact_remote_tag(&tag_name, &tag_target, &tag_annotation);
    assert!(matches!(
        observe_prepared(&mut session, &artifacts, &tag_id),
        OperationObservation::Exact(_)
    ));

    let (release, release_tag) = match &prepare_id {
        ReleaseOperationId::ForgePrepare { release, .. } => (release.clone(), release.tag()),
        _ => unreachable!(),
    };
    runner.push_github(1, 404, serde_json::json!({"message":"Not Found"}));
    assert_eq!(
        observe_prepared(&mut session, &artifacts, &prepare_id),
        OperationObservation::Absent
    );
    runner.push_github(
        0,
        200,
        serde_json::json!({"tag_name":release_tag,"draft":true,"assets":[]}),
    );
    // The same phase returns its cached absence; a post-effect phase must
    // explicitly discard it before readback.
    assert_eq!(
        observe_prepared(&mut session, &artifacts, &prepare_id),
        OperationObservation::Absent
    );
    session.invalidate_after_effect();
    assert!(matches!(
        observe_prepared(&mut session, &artifacts, &prepare_id),
        OperationObservation::Exact(_)
    ));
    let github_api_calls = runner
        .calls
        .lock()
        .unwrap()
        .iter()
        .filter(|(program, args)| program == "gh" && args.first().is_some_and(|argument| argument == "api"))
        .cloned()
        .collect::<Vec<_>>();
    assert_eq!(
        github_api_calls.len(),
        2,
        "cached observation must not issue a second API call"
    );
    for (_, args) in github_api_calls {
        assert_eq!(&args[..4], ["api", "--include", "--method", "GET"]);
        assert!(!args.iter().any(|argument| argument == "--repo"));
        assert!(!args.iter().any(|argument| argument.contains("target_commitish")));
    }

    session.invalidate_after_effect();
    runner.push_github(1, 401, serde_json::json!({"message":"Unauthorized"}));
    assert_eq!(
        observe_prepared(&mut session, &artifacts, &prepare_id),
        OperationObservation::Unverifiable(ObservationFailure::HttpStatus {
            provider: ObservationProvider::GitHub,
            status: 401,
        })
    );

    let forge_slots = validated
        .intent()
        .slots()
        .iter()
        .filter(|slot| slot.release() == Some(&release))
        .cloned()
        .collect::<Vec<_>>();
    let github_asset = |slot: &ReleaseArtifactSlot, digest_override: Option<String>| {
        let (digest, length) = expectations.artifact(slot).unwrap();
        serde_json::json!({
            "name": slot.file_name(),
            "size": length,
            "digest": format!("sha256:{}", digest_override.unwrap_or_else(|| digest.as_str().to_string()))
        })
    };
    session.invalidate_after_effect();
    runner.push_github(
        0,
        200,
        serde_json::json!({
            "tag_name": release.tag(),
            "draft": false,
            "assets": [github_asset(&forge_slots[0], None)]
        }),
    );
    assert!(matches!(
        observe_prepared(&mut session, &artifacts, &publish_id),
        OperationObservation::Incomplete(ref partial)
            if !partial.exact().is_empty() && !partial.missing().is_empty()
    ));

    let upload_slot = match &upload_id {
        ReleaseOperationId::ArtifactUpload { slot, .. } => slot,
        _ => unreachable!(),
    };
    session.invalidate_after_effect();
    runner.push_github(
        0,
        200,
        serde_json::json!({
            "tag_name": release.tag(),
            "draft": true,
            "assets": [github_asset(upload_slot, Some("f".repeat(64)))]
        }),
    );
    assert!(matches!(
        observe_prepared(&mut session, &artifacts, &upload_id),
        OperationObservation::Conflict(ExternalConflict::ForgeAssetDigest { .. })
    ));

    let (upload_digest, upload_length) = expectations.artifact(upload_slot).unwrap();
    session.invalidate_after_effect();
    runner.push_github(
        0,
        200,
        serde_json::json!({
            "tag_name": release.tag(),
            "draft": true,
            "assets": [{
                "name": upload_slot.file_name(),
                "size": upload_length + 1,
                "digest": format!("sha256:{}", upload_digest.as_str())
            }]
        }),
    );
    assert!(matches!(
        observe_prepared(&mut session, &artifacts, &upload_id),
        OperationObservation::Conflict(ExternalConflict::ForgeAssetLength { .. })
    ));
    session.invalidate_after_effect();
    runner.push_github(
        0,
        200,
        serde_json::json!({
            "tag_name": release.tag(),
            "draft": true,
            "assets": [github_asset(upload_slot, None)]
        }),
    );
    assert!(matches!(
        observe_prepared(&mut session, &artifacts, &upload_id),
        OperationObservation::Exact(_)
    ));

    session.invalidate_after_effect();
    runner.push_github(
        0,
        200,
        serde_json::json!({
            "tag_name": release.tag(),
            "draft": false,
            "assets": forge_slots.iter().map(|slot| github_asset(slot, None)).collect::<Vec<_>>()
        }),
    );
    assert!(matches!(
        observe_prepared(&mut session, &artifacts, &publish_id),
        OperationObservation::Exact(_)
    ));

    let cargo_slot = match &cargo_id {
        ReleaseOperationId::RegistryArtifactPublish { slot, .. } => slot,
        _ => unreachable!(),
    };
    let (cargo_digest, _) = expectations.artifact(cargo_slot).unwrap();
    runner.push_http(200, serde_json::json!({"version":{"checksum":"f".repeat(64)}}));
    assert!(matches!(
        observe_prepared(&mut session, &artifacts, &cargo_id),
        OperationObservation::Conflict(ExternalConflict::RegistryDigest { .. })
    ));
    runner.push_http(200, serde_json::json!({"version":{"checksum":cargo_digest.as_str()}}));
    assert!(matches!(
        observe_prepared(&mut session, &artifacts, &cargo_id),
        OperationObservation::Exact(_)
    ));

        let npm_slot = match &npm_id {
            ReleaseOperationId::RegistryArtifactPublish { slot, .. } => slot,
            _ => unreachable!(),
        };
        let npm_bytes = slot_bytes(npm_slot);
        runner.npm.lock().unwrap().push_back(NpmPlan {
            output: CommandOutput {
                exit_code: Some(0),
                stdout: serde_json::json!([{
                    "filename":npm_slot.file_name(),
                    "size":npm_bytes.len() + 1
                }])
                .to_string(),
                stderr: String::new(),
            },
            file: Some((npm_slot.file_name().to_string(), [npm_bytes.clone(), vec![0]].concat())),
        });
        assert!(matches!(
            observe_prepared(&mut session, &artifacts, &npm_id),
            OperationObservation::Conflict(ExternalConflict::RegistryLength { .. })
        ));
        runner.npm.lock().unwrap().push_back(NpmPlan {
            output: CommandOutput {
                exit_code: Some(0),
                stdout: serde_json::json!([{"filename":npm_slot.file_name(),"size":npm_bytes.len()}]).to_string(),
                stderr: String::new(),
            },
            file: Some((npm_slot.file_name().to_string(), npm_bytes)),
        });
        assert!(matches!(
            observe_prepared(&mut session, &artifacts, &npm_id),
            OperationObservation::Exact(_)
        ));

        let pypi_slots = validated
            .intent()
            .slots()
            .iter()
            .filter(|slot| {
                matches!(slot, ReleaseArtifactSlot::RegistryPackage { package, .. } if package.ecosystem() == Ecosystem::Pypi)
            })
            .cloned()
            .collect::<Vec<_>>();
        let pypi_file = |slot: &ReleaseArtifactSlot| {
            let (digest, length) = expectations.artifact(slot).unwrap();
            serde_json::json!({"filename":slot.file_name(),"size":length,"digests":{"sha256":digest.as_str()}})
        };
        session.invalidate_after_effect();
        runner.push_http(200, serde_json::json!({"urls":[pypi_file(&pypi_slots[0])]}));
        assert!(matches!(
            observe_prepared(&mut session, &artifacts, &pypi_id),
            OperationObservation::Incomplete(_)
        ));
        session.invalidate_after_effect();
        runner.push_http(
            200,
            serde_json::json!({"urls":[pypi_file(&pypi_slots[0]),pypi_file(&pypi_slots[1])]}),
        );
        assert!(matches!(
            observe_prepared(&mut session, &artifacts, &pypi_id),
            OperationObservation::Exact(_)
        ));

        run_git(
            root,
            &[
                "remote",
                "set-url",
                "origin",
                "https://github.com/attacker/substitution.git",
            ],
        );
        assert_eq!(
            observe_prepared(&mut session, &artifacts, &tag_id),
            OperationObservation::Unverifiable(ObservationFailure::TrustChanged {
                provider: ObservationProvider::Git,
            })
        );
    }
}
