        run_git(local.path(), &["config", "push.followTags", "true"]);
        let desired = TagName::parse("release-only-this-tag").unwrap();
        let unrelated = TagName::parse("release-must-not-follow").unwrap();
        let annotation = "Release no follow tags";
        let digest = TagAnnotationDigest::from_annotation(annotation);
        for name in [&desired, &unrelated] {
            git.create_tag(
                name.as_str(),
                &head,
                Some(annotation),
                crate::TagSignPolicy::ForceUnsigned,
                &permit(),
            )
            .unwrap();
        }

        assert_eq!(
            git.push_annotated_tag_and_confirm("origin", &desired, &head, &digest, &permit())
                .unwrap(),
