        );
        let refs = git_output(remote.path(), &["for-each-ref", "--format=%(refname)", "refs/tags"]);
        assert_eq!(
            refs.lines().collect::<Vec<_>>(),
            vec![format!("refs/tags/{}", desired.as_str())],
            "the remote tag roster must contain exactly the explicitly pushed release tag"
        );
