    #[test]
    fn remote_lightweight_tag_is_a_typed_conflict() {
        let (_remote, local, head) = remote_fixture();
        let runner = RealGitRunner;
        let git = GitAccess::discover(local.path(), &runner);
        let name = TagName::parse("release-lightweight").unwrap();
        run_git(local.path(), &["tag", name.as_str(), head.as_str()]);
        run_git(local.path(), &["push", "-q", "origin", name.as_str()]);

