/// The complete, remote-only result of comparing an annotated release tag to
/// its immutable expectation. A matching local tag is intentionally absent
/// from this vocabulary: it provides no proof about the configured remote.
#[derive(Clone, Debug, PartialEq, Eq)]
pub enum RemoteAnnotatedTagObservation {
    Absent,
    Exact,
    Conflict(RemoteAnnotatedTagConflict),
}

/// The closed reasons a remote tag can fail an exact annotated-tag check.
#[derive(Clone, Debug, PartialEq, Eq)]
pub enum RemoteAnnotatedTagConflict {
    /// The remote name resolves to a lightweight tag, which cannot carry the
    /// required annotation.
    LightweightTag,
    /// The tag peels to a commit other than the immutable release source.
    Target { expected: CommitSha, actual: CommitSha },
    /// The annotated tag object's declared target is inconsistent with the
    /// peeled remote ref, so its content cannot be accepted as proof.
    MalformedTarget,
    /// The tag object does not contain the expected annotated-tag header.
    MalformedTagObject,
    /// The tag annotation bytes differ from the release intent.
    Annotation {
        expected: TagAnnotationDigest,
        actual: TagAnnotationDigest,
    },
}

/// Why an existing local tag cannot be reused for an exact release retry.
///
/// Local refs are never provider evidence, but an exact local annotated tag
/// may remain after a crash between tag creation and push. Reusing only that
/// exact object makes the tag effect retryable without force-moving or
/// deleting a conflicting user ref.
#[derive(Clone, Debug, PartialEq, Eq, Error)]
pub enum LocalAnnotatedTagConflict {
    #[error("the existing ref is not a well-formed annotated commit tag")]
    NotAnnotated,
    #[error("the existing tag targets `{actual:?}`, expected `{expected:?}")]
    Target { expected: CommitSha, actual: CommitSha },
    #[error("the existing tag annotation differs from the approved annotation")]
    Annotation,
}

#[derive(Clone, Debug, Error, miette::Diagnostic, PartialEq, Eq)]
#[non_exhaustive]
pub enum VcsError {
    #[error("failed to discover Git repository at `{path}`: {message}")]
    #[diagnostic(code(E050), help("Ensure target directory is inside a valid Git repository."))]
    RepoNotFound { path: PathBuf, message: String },

    #[error("git error: {0}")]
    #[diagnostic(code(E051))]
    Git(String),

    #[error("reference `{ref_name}` was not found")]
    #[diagnostic(code(E052), help("Check if reference or tag exists in local or remote Git refs."))]
    RefNotFound { ref_name: String },

    #[error("tag glob pattern `{pattern}` is not a valid glob: {message}")]
    #[diagnostic(
        code(E053),
        help("Fix the glob syntax (e.g. balance `{{`/`}}` and `[`/`]`) or use a literal tag name.")
    )]
    InvalidGlob { pattern: String, message: String },

    #[error("local release tag `{name}` conflicts with the approved tag: {conflict}")]
    #[diagnostic(
        code(E058),
        help("Inspect the local tag. Callisto will reuse an exact crash-recovery tag but will never force-move or delete a conflicting ref.")
    )]
    LocalAnnotatedTagConflict {
        name: TagName,
        #[source]
