    fn convergence_recovers_from_lost_receipt_without_repeating_an_effect() {
        use crate::commands::release::{
            build_release_intent, validate_release_intent_with_state_directory, PreparedOperationView,
        };
        use crate::commands::release_execution::converge_release;
        use crate::commands::release_receipt_store::ReleaseReceiptStore;

        let (workspace, decision) = capability_workspace();
        let root = workspace.path();
        let runner = CapabilityRunner::default();
        let locator = crate::IgnoreWalkLocator::new(root);
        let intent = build_release_intent(root, &locator, &runner, &decision, "production").unwrap();
        let state_directory = tempfile::tempdir().unwrap();
        let validated =
            validate_release_intent_with_state_directory(root, &locator, &runner, Some(state_directory.path()), intent)
                .unwrap();
        let (_artifact_directory, artifacts) = artifact_fixture(&validated, &runner);
        let tag_id = validated
            .intent()
            .operations()
            .iter()
            .find_map(|operation| {
                matches!(operation.id(), ReleaseOperationId::ProductTag { .. }).then(|| operation.id().clone())
            })
            .unwrap();
        let (name, target, annotation) = match validated.prepared_operation(&tag_id).unwrap() {
            PreparedOperationView::ProductTag {
                name,
                target,
                annotation,
                ..
            } => (name.clone(), target.clone(), annotation.to_string()),
            _ => unreachable!(),
        };
        runner.set_remote_tag_after_push(&name, &target, &annotation);

        // Initial canonical pass plus mandatory final pass.
        queue_exact_convergence_passes(&runner, &validated, &artifacts, 2);
        let receipts = tempfile::tempdir().unwrap();
        let receipt_path = receipts.path().join("receipt.json");
        let failing = ReleaseReceiptStore::with_writer(&receipt_path, FailReceiptWrite);
        let permit = callisto_model::ApplyPermit::force_for_tests();
        assert!(matches!(
            converge_release(&validated, &artifacts, &failing, &permit),
            Err(GraphError::ReleaseStateWrite { .. })
        ));
        assert!(!receipt_path.exists());
        let push_count_after_failure = runner
            .calls
            .lock()
            .unwrap()
            .iter()
            .filter(|(program, args)| program == "git" && args.first().is_some_and(|argument| argument == "push"))
            .count();
        assert_eq!(
            push_count_after_failure, 1,
            "one proven-missing tag gets one effect attempt"
        );

        // The lost receipt authorizes nothing. Fresh observation sees every
        // operation exact and writes a receipt without repeating the tag push.
        queue_exact_convergence_passes(&runner, &validated, &artifacts, 2);
        let production = ReleaseReceiptStore::new(&receipt_path);
        let receipt = converge_release(&validated, &artifacts, &production, &permit).unwrap();
        assert_eq!(receipt.operations().len(), validated.intent().operations().len());
        let push_count_after_recovery = runner
            .calls
            .lock()
            .unwrap()
            .iter()
            .filter(|(program, args)| program == "git" && args.first().is_some_and(|argument| argument == "push"))
            .count();
        assert_eq!(
            push_count_after_recovery, 1,
            "recovery must not repeat an externally exact effect"
        );
        let decoded: callisto_model::CompleteObservationReceipt =
            serde_json::from_str(&std::fs::read_to_string(&receipt_path).unwrap()).unwrap();
        decoded
            .validate_for_intent(validated.intent(), &artifacts.expectations())
            .unwrap();

        let calls = runner.calls.lock().unwrap();
        assert_eq!(
            calls.iter().filter(|(program, _)| program == "curl").count(),
            8,
            "each invocation performs an initial and independent final Cargo/PyPI pass"
        );
    }
