    /// Creates the exact local annotated tag, or proves that an existing tag
    /// is identical and can be reused after a crash. This never deletes or
    /// force-moves a ref.
    pub(crate) fn ensure_local_annotated_tag(
        &self,
        name: &TagName,
        target_sha: &CommitSha,
        annotation: &str,
        sign: crate::TagSignPolicy,
        permit: &ApplyPermit,
    ) -> Result<(), VcsError> {
        let reference = format!("refs/tags/{}", name.as_str());
        let exists = self.runner.run(
            "git",
            &["show-ref", "--verify", "--quiet", "--", &reference],
            &self.root,
        )?;
        match exists.exit_code {
            Some(1) => return self.create_tag(name.as_str(), target_sha, Some(annotation), sign, permit),
            Some(0) => {}
            _ => return Err(remote_command_error("git show-ref", &exists)),
        }

        let object = self.runner.run(
            "git",
            &["--no-replace-objects", "cat-file", "-p", "--", &reference],
            &self.root,
        )?;
        if !object.success() {
            return Err(remote_command_error("git cat-file", &object));
        }
        let (actual_target, actual_annotation) =
            parse_annotated_tag_object(&object.stdout).map_err(|_| VcsError::LocalAnnotatedTagConflict {
                name: name.clone(),
                conflict: LocalAnnotatedTagConflict::NotAnnotated,
            })?;
        if actual_target != *target_sha {
            return Err(VcsError::LocalAnnotatedTagConflict {
                name: name.clone(),
                conflict: LocalAnnotatedTagConflict::Target {
                    expected: target_sha.clone(),
                    actual: actual_target,
                },
            });
        }
        if TagAnnotationDigest::from_tag_object_message(actual_annotation.as_bytes())
            != TagAnnotationDigest::from_annotation(annotation)
        {
            return Err(VcsError::LocalAnnotatedTagConflict {
                name: name.clone(),
                conflict: LocalAnnotatedTagConflict::Annotation,
            });
        }
        Ok(())
    }

