 831	fn require_cargo_upload_success(args: &[&str], output: callisto_model::CommandOutput) -> Result<(), GraphError> {
 832	    if !output.success() {
 833	        return require_command_success("curl", args, output);
 834	    }
 835	    let response: serde_json::Value = serde_json::from_str(&output.stdout).map_err(|_| GraphError::ReleaseCommand {
 836	        program: "curl".to_string(),
 837	        args: args.iter().map(ToString::to_string).collect(),
 838	        failure: CommandFailure::MalformedOutput {
 839	            detail: "Cargo registry returned a successful HTTP status with a non-JSON body".to_string(),
 840	        },
 841	    })?;
 842	    let object = response.as_object().ok_or_else(|| GraphError::ReleaseCommand {
 843	        program: "curl".to_string(),
 844	        args: args.iter().map(ToString::to_string).collect(),
 845	        failure: CommandFailure::MalformedOutput {
 846	            detail: "Cargo registry response is not a JSON object".to_string(),
 847	        },
 848	    })?;
 849	    match object.get("errors") {
 850	        None => Ok(()),
 851	        Some(serde_json::Value::Array(errors)) if errors.is_empty() => Ok(()),
 852	        Some(serde_json::Value::Array(errors)) => Err(GraphError::ReleaseCommand {
 853	            program: "curl".to_string(),
 854	            args: args.iter().map(ToString::to_string).collect(),
 855	            failure: CommandFailure::ProviderRejected {
 856	                detail: format!("Cargo registry returned {} error object(s)", errors.len()),
 857	            },
 858	        }),
 859	        Some(_) => Err(GraphError::ReleaseCommand {
 860	            program: "curl".to_string(),
 861	            args: args.iter().map(ToString::to_string).collect(),
 862	            failure: CommandFailure::MalformedOutput {
 863	                detail: "Cargo registry `errors` field is not an array".to_string(),
 864	            },
 865	        }),
 866	    }
 867	}
