  63	    /// Creates the exact local annotated tag, or proves that an existing tag
  64	    /// is identical and can be reused after a crash. This never deletes or
  65	    /// force-moves a ref.
  66	    pub(crate) fn ensure_local_annotated_tag(
  67	        &self,
  68	        name: &TagName,
  69	        target_sha: &CommitSha,
  70	        annotation: &str,
  71	        sign: crate::TagSignPolicy,
  72	        permit: &ApplyPermit,
  73	    ) -> Result<(), VcsError> {
  74	        let reference = format!("refs/tags/{}", name.as_str());
  75	        let exists = self.runner.run(
  76	            "git",
  77	            &["show-ref", "--verify", "--quiet", "--", &reference],
  78	            &self.root,
  79	        )?;
  80	        match exists.exit_code {
  81	            Some(1) => return self.create_tag(name.as_str(), target_sha, Some(annotation), sign, permit),
  82	            Some(0) => {}
  83	            _ => return Err(remote_command_error("git show-ref", &exists)),
  84	        }
  85	
  86	        let object = self.runner.run(
  87	            "git",
  88	            &["--no-replace-objects", "cat-file", "-p", "--", &reference],
  89	            &self.root,
  90	        )?;
  91	        if !object.success() {
  92	            return Err(remote_command_error("git cat-file", &object));
  93	        }
  94	        let (actual_target, actual_annotation) =
  95	            parse_annotated_tag_object(&object.stdout).map_err(|_| VcsError::LocalAnnotatedTagConflict {
  96	                name: name.clone(),
  97	                conflict: LocalAnnotatedTagConflict::NotAnnotated,
  98	            })?;
  99	        if actual_target != *target_sha {
 100	            return Err(VcsError::LocalAnnotatedTagConflict {
 101	                name: name.clone(),
 102	                conflict: LocalAnnotatedTagConflict::Target {
 103	                    expected: target_sha.clone(),
 104	                    actual: actual_target,
 105	                },
 106	            });
 107	        }
 108	        if TagAnnotationDigest::from_tag_object_message(actual_annotation.as_bytes())
 109	            != TagAnnotationDigest::from_annotation(annotation)
 110	        {
 111	            return Err(VcsError::LocalAnnotatedTagConflict {
 112	                name: name.clone(),
 113	                conflict: LocalAnnotatedTagConflict::Annotation,
 114	            });
 115	        }
 116	        Ok(())
 117	    }
