    21	/// A private temporary copy of one already-validated artifact.
    22	pub(super) struct PrivateArtifactFile {
    23	    _directory: tempfile::TempDir,
    24	    path: PathBuf,
    25	}
    26	
    27	impl PrivateArtifactFile {
    28	    pub(super) fn new(file_name: &str, bytes: &[u8]) -> Result<Self, GraphError> {
    29	        let mut components = std::path::Path::new(file_name).components();
    30	        if !matches!(components.next(), Some(std::path::Component::Normal(_))) || components.next().is_some() {
    31	            return Err(invalid_artifact("artifact name is not one basename"));
    32	        }
    33	        let directory = tempfile::tempdir().map_err(|error| invalid_artifact(error.to_string()))?;
    34	        let path = directory.path().join(file_name);
    35	        std::fs::write(&path, bytes).map_err(|error| invalid_artifact(error.to_string()))?;
    36	        Ok(Self {
    37	            _directory: directory,
    38	            path,
    39	        })
    40	    }
    41	
    42	    pub(super) fn path(&self) -> &std::path::Path {
    43	        &self.path
    44	    }
    45	
    46	    /// Writes credential-free npm configuration which refers to the fixed
    47	    /// credential environment variable by name. The token itself never enters
    48	    /// a file or argv.
    49	    pub(super) fn write_npm_config(&self, registry: &str, token_env: &str) -> Result<(), GraphError> {
    50	        if !token_env
    51	            .bytes()
    52	            .all(|byte| byte.is_ascii_uppercase() || byte.is_ascii_digit() || byte == b'_')
    53	        {
    54	            return Err(invalid_artifact("npm credential environment name is not canonical"));
    55	        }
    56	        let parsed = url::Url::parse(registry).map_err(|error| invalid_artifact(error.to_string()))?;
    57	        let host = parsed
    58	            .host_str()
    59	            .ok_or_else(|| invalid_artifact("npm registry has no host"))?;
    60	        let mut authority = host.to_ascii_lowercase();
    61	        if let Some(port) = parsed.port() {
    62	            authority.push(':');
    63	            authority.push_str(&port.to_string());
    64	        }
    65	        let path = parsed.path().trim_matches('/');
    66	        let auth_scope = if path.is_empty() {
    67	            format!("//{authority}/")
    68	        } else {
    69	            format!("//{authority}/{path}/")
    70	        };
    71	        let source = format!(
    72	            "registry={registry}\nalways-auth=true\n{auth_scope}:_authToken=${{{token_env}}}\nignore-scripts=true\n"
    73	        );
    74	        std::fs::write(self._directory.path().join(".npmrc"), source)
    75	            .map_err(|error| invalid_artifact(error.to_string()))
    76	    }
    77	
    78	    pub(super) fn directory(&self) -> &std::path::Path {
    79	        self._directory.path()
    80	    }
    81	}
