    28	    pub(super) fn new(file_name: &str, bytes: &[u8]) -> Result<Self, GraphError> {
    29	        let mut components = std::path::Path::new(file_name).components();
    30	        if !matches!(components.next(), Some(std::path::Component::Normal(_))) || components.next().is_some() {
    31	            return Err(invalid_artifact("artifact name is not one basename"));
    32	        }
