    68	        } else {
    69	            format!("//{authority}/{path}/")
    70	        };
    71	        let source = format!(
    72	            "registry={registry}\nalways-auth=true\n{auth_scope}:_authToken=${{{token_env}}}\nignore-scripts=true\n"
    73	        );
