#[derive(Clone, Debug, PartialEq, Eq, Hash, Serialize, Deserialize, JsonSchema)]
#[serde(rename_all = "camelCase", tag = "kind", deny_unknown_fields)]
pub enum ReleaseOperationId {
    RegistryArtifactPublish {
        package: ReleasePackageId,
        version: Version,
        #[serde(flatten)]
        registry: RegistryBindingId,
        slot: ReleaseArtifactSlot,
    },
    ProductTag {
        release: ProductReleaseId,
        tag: String,
    },
    ForgePrepare {
        release: ProductReleaseId,
        repository: GitHubRepository,
    },
    ArtifactUpload {
        release: ProductReleaseId,
        slot: ReleaseArtifactSlot,
    },
    ForgePublish {
        release: ProductReleaseId,
        repository: GitHubRepository,
    },
}

impl ReleaseOperationId {
    pub fn release(&self) -> Option<&ProductReleaseId> {
        match self {
            Self::RegistryArtifactPublish { .. } => None,
            Self::ProductTag { release, .. }
            | Self::ForgePrepare { release, .. }

    pub fn line(&self) -> String {
        format!("{}  {}\n", self.digest, self.file_name)
    }
}

fn canonical_checksum_bytes(
    payloads: &ValidatedPayloadEntries,
    metadata_entry: &ReleaseArtifactEntry,
) -> Result<Vec<u8>, SuccessorError> {
    let expected_count = payloads.entries.len() + 1;
    let mut entries = payloads
        .entries
        .iter()
        .filter_map(|entry| match entry.slot {
            ReleaseArtifactSlot::RegistryPackage { .. } | ReleaseArtifactSlot::ProductAsset { .. } => {
                Some(ChecksumRosterEntry {
                    file_name: entry.slot.file_name().to_string(),
                    digest: entry.digest.clone(),
                })
            }
            ReleaseArtifactSlot::ChecksumManifest { .. } | ReleaseArtifactSlot::ReleaseMetadata { .. } => None,
        })
        .collect::<Vec<_>>();
    entries.push(ChecksumRosterEntry {
        file_name: metadata_entry.slot.file_name().to_string(),
        digest: metadata_entry.digest.clone(),
    });
    entries.sort_by(|left, right| left.file_name.cmp(&right.file_name));
    if entries.len() != expected_count
        || entries.iter().any(|entry| entry.file_name == CHECKSUM_FILE_NAME)
        || entries.windows(2).any(|pair| pair[0].file_name == pair[1].file_name)
    {
        return Err(SuccessorError::InvalidChecksumRoster);
    }
    Ok(entries
        .into_iter()
        .flat_map(|entry| entry.line().into_bytes())
        .collect())
}

/// Exact, provider-neutral facts retained only after graph has verified an
/// operation. Deliberately no endpoint, headers, stderr, or free-form
/// provider text can be represented here.
#[derive(Clone, Debug, PartialEq, Eq, Serialize, JsonSchema)]
#[serde(rename_all = "camelCase", tag = "kind", deny_unknown_fields)]
pub enum ReleaseObservationEvidence {
    RegistryArtifact {
        #[serde(rename = "schemaVersion")]
        schema_version: u8,
        package: ReleasePackageId,
        version: Version,
        #[serde(flatten)]
        registry: RegistryBindingId,
        slot: ReleaseArtifactSlot,
        digest: ArtifactDigest,
        #[serde(rename = "byteLength")]
        byte_length: u64,
    },
    RemoteTag {
        #[serde(rename = "schemaVersion")]
        schema_version: u8,
        release: ProductReleaseId,
        name: String,
        target: CommitSha,
        #[serde(rename = "annotationDigest")]
        annotation_digest: ArtifactDigest,
    },
    ForgePrepare {
        #[serde(rename = "schemaVersion")]
        schema_version: u8,
        release: ProductReleaseId,
        lifecycle: ForgePrepareLifecycle,
    },
    ForgePublish {
        #[serde(rename = "schemaVersion")]
        schema_version: u8,
        release: ProductReleaseId,
        #[serde(rename = "assetRosterDigest")]
        asset_roster_digest: ArtifactDigest,
    },
    ForgeAsset {
        #[serde(rename = "schemaVersion")]
        schema_version: u8,
        release: ProductReleaseId,
        slot: ReleaseArtifactSlot,
        digest: ArtifactDigest,
        #[serde(rename = "byteLength")]
        byte_length: u64,
    },
}

