    pub const SCHEMA_VERSION: u8 = 1;

    pub fn registry_artifact(
        package: ReleasePackageId,
        version: Version,
        registry: RegistryBindingId,
        slot: ReleaseArtifactSlot,
        digest: ArtifactDigest,
        byte_length: u64,
    ) -> Self {
        Self::RegistryArtifact {
            schema_version: Self::SCHEMA_VERSION,
            package,
            version,
            registry,
            slot,
            digest,
            byte_length,
        }
    }

    pub fn remote_tag(
        release: ProductReleaseId,
    ) -> Self {
        Self::ForgeAsset {
            schema_version: Self::SCHEMA_VERSION,
            release,
            slot,
            digest,
            byte_length,
        }
    }

    pub fn schema_version(&self) -> u8 {
        match self {
            Self::RegistryArtifact { schema_version, .. }
            | Self::RemoteTag { schema_version, .. }
            | Self::ForgePrepare { schema_version, .. }
            | Self::ForgePublish { schema_version, .. }
            | Self::ForgeAsset { schema_version, .. } => *schema_version,
        }
    }
}

