impl ProductReleaseId {
    pub fn new(product: ProductName, version: Version) -> Result<Self, SuccessorError> {
        if version.grammar() != VersionGrammar::SemVer {
            return Err(SuccessorError::NonSemverProductVersion {
                version: Box::new(version),
            });
        }
        Ok(Self { product, version })
    }

    pub fn from_coordinated_versions(
        product: ProductName,
        versions: impl IntoIterator<Item = Version>,
    ) -> Result<Self, SuccessorError> {
        let versions = versions.into_iter().collect::<Vec<_>>();
        let Some(first) = versions.first() else {
            return Err(SuccessorError::EmptyCoordinatedRoster);
        };
        let canonical = first.render();
        for candidate in &versions[1..] {
            if candidate.render() != canonical {
                return Err(SuccessorError::DivergentCoordinatedVersion {
                    expected: Box::new(first.clone()),
                    found: Box::new(candidate.clone()),
                });
            }
        }
        let version = Version::parse(canonical, VersionGrammar::SemVer).map_err(|_| {
            SuccessorError::NonSemverProductVersion {
                version: Box::new(first.clone()),
            }
        })?;
        Self::new(product, version)
    }

    pub fn product(&self) -> &ProductName {
        &self.product
    }

    pub fn version(&self) -> &Version {
        &self.version
    }

    pub fn tag(&self) -> String {
        format!("{}@{}", self.product, self.version.render())
    }
}

impl PartialOrd for ProductReleaseId {
    fn partial_cmp(&self, other: &Self) -> Option<Ordering> {
    // A fixed or linked group always converges every member to one
    // shared target version -- `solve_cascade` guarantees this when a
    // decision is derived from a version plan. Entries tag their own
    // group membership via `FixedGroup`/`LinkedGroup` reasons, so this
    // invariant is checkable from the decision's own content alone, with
    // no `GroupTable`/workspace-config access needed. Rejecting a
    // violation here means it also applies to a decision deserialized
    // from a committed release-decision file (`Deserialize` calls
    // `new()`), not just one freshly derived from a plan.
    let mut group_targets: BTreeMap<&str, &Version> = BTreeMap::new();
    for entry in &entries {
        for reason in &entry.reasons {
            let group_id = match reason {
                ReleaseInclusionReason::FixedGroup { group_id }
                | ReleaseInclusionReason::LinkedGroup { group_id } => group_id.as_str(),
                _ => continue,
            };
            match group_targets.get(group_id) {
                Some(existing) if existing.render() != entry.target_version.render() => {
                    return Err(ReleaseDecisionError::DivergentGroupTarget {
                        group_id: group_id.to_string(),
                        left: (*existing).clone(),
                        right: entry.target_version.clone(),
                    });
                }
                _ => {
                    group_targets.insert(group_id, &entry.target_version);
                }
            }
        }
    }

    let digest = decision_digest(&entries);
    Ok(Self {
            _ => None,
        }
    }

    pub fn validate(&self, release: &ProductReleaseId) -> Result<(), SuccessorError> {
        if !is_safe_artifact_component(self.file_name()) {
            return Err(SuccessorError::UnsafeArtifactSlot);
        }
        self.policy().validate()?;
        match self {
            Self::RegistryPackage { package, version, .. }
                if version.grammar() != package.ecosystem().version_grammar() =>
            {
                Err(SuccessorError::RegistryVersionGrammarMismatch)
            }
            Self::RegistryPackage { package, format, .. }
                if !format_matches_ecosystem(*format, package.ecosystem()) =>
            {
                Err(SuccessorError::RegistryFormatMismatch)
            }
            Self::RegistryPackage { format, file_name, .. } if !format_matches_file_name(*format, file_name) => {
    }

    fn from_wire(wire: ReleaseExecutionStateWire) -> Result<Self, ReleaseExecutionStateError> {
        if wire.schema_version != Self::SCHEMA_VERSION {
            return Err(ReleaseExecutionStateError::UnsupportedSchema {
                found: wire.schema_version,
            });
        }
        let mut operations = BTreeMap::new();
        for entry in wire.operations {
            if operations.insert(entry.operation.clone(), entry.state).is_some() {
                return Err(ReleaseExecutionStateError::DuplicateOperation {
                    id: Box::new(entry.operation),
                });
            }
        }
        Ok(Self {
            schema_version: wire.schema_version,
            intent_digest: wire.intent_digest,
            operations,
        })
    }
}

