    assert!(ProductReleaseId::new(
        ProductName::parse("callisto").unwrap(),
        Version::parse("1.2.3", VersionGrammar::Pep440).unwrap(),
    )
    .is_err());
    let cross_grammar = ProductReleaseId::from_coordinated_versions(
        ProductName::parse("callisto").unwrap(),
        [
            Version::parse("1.2.3", VersionGrammar::Pep440).unwrap(),
            Version::semver(1, 2, 3),
        ],
    )
    .unwrap();
    assert_eq!(cross_grammar.version(), &Version::semver(1, 2, 3));
    assert!(matches!(
        ProductReleaseId::from_coordinated_versions(
            ProductName::parse("callisto").unwrap(),
            [
                Version::semver(1, 2, 3),
                Version::parse("1.2.4", VersionGrammar::Pep440).unwrap(),
