        Err(SuccessorError::DivergentCoordinatedVersion { .. })
    ));
    let wire = serde_json::to_value(release()).unwrap();
    assert!(serde_json::from_value::<ProductReleaseId>(wire).is_ok());
    assert_eq!(
        serde_json::to_string(&ProductTarget::X86_64UnknownLinuxMusl).unwrap(),
        "\"x86_64-unknown-linux-musl\""
    );
}

