#[test]
fn successor_slot_and_operation_ordering_preserves_version_grammar() {
    let package = ReleasePackageId::parse("cargo/callisto-model").unwrap();
    let registry = registry_binding();
    let semver = Version::parse("1.2.3", VersionGrammar::SemVer).unwrap();
    let pep440 = Version::parse("1.2.3", VersionGrammar::Pep440).unwrap();
    assert_eq!(semver.render(), pep440.render());
    assert_ne!(semver, pep440);
    let semver_slot = ReleaseArtifactSlot::RegistryPackage {
        package: package.clone(),
        version: semver.clone(),
        registry: registry.clone(),
        format: RegistryArtifactFormat::CargoCrate,
        publication_policy: RegistryPublicationPolicy::cargo(),
        file_name: "callisto-model-1.2.3.crate".to_string(),
        provenance_policy: policy(),
    };
    let mut pep440_slot = semver_slot.clone();
    if let ReleaseArtifactSlot::RegistryPackage { version, .. } = &mut pep440_slot {
        *version = pep440.clone();
    }
    assert_ne!(semver_slot, pep440_slot);
    assert_ne!(semver_slot.cmp(&pep440_slot), Ordering::Equal);
    assert_eq!(BTreeSet::from([semver_slot.clone(), pep440_slot.clone()]).len(), 2);

    let semver_operation = ReleaseOperationId::RegistryArtifactPublish {
        package: package.clone(),
        version: semver,
        registry: registry.clone(),
        slot: semver_slot.clone(),
    };
    let pep440_outer_operation = ReleaseOperationId::RegistryArtifactPublish {
        package: package.clone(),
        version: pep440.clone(),
        registry: registry.clone(),
        slot: semver_slot,
    };
    let pep440_operation = ReleaseOperationId::RegistryArtifactPublish {
        package,
        version: pep440,
        registry,
        slot: pep440_slot,
    };
    assert_ne!(semver_operation, pep440_outer_operation);
    assert_ne!(semver_operation.cmp(&pep440_outer_operation), Ordering::Equal);
    assert_ne!(semver_operation, pep440_operation);
    assert_ne!(semver_operation.cmp(&pep440_operation), Ordering::Equal);
    assert_eq!(
        BTreeSet::from([semver_operation, pep440_outer_operation, pep440_operation]).len(),
        3
    );
}

