    let operations = intent
        .operations
        .iter()
        .enumerate()
        .map(|(index, operation)| ObservedOperation {
            operation: operation.id.clone(),
            evidence: match &operation.id {
                ReleaseOperationId::RegistryArtifactPublish {
                    package,
                    version,
                    registry,
                    slot,
                } => ReleaseObservationEvidence::registry_artifact(
                    package.clone(),
                    version.clone(),
                    registry.clone(),
                    slot.clone(),
                    expected.entries[slot].0.clone(),
                    expected.entries[slot].1,
