#[test]
fn mixed_ecosystem_durable_release_round_trip_preserves_native_version_grammars() {
    let release = release();
    let destination = destination();
    let descriptors = [
        (
            ReleasePackageId::parse("cargo/callisto").unwrap(),
            RegistryArtifactFormat::CargoCrate,
            RegistryPublicationPolicy::cargo(),
            "callisto-1.2.3.crate",
        ),
        (
            ReleasePackageId::parse("npm/callisto").unwrap(),
            RegistryArtifactFormat::NpmTarball,
            RegistryPublicationPolicy::npm(NpmAccess::Public, "latest").unwrap(),
            "callisto-1.2.3.tgz",
        ),
        (
            ReleasePackageId::parse("pypi/callisto").unwrap(),
            RegistryArtifactFormat::PythonWheel,
            RegistryPublicationPolicy::pypi(),
            "callisto-1.2.3-py3-none-any.whl",
        ),
    ];
    let mut approved = Vec::new();
    let mut release_slots = slots(&release);
    let mut packages = Vec::new();
    for (package, format, publication_policy, file_name) in descriptors {
        let registry = destination.registry_for(package.ecosystem()).unwrap().clone();
        let version = Version::parse(release.version.render(), package.ecosystem().version_grammar()).unwrap();
        approved.push(
            ApprovedRegistryArtifact::new(
                package.clone(),
                registry.clone(),
                format,
                publication_policy.clone(),
                file_name,
            )
            .unwrap(),
        );
        release_slots.push(ReleaseArtifactSlot::RegistryPackage {
            package: package.clone(),
            version,
            registry,
            format,
            publication_policy,
            file_name: file_name.to_string(),
            provenance_policy: policy(),
        });
        packages.push(package);
    }
    let intent = ReleaseIntent::new(
        decision_for(&release, packages),
        release.clone(),
        commit(),
        destination.clone(),
        approved,
        operations_for(&release, &destination, &release_slots),
        release_slots,
    )
    .unwrap();
    let manifest = manifest_for(&intent);
    let receipt = observation_fixture_for(intent.clone()).receipt();

    let decoded_intent: ReleaseIntent = serde_json::from_slice(&serde_json::to_vec(&intent).unwrap()).unwrap();
    let decoded_manifest: ReleaseArtifactManifest =
        serde_json::from_slice(&serde_json::to_vec(&manifest).unwrap()).unwrap();
    let decoded_receipt: CompleteObservationReceipt =
        serde_json::from_slice(&serde_json::to_vec(&receipt).unwrap()).unwrap();
    let expected = ObservationExpectations::from_manifest(&decoded_intent, &decoded_manifest).unwrap();
    decoded_receipt.validate_for_intent(&decoded_intent, &expected).unwrap();

    let pypi = ReleasePackageId::parse("pypi/callisto").unwrap();
    assert_eq!(
        decoded_intent
            .decision
            .entries
            .iter()
            .find(|entry| entry.package == pypi)
            .unwrap()
            .target_version
            .grammar(),
        VersionGrammar::Pep440
    );
    for slot in decoded_intent
        .slots
        .iter()
        .chain(decoded_manifest.entries.iter().map(|entry| &entry.slot))
    {
        if let ReleaseArtifactSlot::RegistryPackage { package, version, .. } = slot {
            if package == &pypi {
                assert_eq!(version.grammar(), VersionGrammar::Pep440);
            }
        }
    }
    for observed in decoded_receipt.operations() {
        if let ReleaseObservationEvidence::RegistryArtifact {
            package, version, slot, ..
        } = &observed.evidence
        {
            if package == &pypi {
                assert_eq!(version.grammar(), VersionGrammar::Pep440);
                assert!(matches!(
                    slot,
                    ReleaseArtifactSlot::RegistryPackage { version, .. }
                        if version.grammar() == VersionGrammar::Pep440
                ));
            }
        }
    }
}

