                    program: program.to_string(),
                    args: args.iter().map(|argument| argument.to_string()).collect(),
                    timeout,
                    staged_bytes: std::fs::read(staged_path).unwrap(),
                    npm_config: std::fs::read_to_string(cwd.join(".npmrc")).ok(),
                });
