 21 pub fn handle(args: ReleaseArgs, global: &GlobalArgs) -> Result<ExitCode, CliError> {
 22     match args {
 23         ReleaseArgs::Plan(args) => plan(args, global),
 24         ReleaseArgs::Inspect(args) => inspect(args, global),
 25         ReleaseArgs::Reconcile(args) => reconcile(args, global),
 26         ReleaseArgs::Execute(args) => execute(args, global),
 27     }
 28 }
