 85 fn inspect(args: ReleaseInspectArgs, global: &GlobalArgs) -> Result<ExitCode, CliError> {
 86     let value = read_json_file(&args.input)?;
 87     match global.format {
 88         OutputFormat::Json => write_json(&mut std::io::stdout(), &value)?,
 89         OutputFormat::Text => println!(
 90             "{}",
 91             serde_json::to_string_pretty(&value).expect("JSON value serializes")
 92         ),
 93     }
 94     Ok(ExitCode::SUCCESS)
 95 }
