118 fn execute(args: ReleaseExecuteArgs, global: &GlobalArgs) -> Result<ExitCode, CliError> {
119     let intent = read_intent(&args.intent)?;
120     let manifest = read_artifact_manifest(&args.artifact_manifest)?;
121     let runner = CliCommandRunner;
122     let root = canonical_root(global)?;
123     let locator = IgnoreWalkLocator::new(&root);
124     let explicit_state_directory = args
125         .receipt
126         .parent()
127         .filter(|parent| !parent.as_os_str().is_empty());
128     let permit = ApplyPermit::granted_unless_dry_run(global.dry_run).ok_or_else(|| {
129         CliError::Other(
130             "release execute cannot run with --dry-run; use release reconcile for a read-only readiness check"
131                 .to_string(),
132         )
133     })?;
134     let receipt = execute_release_from_artifacts(
135         &root,
136         &locator,
137         &runner,
138         explicit_state_directory,
139         intent,
140         manifest,
141         &args.artifact_dir,
142         &args.receipt,
143         &permit,
144     )?;
145     match global.format {
146         OutputFormat::Json => write_json(&mut std::io::stdout(), &receipt)?,
147         OutputFormat::Text => println!("Release receipt saved to {}", args.receipt.display()),
148     }
149     Ok(ExitCode::SUCCESS)
150 }
