 97 fn reconcile(args: ReleaseReconcileArgs, global: &GlobalArgs) -> Result<ExitCode, CliError> {
 98     let intent = read_intent(&args.intent)?;
 99     let manifest = read_artifact_manifest(&args.artifact_manifest)?;
100     let runner = CliCommandRunner;
101     let root = canonical_root(global)?;
102     let locator = IgnoreWalkLocator::new(&root);
103     let report =
104         reconcile_release_from_artifacts(&root, &locator, &runner, None, intent, manifest, &args.artifact_dir)?;
105     let ready = report.is_ready();
106     match global.format {
107         OutputFormat::Json => write_json(&mut std::io::stdout(), &report)?,
108         OutputFormat::Text => {
