152 fn canonical_root(global: &GlobalArgs) -> Result<std::path::PathBuf, CliError> {
153     dunce::canonicalize(&global.cwd).map_err(|source| CliError::Io {
154         source,
155         path: Some(global.cwd.clone()),
156     })
157 }
