159 fn read_intent(path: &std::path::Path) -> Result<ReleaseIntent, CliError> {
160     serde_json::from_value(read_json_file(path)?)
161         .map_err(|error| CliError::Other(format!("invalid release intent {}: {error}", path.display())))
162 }
163 
164 fn read_artifact_manifest(path: &std::path::Path) -> Result<ReleaseArtifactManifest, CliError> {
165     serde_json::from_value(read_json_file(path)?)
166         .map_err(|error| CliError::Other(format!("invalid artifact manifest {}: {error}", path.display())))
167 }
168 
169 fn read_json_file(path: &std::path::Path) -> Result<serde_json::Value, CliError> {
170     let content = std::fs::read_to_string(path).map_err(|source| CliError::Io {
171         source,
172         path: Some(path.to_path_buf()),
173     })?;
174     serde_json::from_str(&content)
175         .map_err(|error| CliError::Other(format!("invalid JSON in {}: {error}", path.display())))
176 }
177 
178 fn write_intent(path: &std::path::Path, intent: &ReleaseIntent, permit: &ApplyPermit) -> Result<(), CliError> {
179     let content = serde_json::to_string_pretty(intent).expect("release intent serializes") + "\n";
180     callisto_model::atomic::atomic_write(path, &content, permit).map_err(|source| CliError::Io {
181         source,
182         path: Some(path.to_path_buf()),
183     })?;
184     Ok(())
185 }
