219     fn format_error_json_structure_is_consistent_across_variants() {
220         let errors: &[CliError] = &[CliError::Other("first".to_string()), CliError::NotATty];
221         let jsons: Vec<serde_json::Value> = errors.iter().map(format_error_json).collect();
222         for json in &jsons {
223             assert_envelope_shape(json);
224         }
225         // Both must have the same top-level keys
226         let keys_0: std::collections::BTreeSet<String> =
227             jsons[0]["error"].as_object().unwrap().keys().cloned().collect();
228         let keys_1: std::collections::BTreeSet<String> =
229             jsons[1]["error"].as_object().unwrap().keys().cloned().collect();
