169 fn read_json_file(path: &std::path::Path) -> Result<serde_json::Value, CliError> {
170     let content = std::fs::read_to_string(path).map_err(|source| CliError::Io {
171         source,
172         path: Some(path.to_path_buf()),
173     })?;
174     serde_json::from_str(&content)
175         .map_err(|error| CliError::Other(format!("invalid JSON in {}: {error}", path.display())))
