118 fn execute(args: ReleaseExecuteArgs, global: &GlobalArgs) -> Result<ExitCode, CliError> {
119     let intent = read_intent(&args.intent)?;
120     let manifest = read_artifact_manifest(&args.artifact_manifest)?;
121     let runner = CliCommandRunner;
122     let root = canonical_root(global)?;
123     let locator = IgnoreWalkLocator::new(&root);
