129         CliError::Other(
130             "release execute cannot run with --dry-run; use release reconcile for a read-only readiness check"
131                 .to_string(),
132         )
133     })?;
134     let receipt = execute_release_from_artifacts(
135         &root,
136         &locator,
137         &runner,
138         explicit_state_directory,
139         intent,
140         manifest,
141         &args.artifact_dir,
142         &args.receipt,
143         &permit,
144     )?;
145     match global.format {
146         OutputFormat::Json => write_json(&mut std::io::stdout(), &receipt)?,
147         OutputFormat::Text => println!("Release receipt saved to {}", args.receipt.display()),
148     }
