 169         "[workspace]\nmembers = [\"crates/crate-a\", \"crates/crate-b\"]\nresolver = \"2\"\n",
 170     )
 171     .unwrap();
 172     for name in ["crate-a", "crate-b"] {
 173         fs::create_dir_all(root.join(format!("crates/{name}/src"))).unwrap();
 174         fs::write(
