 214         String::from_utf8_lossy(&add.stderr)
 215     );
 216     git(root, &["add", "."]);
 217     git(root, &["commit", "-m", "add release changeset"]);
 218 
 219     let version = callisto(root, &["version", "--emit-decision", DECISION_PATH]);
