 247 /// The original bug this whole redesign exists to fix: a fixed-group cascade
 248 /// bumps a sibling package with no changeset naming it directly. The prior
 249 /// re-derivation approach only trusted a direct changeset-to-package match
 250 /// and rejected exactly this commit shape in production.
 251 #[test]
 252 fn fixed_group_cascade_bump_without_direct_changeset_is_accepted() {
 253     let (dir, release_commit) = fixed_group_release_commit_fixture();
 254     let root = dir.path();
 255     let external = tempfile::tempdir().unwrap();
 256     let intent = external.path().join("release-intent.json");
 257 
 258     let plan = callisto(
 259         root,
 260         &[
 261             "release",
 262             "plan",
 263             "--from-release-commit",
 264             &release_commit,
 265             "--decision",
 266             DECISION_PATH,
 267             "--out",
 268             intent.to_str().unwrap(),
 269         ],
 270     );
 271     assert!(
 272         plan.status.success(),
 273         "release plan must accept a fixed-group cascade bump with no direct changeset: {}",
 274         String::from_utf8_lossy(&plan.stderr)
 275     );
 276     let value: serde_json::Value = serde_json::from_slice(&fs::read(&intent).unwrap()).unwrap();
 277     let packages = value["decision"]["entries"]
 278         .as_array()
 279         .unwrap()
 280         .iter()
 281         .map(|entry| entry["package"].as_str().unwrap().to_owned())
 282         .collect::<std::collections::BTreeSet<_>>();
 283     assert_eq!(
 284         packages,
 285         std::collections::BTreeSet::from(["cargo/crate-a".to_owned(), "cargo/crate-b".to_owned()]),
 286         "both fixed-group members must be authorized, not just the one with a direct changeset"
 287     );
 288 }
