 492 /// publishers make an ordering regression observable: any cargo, gh, or git
 493 /// push invocation creates the external-effects log.
 494 #[test]
 495 fn malformed_membership_before_execute_never_reaches_credentials_or_provider() {
 496     let (dir, release_commit) = release_commit_fixture();
 497     let external = tempfile::tempdir().unwrap();
 498     let root = dir.path();
 499     let planned_intent = plan_intent(root, external.path(), &release_commit);
 500     let planned: callisto_model::ReleaseIntentV1 = serde_json::from_slice(&fs::read(&planned_intent).unwrap()).unwrap();
 501     let entry = planned.decision.entries[0].clone();
 502     let slot = callisto_model::ArtifactSlotId::new(
 503         entry.package.clone(),
 504         entry.target_version.clone(),
 505         "x86_64-unknown-linux-gnu",
 506         "core-crate.tar.gz",
 507         callisto_model::GitHubRepository::parse("example/core-crate").unwrap(),
 508         ".github/workflows/release.yml",
 509         callisto_model::CommitSha::parse(&release_commit).unwrap(),
 510     )
 511     .unwrap();
 512     let mut operations = planned.operations.clone();
 513     operations.push(callisto_model::ReleaseOperation::artifact_upload(slot.clone(), vec![]).unwrap());
 514     let intent = callisto_model::ReleaseIntentV1::new(
 515         planned.decision.clone(),
 516         planned.snapshot.clone(),
 517         planned.trust_profile,
 518         operations,
 519         vec![slot.clone()],
 520     )
 521     .unwrap();
 522     let artifact_dir = external.path().join("artifacts");
 523     fs::create_dir_all(&artifact_dir).unwrap();
 524     let bytes = b"attested core-crate bytes";
 525     fs::write(artifact_dir.join(&slot.asset_name), bytes).unwrap();
 526     let digest = callisto_model::ArtifactDigest::from_bytes(bytes);
 527     let source_commit = match &intent.snapshot.source {
 528         callisto_model::SourceIdentity::GitCommit { sha } => sha.clone(),
 529         callisto_model::SourceIdentity::HermeticContent { .. } => panic!("fixture must use Git commit trust"),
 530     };
 531     let manifest = callisto_model::ArtifactManifestV1::new(
 532         &intent,
 533         vec![callisto_model::ArtifactManifestEntryV1 {
 534             slot: slot.clone(),
 535             digest: digest.clone(),
 536             byte_length: bytes.len() as u64,
 537             attestation: callisto_model::GitHubArtifactAttestationV1 {
 538                 repository: slot.attestation_policy.repository.clone(),
 539                 workflow_path: slot.attestation_policy.workflow_path.clone(),
 540                 workflow_commit: slot.attestation_policy.workflow_commit.clone(),
 541                 subject_digest: digest,
 542                 source_commit,
 543             },
 544         }],
 545     )
 546     .unwrap();
 547     // Control: this exact slot, manifest, and bytes are attestation-eligible.
 548     // The old execute ordering called this verifier before revalidation, so
 549     // removing the production ordering repair would reach `gh` here.
 550     struct AttestationControl(std::sync::atomic::AtomicUsize);
 551     impl callisto_model::CommandRunner for AttestationControl {
 552         fn run(
 553             &self,
 554             program: &str,
 555             args: &[&str],
 556             _cwd: &Path,
 557         ) -> Result<callisto_model::CommandOutput, callisto_model::CommandError> {
 558             assert_eq!(program, "gh", "artifact verification must invoke only gh");
 559             assert!(
 560                 args.starts_with(&["attestation", "verify"]),
 561                 "control must exercise attestation verification, got {args:?}"
 562             );
 563             self.0.fetch_add(1, std::sync::atomic::Ordering::SeqCst);
 564             Ok(callisto_model::CommandOutput {
 565                 exit_code: Some(0),
 566                 stdout: String::new(),
 567                 stderr: String::new(),
 568             })
 569         }
 570     }
 571     let control = AttestationControl(std::sync::atomic::AtomicUsize::new(0));
 572     callisto_graph::commands::verify_artifact_manifest(&intent, &manifest, &artifact_dir, &control).unwrap();
 573     assert_eq!(
 574         control.0.load(std::sync::atomic::Ordering::SeqCst),
 575         1,
 576         "the control proves this fixture would invoke gh attestation verification before the repaired membership boundary"
 577     );
 578     let intent_path = external.path().join("attested-intent.json");
 579     let manifest_path = external.path().join("artifact-manifest.json");
 580     fs::write(&intent_path, serde_json::to_vec(&intent).unwrap()).unwrap();
 581     fs::write(&manifest_path, serde_json::to_vec(&manifest).unwrap()).unwrap();
 582     let state = external.path().join("release-state.json");
 583     let (bin, log, forge_marker, git_trace) = fake_publishers(external.path(), &release_commit, false);
 584 
 585     fs::write(root.join("Cargo.toml"), "[workspace]\nmembers = [\"").unwrap();
 586     let path = format!("{}:{}", bin.display(), std::env::var("PATH").unwrap());
 587     let output = Command::new(env!("CARGO_BIN_EXE_callisto"))
 588         .args(["--format", "json", "--cwd", root.to_str().unwrap()])
 589         .args([
 590             "release",
 591             "execute",
 592             "--intent",
 593             intent_path.to_str().unwrap(),
 594             "--state",
 595             state.to_str().unwrap(),
 596             "--artifact-manifest",
 597             manifest_path.to_str().unwrap(),
 598             "--artifact-dir",
 599             artifact_dir.to_str().unwrap(),
 600         ])
 601         .env("PATH", path)
 602         .env("NPM_TOKEN", "must-not-be-observed")
 603         .env("CALLISTO_TEST_LOG", &log)
 604         .env("CALLISTO_TEST_GIT_TRACE", &git_trace)
 605         .env("CALLISTO_TEST_FORGE_MARKER", &forge_marker)
 606         .env("CALLISTO_TEST_REAL_GIT", system_git())
 607         .output()
 608         .expect("release execute should run");
 609 
 610     assert!(!output.status.success(), "malformed membership must reject execution");
 611     let report: serde_json::Value = serde_json::from_slice(&output.stderr).unwrap();
 612     assert!(report["error"]["code"]
 613         .as_str()
 614         .is_some_and(|code| code.contains("E173")));
 615     assert!(
 616         !log.exists(),
 617         "the valid matching artifact roster and bytes would reach fake `gh attestation verify` under the old ordering; membership validation must stop it before credential-aware artifact verification or providers"
 618     );
 619     assert!(!forge_marker.exists());
 620     assert!(
 621         !state.exists(),
 622         "failed membership validation must not initialize execution state"
 623     );
 624 }
