 309 fn incomplete_authorizes_operation(id: &ReleaseOperationId, partial: &VerifiedPartialEvidence) -> bool {
 310     match id {
 311         ReleaseOperationId::RegistryArtifactPublish { slot, .. } => {
 312             partial.missing().contains(&MissingWork::RegistryArtifact(slot.clone()))
 313         }
 314         ReleaseOperationId::ForgePublish { release, .. } => {
 315             partial.missing().len() == 1
 316                 && partial
 317                     .missing()
 318                     .contains(&MissingWork::PublishForgeRelease(release.clone()))
 319         }
 320         ReleaseOperationId::ProductTag { .. }
 321         | ReleaseOperationId::ForgePrepare { .. }
 322         | ReleaseOperationId::ArtifactUpload { .. } => false,
 323     }
 324 }
