 326 fn readiness_state(observation: OperationObservation) -> ReleaseReadinessState {
 327     match observation {
 328         OperationObservation::Absent => ReleaseReadinessState::Absent,
 329         OperationObservation::Incomplete(partial) => ReleaseReadinessState::Incomplete {
 330             exact: partial.exact().to_vec(),
 331             missing: partial
 332                 .missing()
 333                 .iter()
 334                 .cloned()
 335                 .map(ReleaseMissingWork::from)
 336                 .collect(),
 337         },
 338         OperationObservation::Exact(evidence) => ReleaseReadinessState::Exact(evidence),
 339         OperationObservation::Conflict(conflict) => ReleaseReadinessState::Conflict(conflict.into()),
 340         OperationObservation::Unverifiable(failure) => ReleaseReadinessState::Unverifiable(failure.into()),
 341     }
 342 }
