 197 /// Converges one validated release from external truth and writes its strict
 198 /// final observation receipt atomically. No journal or prior receipt is read.
 199 pub(super) fn converge_release<W: ReleaseReceiptWriter>(
 200     capability: &ValidatedReleaseIntent<'_>,
 201     artifacts: &ValidatedArtifactManifest<'_, '_>,
 202     receipt_store: &ReleaseReceiptStore<W>,
 203     permit: &ApplyPermit,
 204 ) -> Result<CompleteObservationReceipt, GraphError> {
 205     let intent = capability.intent();
 206     let mut observations = ObservationSession::default();
 207     let mut provenance = BTreeMap::new();
 208 
 209     for operation in intent.operations() {
 210         let id = operation.id();
 211         let observed = observe_prepared(&mut observations, artifacts, id);
 212         if observation_satisfies_operation(id, &observed) {
 213             provenance.insert(id.clone(), ObservationProvenance::AlreadyPresent);
 214             continue;
 215         }
 216         require_dispatchable_missing_work(id, &observed)?;
 217         let outcome = capability.dispatch_prepared(artifacts, &mut observations, permit, id)?;
 218         provenance.insert(
 219             id.clone(),
 220             match outcome {
 221                 OperationOutcome::Published => ObservationProvenance::NewlyProduced,
 222                 OperationOutcome::AlreadySatisfied => ObservationProvenance::AlreadyPresent,
 223                 OperationOutcome::Failed | OperationOutcome::Blocked { .. } => {
 224                     return Err(GraphError::ReleaseOperationNotMissing { operation: id.clone() });
 225                 }
 226                 _ => return Err(GraphError::ReleaseOperationNotMissing { operation: id.clone() }),
 227             },
 228         );
 229     }
 230 
 231     observations.invalidate_after_effect();
 232     let mut exact = Vec::with_capacity(intent.operations().len());
 233     for operation in intent.operations() {
 234         let id = operation.id();
 235         let evidence = match observe_prepared(&mut observations, artifacts, id) {
 236             OperationObservation::Exact(evidence) => evidence,
 237             OperationObservation::Conflict(_) => {
 238                 return Err(GraphError::ReleaseObservationConflict { operation: id.clone() });
 239             }
 240             OperationObservation::Unverifiable(_) => {
 241                 return Err(GraphError::ReleaseObservationUnverifiable { operation: id.clone() });
 242             }
 243             OperationObservation::Absent | OperationObservation::Incomplete(_) => {
 244                 return Err(GraphError::ReleaseOperationNotMissing { operation: id.clone() });
 245             }
 246         };
 247         exact.push(ObservedOperation::new(
 248             id.clone(),
 249             evidence,
 250             provenance
 251                 .get(id)
 252                 .copied()
 253                 .unwrap_or(ObservationProvenance::AlreadyPresent),
 254         ));
 255     }
 256 
 257     let expectations = artifacts.expectations();
 258     let receipt = CompleteObservationReceipt::new(intent, &expectations, exact).map_err(|source| {
 259         GraphError::ReleaseInvariant {
 260             detail: format!("final exact observation roster did not form a receipt: {source}"),
 261         }
 262     })?;
 263     receipt_store.save(intent, &expectations, &receipt, permit)?;
 264     Ok(receipt)
 265 }
