 267 fn observation_satisfies_operation(id: &ReleaseOperationId, observed: &OperationObservation) -> bool {
 268     match observed {
 269         OperationObservation::Exact(_) => true,
 270         OperationObservation::Incomplete(partial) => match id {
 271             ReleaseOperationId::RegistryArtifactPublish { slot, .. } => {
 272                 !partial.missing().contains(&MissingWork::RegistryArtifact(slot.clone()))
 273             }
 274             _ => false,
 275         },
 276         OperationObservation::Absent | OperationObservation::Conflict(_) | OperationObservation::Unverifiable(_) => {
 277             false
 278         }
 279     }
 280 }
