 282 fn require_dispatchable_missing_work(
 283     id: &ReleaseOperationId,
 284     observed: &OperationObservation,
 285 ) -> Result<(), GraphError> {
 286     match observed {
 287         OperationObservation::Absent
 288             if matches!(
 289                 id,
 290                 ReleaseOperationId::RegistryArtifactPublish { .. }
 291                     | ReleaseOperationId::ProductTag { .. }
 292                     | ReleaseOperationId::ForgePrepare { .. }
 293                     | ReleaseOperationId::ArtifactUpload { .. }
 294             ) =>
 295         {
 296             Ok(())
 297         }
 298         OperationObservation::Incomplete(partial) if incomplete_authorizes_operation(id, partial) => Ok(()),
 299         OperationObservation::Conflict(_) => Err(GraphError::ReleaseObservationConflict { operation: id.clone() }),
 300         OperationObservation::Unverifiable(_) => {
 301             Err(GraphError::ReleaseObservationUnverifiable { operation: id.clone() })
 302         }
 303         OperationObservation::Absent | OperationObservation::Incomplete(_) | OperationObservation::Exact(_) => {
 304             Err(GraphError::ReleaseOperationNotMissing { operation: id.clone() })
 305         }
 306     }
 307 }
