  28 #[derive(Debug)]
  29 pub struct ReleaseReceiptStore<W = AtomicReleaseReceiptWriter> {
  30     path: PathBuf,
  31     writer: W,
  32 }
  33 
  34 impl ReleaseReceiptStore {
  35     pub fn new(path: impl Into<PathBuf>) -> Self {
  36         Self::with_writer(path, AtomicReleaseReceiptWriter)
  37     }
  38 }
