  40 impl<W: ReleaseReceiptWriter> ReleaseReceiptStore<W> {
  41     pub fn with_writer(path: impl Into<PathBuf>, writer: W) -> Self {
  42         Self {
  43             path: path.into(),
  44             writer,
  45         }
  46     }
  47 
  48     pub fn path(&self) -> &Path {
  49         &self.path
  50     }
