  52     pub fn save(
  53         &self,
  54         intent: &ReleaseIntent,
  55         expectations: &ObservationExpectations,
  56         receipt: &CompleteObservationReceipt,
  57         permit: &ApplyPermit,
  58     ) -> Result<(), GraphError> {
  59         receipt
  60             .validate_for_intent(intent, expectations)
