 370 /// Builds a release intent from a fresh root-bound observation.
 371 pub fn build_release_intent<L: ProjectLocator, R: CommandRunner>(
 372     root: &Path,
 373     locator: &L,
 374     runner: &R,
 375     decision: &ReleaseDecisionV1,
 376     profile_name: &str,
 377 ) -> Result<ReleaseIntent, GraphError> {
 378     let root = canonical_root(root)?;
 379     let workspace = Workspace::load(root.clone(), locator, runner)?;
 380     let source = observe_source(&workspace)?;
 381     let intent = derive_product_release(&workspace, decision, source.clone(), profile_name)?.intent;
 382 
 383     // Recheck after all input reads. A concurrent edit or checkout cannot be
 384     // authorized merely because it happened after the first check.
 385     if observe_source(&workspace)? != source {
 386         return Err(GraphError::ReleaseIntentStale {
 387             reason: StaleReason::source_identity_changed(),
 388         });
 389     }
 390     Ok(intent)
 391 }
 392 
 393 /// Re-observes root, config, package discovery, manifests, Git evidence, and
 394 /// the exact operation DAG before creating an opaque authorization capability.
 395 pub fn validate_release_intent<'a, L: ProjectLocator, R: CommandRunner>(
 396     root: &Path,
 397     locator: &L,
 398     runner: &'a R,
 399     received: ReleaseIntent,
 400 ) -> Result<ValidatedReleaseIntent<'a>, GraphError> {
 401     validate_release_intent_with_state_directory(root, locator, runner, None, received)
 402 }
 403 
 404 /// Validates an intent while placing its workspace lock under an explicit
 405 /// caller-owned state directory.
 406 ///
 407 /// CI callers that supply an explicit durable state file must use its parent
 408 /// here as well.  Otherwise validation would still depend on the runner's
 409 /// implicit platform state location, defeating hermetic job handoff.
 410 pub fn validate_release_intent_with_state_directory<'a, L: ProjectLocator, R: CommandRunner>(
 411     root: &Path,
 412     locator: &L,
 413     runner: &'a R,
 414     state_directory: Option<&Path>,
 415     received: ReleaseIntent,
 416 ) -> Result<ValidatedReleaseIntent<'a>, GraphError> {
 417     let root = canonical_root(root)?;
 418     let workspace = Workspace::load(root.clone(), locator, runner)?;
 419     let initial_trust = observe_git_trust(&workspace)?;
 420     let lock = ReleaseWorkspaceLock::acquire(&root, state_directory)?;
 421     let trust = observe_git_trust(&workspace)?;
 422     if trust != initial_trust {
 423         return Err(GraphError::ReleaseIntentStale {
 424             reason: StaleReason::trust_evidence_changed(),
 425         });
 426     }
 427     let source = trust.head().clone();
 428     let approved_decision = super::release_decision::derive_release_commit_decision(
 429         &workspace,
 430         received.source_commit(),
 431         Path::new(super::release_decision::CANONICAL_RELEASE_DECISION_PATH),
 432     )?;
 433     if &approved_decision != received.decision() {
 434         return Err(GraphError::ReleaseIntentStale {
 435             reason: StaleReason::intent_differs_from_fresh_derivation(),
 436         });
 437     }
 438     let prepared = derive_product_release(
 439         &workspace,
 440         &approved_decision,
 441         source.clone(),
 442         received.destination().profile_name(),
 443     )?;
 444     let final_trust = observe_git_trust(&workspace)?;
 445     if prepared.intent != received || final_trust != trust {
 446         return Err(GraphError::ReleaseIntentStale {
 447             reason: StaleReason::intent_differs_from_fresh_derivation(),
 448         });
 449     }
 450 
 451     Ok(ValidatedReleaseIntent {
 452         prepared: PreparedReleaseInputs {
 453             root,
 454             source,
 455             trust: final_trust,
 456             git_remote: prepared.git_remote,
 457             _lock: lock,
 458             operations: prepared.operations,
 459         },
 460         intent: received,
 461         runner,
 462     })
 463 }
 464 
 465 fn canonical_root(root: &Path) -> Result<std::path::PathBuf, GraphError> {
 466     dunce::canonicalize(root).map_err(|error| GraphError::ReleaseInputRead {
 467         path: root.to_path_buf(),
 468         message: error.to_string(),
 469     })
 470 }

