  1 //! Process-scoped advisory locks for durable release execution.
  2 //!
  3 //! The lock is operational evidence, never part of a serialized intent. It
  4 //! prevents cooperating Callisto processes from validating and executing the
  5 //! same checkout concurrently; Git trust is still re-observed before effects.
  6 
  7 #[cfg(not(target_arch = "wasm32"))]
  8 use std::fs::{self, File, OpenOptions};
  9 use std::path::{Path, PathBuf};
 10 
 11 #[cfg(not(target_arch = "wasm32"))]
 12 use fs2::FileExt;
 13 #[cfg(not(target_arch = "wasm32"))]
 14 use sha2::{Digest, Sha256};
 15 
 16 use crate::VcsError;
 17 
 18 /// An exclusive OS-backed advisory lock held for one canonical workspace.
 19 #[derive(Debug)]
 20 pub struct ReleaseWorkspaceLock {
 21     #[cfg(not(target_arch = "wasm32"))]
 22     file: File,
 23     path: PathBuf,
 24 }
 25 
 26 impl ReleaseWorkspaceLock {
 27     /// Acquires the workspace lock outside the checkout.
 28     ///
 29     /// `state_directory` exists for CI and tests. Without it, the lock lives
 30     /// under the platform's application-state location.
 31     pub fn acquire(canonical_root: &Path, state_directory: Option<&Path>) -> Result<Self, VcsError> {
 32         #[cfg(target_arch = "wasm32")]
 33         {
 34             let _ = (canonical_root, state_directory);
 35             return Err(VcsError::Git(
 36                 "durable release execution is unavailable on wasm32".to_string(),
 37             ));
 38         }
 39         #[cfg(not(target_arch = "wasm32"))]
 40         {
 41             let path = lock_path(canonical_root, state_directory)?;
 42             let parent = path.parent().expect("lock path always has a parent");
 43             fs::create_dir_all(parent)
 44                 .map_err(|_error| VcsError::Git("could not create release state directory".to_string()))?;
 45             let file = OpenOptions::new()
 46                 .create(true)
 47                 .read(true)
 48                 .write(true)
 49                 .truncate(false)
 50                 .open(&path)
 51                 .map_err(|_error| VcsError::Git("could not open release workspace lock".to_string()))?;
 52             file.try_lock_exclusive().map_err(classify_lock_acquire_error)?;
 53             Ok(Self { file, path })
 54         }
 55     }
 56 
 57     /// Returns the operational lock location for diagnostics and tests.
 58     pub fn path(&self) -> &Path {
 59         &self.path
 60     }
 61 }
 62 
 63 impl Drop for ReleaseWorkspaceLock {
 64     #[cfg(not(target_arch = "wasm32"))]
 65     fn drop(&mut self) {
 66         drop(self.file.unlock());
 67     }
 68     #[cfg(target_arch = "wasm32")]
 69     fn drop(&mut self) {}
 70 }
 71 
 72 /// Classifies a [`fs2::FileExt::try_lock_exclusive`] failure as either the
 73 /// expected "another process already holds this lock" contention (matched
 74 /// against [`fs2::lock_contended_error`]'s `ErrorKind`, the cross-platform
 75 /// signal fs2 itself uses to identify contention) or a genuine I/O failure
 76 /// (permission denied, disk full, filesystem lacks locking support, etc.),
 77 /// which is reported with its real cause instead of being misattributed to
 78 /// a held lock.
 79 #[cfg(not(target_arch = "wasm32"))]
 80 fn classify_lock_acquire_error(error: std::io::Error) -> VcsError {
 81     if error.kind() == fs2::lock_contended_error().kind() {
 82         VcsError::Git("another Callisto release already holds this workspace lock".to_string())
 83     } else {
 84         VcsError::Git(format!("could not acquire release workspace lock: {error}"))
 85     }
 86 }
 87 
 88 #[cfg(not(target_arch = "wasm32"))]
 89 fn lock_path(canonical_root: &Path, state_directory: Option<&Path>) -> Result<PathBuf, VcsError> {
 90     let base = match state_directory {
 91         Some(path) => path.to_path_buf(),
 92         None => platform_state_directory()?,
 93     };
 94     let digest = Sha256::digest(canonical_root.to_string_lossy().as_bytes());
 95     let key = format!("{:x}", digest);
 96     Ok(base.join("callisto").join("release-locks").join(format!("{key}.lock")))
 97 }
 98 
 99 /// Resolves Callisto's platform application-state base directory.
100 ///
101 /// This is operational routing only; callers must still key state by a
102 /// canonical workspace and durable intent rather than treating the location
103 /// as release authority.
104 pub fn platform_state_directory() -> Result<PathBuf, VcsError> {
105     #[cfg(target_arch = "wasm32")]
106     {
107         return Err(VcsError::Git(
108             "durable release execution is unavailable on wasm32".to_string(),
109         ));
110     }
111     #[cfg(not(target_arch = "wasm32"))]
112     {
113         #[cfg(target_os = "macos")]
114         let candidate = std::env::var_os("HOME").map(|home| PathBuf::from(home).join("Library/Application Support"));
115         #[cfg(target_os = "windows")]
116         let candidate = std::env::var_os("LOCALAPPDATA").map(PathBuf::from);
117         #[cfg(all(unix, not(target_os = "macos")))]
118         let candidate = std::env::var_os("XDG_STATE_HOME")
119             .map(PathBuf::from)
120             .or_else(|| std::env::var_os("HOME").map(|home| PathBuf::from(home).join(".local/state")));

