  30 fn plan(args: ReleasePlanArgs, global: &GlobalArgs) -> Result<ExitCode, CliError> {
  31     if global.dry_run {
  32         return Err(CliError::Other(
  33             "release plan needs an output file; remove --dry-run because planning is already read-only".to_string(),
  34         ));
  35     }
  36     let runner = CliCommandRunner;
  37     let workspace = load_workspace(global, &runner)?;
  38     let decision = match args.from_release_commit.as_deref() {
  39         Some(raw) => {
  40             let commit = callisto_model::CommitSha::parse(raw)
  41                 .map_err(|error| CliError::Other(format!("invalid merged release commit `{raw}`: {error}")))?;
  42             let decision_path = args
  43                 .decision
  44                 .as_deref()
  45                 .expect("clap requires --decision alongside --from-release-commit");
  46             derive_release_commit_decision(&workspace, &commit, decision_path)?
  47         }
  48         None => {
  49             let selections = args
  50                 .packages
  51                 .iter()
  52                 .map(|raw| {
  53                     ReleasePackageId::parse(raw).map_err(|error| {
  54                         CliError::Other(format!(
  55                             "invalid release package `{raw}`: {error}; use an exact ecosystem-qualified identity such as cargo/callisto-cli"
  56                         ))
  57                     })
  58                 })
  59                 .collect::<Result<Vec<_>, _>>()?;
  60             let inference = select_inference();
  61             let version_plan =
  62                 callisto_graph::commands::plan_version(&workspace, &inference, &VersionOptions::default())?;
  63             derive_selected_release_decision(&workspace, &version_plan, &selections)?
  64         }
  65     };
  66     let locator = IgnoreWalkLocator::new(&workspace.root);
  67     let intent = build_release_intent(&workspace.root, &locator, &runner, &decision, &args.profile)?;
  68     let permit = ApplyPermit::granted_unless_dry_run(global.dry_run)
  69         .expect("release plan rejects --dry-run before creating its explicit output");
  70     write_intent(&args.out, &intent, &permit)?;
  71     match global.format {
  72         OutputFormat::Json => write_json(&mut std::io::stdout(), &intent)?,
  73         OutputFormat::Text => println!("Wrote release intent {} to {}", intent.digest(), args.out.display()),
  74     }
  75     Ok(ExitCode::SUCCESS)
  76 }
