813 /// Root discovery starts at `--cwd`. A malformed authority in a nested
814 /// directory must therefore fail there, rather than being ignored while the
815 /// CLI climbs to this valid parent release workspace.
816 #[test]
817 fn nested_malformed_authority_never_selects_parent_for_release_planning() {
818     let (dir, release_commit) = release_commit_fixture();
819     let root = dir.path();
820     let child = root.join("nested-authority");
821     fs::create_dir_all(&child).unwrap();
822     let decision_before = fs::read(root.join(DECISION_PATH)).unwrap();
823     let head_before = git(root, &["rev-parse", "HEAD"]);
824 
825     for (ecosystem, authority_file, malformed) in [
826         ("Cargo", "Cargo.toml", "[workspace]\nmembers = [\""),
827         ("uv", "pyproject.toml", "[tool.uv.workspace"),
828         ("npm", "package.json", "{\"workspaces\": [}"),
829         ("pnpm", "pnpm-workspace.yaml", "packages: [\""),
830     ] {
831         let authority = child.join(authority_file);
832         fs::write(&authority, malformed).unwrap();
833         let external = tempfile::tempdir().unwrap();
834         let out = external.path().join("must-not-exist.json");
835         let result = callisto(
836             &child,
837             &[
838                 "release",
839                 "plan",
840                 "--profile",
841                 "production",
842                 "--from-release-commit",
843                 &release_commit,
844                 "--decision",
845                 DECISION_PATH,
846                 "--out",
847                 out.to_str().unwrap(),
848             ],
849         );
850 
851         assert!(
852             !result.status.success(),
853             "{ecosystem} malformed child must reject planning"
854         );
855         let report: serde_json::Value = serde_json::from_slice(&result.stderr).unwrap();
856         assert!(
857             report["error"]["code"]
858                 .as_str()
859                 .is_some_and(|code| code.contains("E173")),
860             "{ecosystem} must report membership parsing rather than select the parent: {report}"
861         );
862         assert!(!out.exists(), "{ecosystem} must not create an intent");
863         assert_eq!(fs::read(root.join(DECISION_PATH)).unwrap(), decision_before);
864         assert_eq!(git(root, &["rev-parse", "HEAD"]), head_before);
865         fs::remove_file(authority).unwrap();
866     }
867 }

