 335 fn cargo_crate_bytes(package: &str, version: &str) -> Vec<u8> {
 336     let encoder = flate2::write::GzEncoder::new(Vec::new(), flate2::Compression::default());
 337     let mut archive = tar::Builder::new(encoder);
 338     let manifest = format!(
 339         "[package]\nname = {package:?}\nversion = {version:?}\nedition = \"2021\"\n"
 340     );
 341     let mut header = tar::Header::new_gnu();
 342     header.set_size(manifest.len() as u64);
 343     header.set_mode(0o644);
 344     header.set_cksum();
 345     archive
 346         .append_data(
 347             &mut header,
 348             format!("{package}-{version}/Cargo.toml"),
 349             manifest.as_bytes(),
 350         )
 351         .unwrap();
 352     archive.into_inner().unwrap().finish().unwrap()
 353 }
