 355 fn artifact_fixture(intent_path: &Path, external: &Path) -> ArtifactFixture {
 356     use callisto_model::{
 357         ArtifactDigest, RegistryArtifactFormat, ReleaseArtifactEntry, ReleaseArtifactManifest,
 358         ReleaseArtifactSlot, ValidatedPayloadEntries,
 359     };
 360 
 361     let intent: callisto_model::ReleaseIntent = serde_json::from_slice(&fs::read(intent_path).unwrap()).unwrap();
 362     let directory = external.join("artifacts");
 363     fs::create_dir_all(&directory).unwrap();
 364     let mut entries = Vec::new();
 365     let mut cargo_digest = None;
 366     for slot in intent.slots().iter().filter(|slot| {
 367         matches!(
 368             slot,
 369             ReleaseArtifactSlot::RegistryPackage { .. } | ReleaseArtifactSlot::ProductAsset { .. }
 370         )
 371     }) {
 372         let bytes = match slot {
 373             ReleaseArtifactSlot::RegistryPackage {
 374                 package,
 375                 version,
 376                 format: RegistryArtifactFormat::CargoCrate,
 377                 ..
 378             } => cargo_crate_bytes(package.name(), &version.render()),
 379             _ => format!("attested payload for {}\n", slot.file_name()).into_bytes(),
 380         };
 381         let digest = ArtifactDigest::from_bytes(&bytes);
 382         if matches!(
 383             slot,
 384             ReleaseArtifactSlot::RegistryPackage {
 385                 format: RegistryArtifactFormat::CargoCrate,
 386                 ..
 387             }
 388         ) {
 389             cargo_digest = Some(digest.clone());
 390         }
 391         fs::write(directory.join(slot.file_name()), &bytes).unwrap();
 392         entries.push(
 393             ReleaseArtifactEntry::new(
 394                 slot.clone(),
 395                 digest,
 396                 bytes.len() as u64,
 397                 intent.source_commit().clone(),
 398                 slot.policy().clone(),
 399             )
 400             .unwrap(),
 401         );
 402     }
 403     let payloads = ValidatedPayloadEntries::new(&intent, entries).unwrap();
 404     let bundle = ReleaseArtifactManifest::complete_with_generated_files(&intent, &payloads).unwrap();
 405     for slot in intent.slots() {
 406         match slot {
 407             ReleaseArtifactSlot::ReleaseMetadata { .. } => {
 408                 fs::write(directory.join(slot.file_name()), bundle.metadata_bytes()).unwrap();
 409             }
 410             ReleaseArtifactSlot::ChecksumManifest { .. } => {
 411                 fs::write(directory.join(slot.file_name()), bundle.checksum_bytes()).unwrap();
 412             }
 413             _ => {}
 414         }
 415     }
 416     let manifest = external.join("artifact-manifest.json");
 417     fs::write(&manifest, serde_json::to_vec_pretty(bundle.manifest()).unwrap()).unwrap();
 418     let cargo_response = external.join("cargo-response.json");
 419     fs::write(
 420         &cargo_response,
 421         serde_json::to_vec(&serde_json::json!({
 422             "version": { "checksum": cargo_digest.expect("fixture has Cargo package").as_str() }
 423         }))
 424         .unwrap(),
 425     )
 426     .unwrap();
 427     let assets = bundle
 428         .manifest()
 429         .entries()
 430         .iter()
 431         .filter(|entry| entry.slot().release().is_some())
 432         .map(|entry| {
 433             serde_json::json!({
 434                 "name": entry.slot().file_name(),
 435                 "size": entry.byte_length(),
 436                 "digest": format!("sha256:{}", entry.digest()),
 437             })
 438         })
 439         .collect::<Vec<_>>();
 440     let github_response = external.join("github-response.json");
 441     fs::write(
 442         &github_response,
 443         serde_json::to_vec(&serde_json::json!({
 444             "tag_name": intent.product_release().tag(),
 445             "draft": false,
 446             "assets": assets,
 447         }))
 448         .unwrap(),
 449     )
 450     .unwrap();
 451     ArtifactFixture {
 452         intent,
 453         directory,
 454         manifest,
 455         cargo_response,
 456         github_response,
 457     }
 458 }
