 469     )
 470     .unwrap();
 471     fs::write(
 472         bin.join("curl"),
 473         "#!/bin/sh\ncase \" $* \" in *' --request GET '*) printf 'HTTP/1.1 200 OK\\r\\n\\r\\n'; cat \"$CALLISTO_TEST_CARGO_RESPONSE\"; exit 0;; esac\nprintf 'curl %s\\n' \"$*\" >> \"$CALLISTO_TEST_MUTATIONS\"\nexit 99\n",
 474     )
 475     .unwrap();
 476     fs::write(
 477         bin.join("gh"),
 478         "#!/bin/sh\nif [ \"$1\" = attestation ]; then exit 0; fi\nif [ \"$1\" = api ]; then printf 'HTTP/1.1 200 OK\\r\\n\\r\\n'; cat \"$CALLISTO_TEST_GITHUB_RESPONSE\"; exit 0; fi\nprintf 'gh %s\\n' \"$*\" >> \"$CALLISTO_TEST_MUTATIONS\"\nexit 99\n",
 479     )
 480     .unwrap();
 481     for program in [bin.join("git"), bin.join("curl"), bin.join("gh")] {
 482         fs::set_permissions(&program, fs::Permissions::from_mode(0o755)).unwrap();
 483     }
 484     (bin, mutations)
