 487 fn release_with_artifacts(
 488     root: &Path,
 489     command: &str,
 490     intent: &Path,
 491     fixture: &ArtifactFixture,
 492     bin: &Path,
 493     mutations: &Path,
 494     receipt: Option<&Path>,
 495 ) -> Output {
 496     let path = format!("{}:{}", bin.display(), std::env::var("PATH").unwrap());
 497     let mut process = Command::new(env!("CARGO_BIN_EXE_callisto"));
