 514         .env("CALLISTO_TEST_GITHUB_RESPONSE", &fixture.github_response);
 515     if let Some(receipt) = receipt {
 516         process.args(["--receipt", receipt.to_str().unwrap()]);
 517     }
 518     process.output().expect("release command should run")
 519 }
