 602 /// distinct from digest tampering: nothing here is individually corrupt, the
 603 /// two just disagree.
 604 #[test]
 605 fn release_plan_rejects_a_commit_whose_manifest_disagrees_with_its_own_decision() {
 606     let (dir, _release_commit) = release_commit_fixture();
 607     let root = dir.path();
 608 
 609     fs::write(
 610         root.join("crates/core/Cargo.toml"),
 611         "[package]\nname = \"core-crate\"\nversion = \"9.9.9\"\nedition = \"2021\"\n",
 612     )
 613     .unwrap();
 614     git(root, &["add", "-A"]);
 615     git(root, &["commit", "--amend", "--no-edit"]);
 616     let release_commit = git(root, &["rev-parse", "HEAD"]);
 617     git(root, &["checkout", "--detach", &release_commit]);
 618 
 619     let external = tempfile::tempdir().unwrap();
 620     let out = external.path().join("must-not-exist.json");
 621     let result = callisto(
 622         root,
 623         &[
