 90 fn reconcile(args: ReleaseReconcileArgs, global: &GlobalArgs) -> Result<ExitCode, CliError> {
 91     let intent = read_intent(&args.intent)?;
 92     let manifest = read_artifact_manifest(&args.artifact_manifest)?;
 93     let explicit_state_directory = args
 94         .artifact_manifest
 95         .parent()
 96         .filter(|parent| !parent.as_os_str().is_empty());
 97     let runner = CliCommandRunner;
 98     let root = canonical_root(global)?;
 99     let locator = IgnoreWalkLocator::new(&root);
100     let report = reconcile_release_from_artifacts(
101         &root,
102         &locator,
103         &runner,
104         explicit_state_directory,
105         intent,
106         manifest,
107         &args.artifact_dir,
108     )?;
109     let ready = report.is_ready();
110     match global.format {
111         OutputFormat::Json => write_json(&mut std::io::stdout(), &report)?,
112         OutputFormat::Text => {
113             println!("ready: {ready}");
114             for operation in report.operations() {
115                 println!(
116                     "{:?}: {:?}; recovery: {:?}",
117                     operation.operation(),
118                     operation.observation(),
119                     operation.recovery_action()
120                 );
121             }
122         }
123     }
124     Ok(if ready { ExitCode::SUCCESS } else { ExitCode::FAILURE })
125 }
