 40 pub fn escalate(diagnostics: &mut [Diagnostic], strict: bool, strict_graph: bool) {
  1 //! Observation-authoritative convergence for one validated release.
  2 //!
  3 //! No local journal is release authority. Every invocation derives authority
  4 //! from fresh provider observation, performs each proven-missing
  5 //! effect at most once, and persists a receipt only after a separate final
  6 //! pass proves the complete canonical operation roster exact.
  7 
  8 use std::{collections::BTreeMap, path::Path};
  9 
 10 use callisto_model::{
 11     ApplyPermit, CommandRunner, CompleteObservationReceipt, ObservationProvenance, ObservedOperation, OperationOutcome,
 12     ProductReleaseId, ReleaseArtifactManifest, ReleaseArtifactSlot, ReleaseIntent, ReleaseObservationEvidence,
 13     ReleaseOperationId,
 14 };
 15 use serde::{Deserialize, Serialize};
 16 
 17 use crate::{locate::ProjectLocator, GraphError};
 18 
 19 use super::{
 20     release::{validate_release_intent_with_lock_directory, ValidatedReleaseIntent},
 21     release_artifacts::{verify_artifact_manifest, ValidatedArtifactManifest},
 22     release_observation::{
 23         observe_prepared, ExternalConflict, MissingWork, ObservationFailure, ObservationProvider, ObservationSession,
 24         OperationObservation, VerifiedPartialEvidence,
 25     },
 26     release_receipt_store::{ReleaseReceiptStore, ReleaseReceiptWriter},
 27 };
