 29 /// Executes one release through the sealed validation, artifact-verification,
 30 /// observation, dispatch, and final-receipt pipeline.
 31 ///
 32 /// Callers provide only serialized model inputs and explicit filesystem
 33 /// locations. The capabilities that authorize provider effects remain private
 34 /// to the graph crate and cannot be retained or fabricated by a caller.
 35 #[allow(clippy::too_many_arguments)]
 36 pub fn execute_release_from_artifacts<L: ProjectLocator, R: CommandRunner>(
 37     root: &Path,
 38     locator: &L,
 39     runner: &R,
 40     explicit_lock_directory: Option<&Path>,
 41     intent: ReleaseIntent,
 42     artifact_manifest: ReleaseArtifactManifest,
 43     artifact_directory: &Path,
 44     receipt_path: &Path,
 45     permit: &ApplyPermit,
 46 ) -> Result<CompleteObservationReceipt, GraphError> {
 47     let capability =
 48         validate_release_intent_with_lock_directory(root, locator, runner, explicit_lock_directory, intent)?;
 49     let artifacts = verify_artifact_manifest(&capability, artifact_manifest, artifact_directory, runner)?;
 50     let receipt_store = ReleaseReceiptStore::new(receipt_path);
 51     converge_release(&capability, &artifacts, &receipt_store, permit)
 52 }
 53 
 54 /// A provider-neutral, secret-free observation state for one exact release
 55 /// operation.
 56 #[derive(Clone, Debug, PartialEq, Eq, Serialize, Deserialize)]
 57 #[serde(rename_all = "kebab-case", tag = "state", content = "summary")]
 58 pub enum ReleaseReadinessState {
 59     Absent,
 60     Incomplete {
760             .bytes()
761             .all(|byte| byte.is_ascii_alphanumeric() || matches!(byte, b'-' | b'_'))
762     {
763         return Err(successor::SuccessorError::MalformedRegistryKey { raw });
764     }
765     Ok(RegistryKey(raw))
766 }
767 
768 /// A provider effect outcome used only during one in-memory convergence pass.
769 #[derive(Clone, Copy, Debug, PartialEq, Eq, Serialize, Deserialize, JsonSchema)]
770 #[serde(rename_all = "camelCase", tag = "kind", deny_unknown_fields)]
771 #[non_exhaustive]
772 pub enum OperationOutcome {
773     Published,
774     AlreadySatisfied,
775 }
776 
777 fn is_safe_workflow_path(value: &str) -> bool {
778     value.starts_with(".github/workflows/")
779         && value.ends_with(".yml")
780         && !value.contains("..")
781         && value
782             .bytes()
783             .all(|byte| byte.is_ascii_alphanumeric() || matches!(byte, b'.' | b'_' | b'-' | b'/'))
784 }
785 
786 fn is_safe_artifact_component(value: &str) -> bool {
787     !value.is_empty()
788         && value.len() <= 255
789         && !value.contains("..")
790         && value
791             .bytes()
792             .all(|byte| byte.is_ascii_alphanumeric() || matches!(byte, b'.' | b'_' | b'-'))
793 }
